def _application_dir():
    """Return the directory beside the source script or packaged EXE."""
    try:
        if getattr(sys, "frozen", False):
            return os.path.dirname(os.path.abspath(sys.executable))
    except Exception:
        pass
    return os.path.dirname(os.path.abspath(__file__))


def _update_staging_root():
    """Return a disposable update staging directory outside the release folder."""
    return os.path.join(tempfile.gettempdir(), "CraftWorldModifier-update")


def _resource_path(name):
    """Resolve release resources, with a root-level development fallback."""
    filename = str(name or "").strip()
    if not filename:
        return os.path.join(_application_dir(), "")
    if getattr(sys, "frozen", False):
        candidates = [
            os.path.join(_application_dir(), "resources", filename),
            os.path.join(_application_dir(), filename),
        ]
    else:
        # In a source checkout the root files remain the edit/test targets;
        # the mirrored resources directory is used by the packaged EXE.
        candidates = [
            os.path.join(_application_dir(), filename),
            os.path.join(_application_dir(), "resources", filename),
        ]
    try:
        bundle_dir = getattr(sys, "_MEIPASS", "")
        if bundle_dir:
            candidates.insert(0, os.path.join(bundle_dir, "resources", filename))
            candidates.insert(1, os.path.join(bundle_dir, filename))
    except Exception:
        pass
    for candidate in candidates:
        if os.path.exists(candidate):
            return candidate
    return candidates[0]


def _read_windows_file_version(path):
    """Read the semantic file version when the PE actually provides one.

    CraftWorld's current Steam executable reports ``0.0.0.0`` and has no
    version resource, so callers must treat that value as unavailable instead
    of showing a misleading version number.
    """
    if os.name != "nt" or not path or not os.path.isfile(path):
        return ""
    try:
        version = ctypes.windll.version
        size = int(version.GetFileVersionInfoSizeW(str(path), None) or 0)
        if size <= 0:
            return ""
        blob = ctypes.create_string_buffer(size)
        if not version.GetFileVersionInfoW(str(path), 0, size, blob):
            return ""
        pointer = ctypes.c_void_p()
        length = ctypes.c_uint()
        if not version.VerQueryValueW(blob, "\\", ctypes.byref(pointer), ctypes.byref(length)):
            return ""
        if not pointer.value or int(length.value) < 16:
            return ""
        # VS_FIXEDFILEINFO: dwFileVersionMS at offset 8 and dwFileVersionLS
        # at offset 12.  Ignore the all-zero placeholder used by this game.
        raw = ctypes.string_at(pointer.value, int(length.value))
        version_ms, version_ls = struct.unpack_from("<II", raw, 8)
        major, minor = (version_ms >> 16) & 0xFFFF, version_ms & 0xFFFF
        build, revision = (version_ls >> 16) & 0xFFFF, version_ls & 0xFFFF
        if not any((major, minor, build, revision)):
            return ""
        return "%d.%d.%d.%d" % (major, minor, build, revision)
    except Exception:
        return ""


def _read_steam_build_id(exe_path):
    """Read the Steam appmanifest buildid associated with CraftWorld.exe."""
    if not exe_path:
        return ""
    try:
        common_dir = os.path.dirname(os.path.abspath(exe_path))
        steamapps = os.path.dirname(os.path.dirname(common_dir))
        if os.path.basename(steamapps).lower() != "steamapps":
            return ""
        manifest = os.path.join(steamapps, "appmanifest_248390.acf")
        if not os.path.isfile(manifest):
            return ""
        with open(manifest, "r", encoding="utf-8", errors="replace") as handle:
            text = handle.read(512 * 1024)
        match = re.search(r'"buildid"\s*"([0-9]+)"', text, re.IGNORECASE)
        return match.group(1) if match else ""
    except Exception:
        return ""


def _ensure_resource_import_path():
    """Make resources/block_data.py importable in an onedir package."""
    resource_file = _resource_path("block_data.py")
    resource_dir = os.path.dirname(resource_file)
    if resource_dir and resource_dir not in sys.path:
        sys.path.insert(0, resource_dir)


def _user_data_root():
    """Return the per-user data directory outside the portable EXE folder."""
    local_app_data = str(os.environ.get("LOCALAPPDATA") or "").strip()
    if not local_app_data:
        local_app_data = os.path.join(os.path.expanduser("~"), "AppData", "Local")
    return os.path.join(os.path.abspath(local_app_data), "CraftWorldModifier")


def _config_dir():
    """Return the hidden/system per-user configuration directory."""
    return os.path.join(_user_data_root(), "config")


def _package_config_dir():
    """Return packaged defaults from source, onedir or a one-file bundle."""
    return _resource_path("config")


def _hide_user_data_root(path):
    """Mark the per-user data directory hidden on Windows when possible."""
    if os.name != "nt":
        return
    try:
        ctypes.windll.kernel32.SetFileAttributesW(str(path), 0x2)
    except Exception:
        pass


def _read_json_object(path):
    try:
        with open(path, "r", encoding="utf-8") as handle:
            value = json.load(handle)
        return value if isinstance(value, dict) else None
    except (OSError, ValueError, json.JSONDecodeError):
        return None


