    PANDORA_CHEST_BEHAVIOUR_VTABLE_RVA = 0xBC4540
    PANDORA_SPAWNER_VTABLE_RVA = 0xBC46E4
    PANDORA_SPAWNER_TIMER_OFF = 0x118
