    _structure_runtime_history = []
    _structure_history_lock = threading.RLock()
    # The full map payload is large.  Keep only a lightweight identity for the
    # current map so the UI can refresh dwarf markers without serialising every
    # tile again.  A reconnect always clears this identity.
    _map_cache_signature = None
    _map_cache_key = ""
    # Reusable player-side settings. They are persisted in the per-user
    # %LOCALAPPDATA%\CraftWorldModifier\config\user_data.json store.
    # beside map pins so a game restart never loses a prepared item profile.
    ITEM_QUICK_LIMIT = 80
    MANA_MAX_LOCK_INTERVAL = 0.45
    MANA_MAX_LOCK_LIMIT = 10000000.0
    _mana_max_lock_guard = threading.RLock()
    _mana_max_lock_enabled = False
    _mana_max_lock_target = None
    _mana_max_lock_generation = 0
    # Timers are short-lived per-process controls.  Unlike the mana-cap lock,
    # these are deliberately not persisted: a new map creates new runtime
    # objects and should always begin unlocked.
    TIMER_LOCK_INTERVAL = 0.35
    _timer_lock_guard = threading.RLock()
    _timer_locks = {
        "countdown": {"enabled": False, "target": None, "generation": 0},
        "game_time": {"enabled": False, "target": None, "generation": 0},
        "game_speed": {"enabled": False, "target": None, "generation": 0},
        "pandora": {"enabled": False, "target": None, "generation": 0},
    }
    # Every game-memory write and process transition shares this gate.  It is
    # separate from the pause lock so ordinary writes cannot race a suspended
    # write batch or a disconnect/reconnect operation.
    _memory_write_lock = threading.RLock()
    _process_pause_lock = threading.RLock()
    # A pywebview API call can outlive the browser window that started it.
    # Keep a small, monotonic session marker so background workers from a
    # previous connection (or a closing window) can never publish stale data
    # into a newly opened UI session.
    _runtime_session_lock = threading.RLock()
    _runtime_session_generation = 0
    _runtime_shutdown = False
    # Every recurring writer/scanner is registered here.  Session generation
    # prevents stale memory access; the registry additionally lets shutdown
    # observe and reap workers instead of leaving anonymous daemon threads
    # behind after a WebView2 close or reconnect.
    _runtime_workers_lock = threading.RLock()
    _runtime_workers = set()
    _magic_scan_token = 0
    # Undo history is session-only. Runtime addresses never cross a reconnect;
    # offline entries additionally bind to the exact post-write SHA-256.
    OPERATION_HISTORY_LIMIT = 50
    _operation_history_lock = threading.RLock()
    _operation_history = []
    _operation_history_next_id = 1
    # This is deliberately session-only. A successful same-value readback
    # proves the current process/layout, not every later game restart.
    _stable_baseline_save_readback = None
    # Compatibility Doctor is deliberately read-only.  A successful connect
    # may still expose read-only pages, but every direct memory write must
    # pass this lightweight structural check first.  This protects against a
    # game update, a half-loaded save, and accidentally attaching to an
    # unrelated CraftWorld.exe build.
    _compatibility_doctor = {"ok": False, "write_ready": False,
                             "checked_pid": 0, "checks": [],
                             "summary": "尚未检查"}
    _compatibility_doctor_lock = threading.RLock()
    # The merged default/user configuration must never be read/rewritten
    # concurrently by two pywebview API calls.
    _config_lock = threading.RLock()
    # A previous modifier build overwrote these three bytes inside the save
    # writer.  The replacement corrupts the caller stack when the game saves.
    LEGACY_SAVE_PATCH_RVA = 0x003FC311
    LEGACY_SAVE_PATCH_BYTES = bytes((0x83, 0xC4, 0x0C))

    def __init__(self):
        """Create an isolated runtime session for one modifier window.

        Address tables and feature definitions remain class-level constants.
        Every value below changes while a game is connected, so it must belong
        to this API instance rather than leak into a later window or test.
        """
        self._v1_native_layout = dict(type(self)._v1_native_layout)
        self._shop_dialog_probe_cache = {"pid": 0, "address": 0, "at": 0.0}
        self._shop_dialog_probe_lock = threading.RLock()
        self.locks = {"gold": False, "mana": False, "xp": False}
        self._gold_economy_guard = threading.RLock()
        self._gold_economy_state = {"enabled": False, "mode": "floor", "floor": None,
                                    "ceiling": None, "fixed": None, "generation": 0}
        self._gold_economy_last_before = None
        self._gold_economy_last_after = None
        self._gold_economy_events = []
        self._mana_reserve_guard = threading.RLock()
        self._mana_reserve_state = {"enabled": False, "low_percent": 30.0,
                                    "restore_percent": 80.0, "generation": 0}
        self._pa1 = self._pa2 = False
        self._recipe_scanned = False
        self._recipe_cache = {}
        self._shop_data = {}
        self._skill_base_cache = self._skill_base_ver = None
        self._pet_house_original = None
        self._pet_infinite_original = {}
        self._portal_locks = {}
        self._portal_lock_guard = threading.RLock()
        self._portal_samples = {}
        self._portal_stability = {}
        self._v2_portal_objects = []
        self._v2_portal_scan_at = self._v2_portal_scan_pid = 0
        self._v2_portal_scan_lock = threading.RLock()
        self._magic_cache = {}
        self._magic_scan_ms = self._magic_process_id = 0
        self._magic_scan_running = self._magic_scan_completed = False
        self._magic_scan_error = ""
        self._magic_stable_values = {}
        self._native_magic_resources = {}
        self._task_runtime_candidates = {}
        self._task_runtime_candidates_generation = 0
        self._task_runtime_probe_baselines = {}
        self._pandora_cache = None
        self._pandora_cache_pid = self._pandora_scan_ms = 0
        self._pandora_forced_key = ""
        self._pandora_runtime_cache = {}
        self._pandora_runtime_scan_lock = threading.RLock()
        self._pandora_chest_seen_for_override = False
        self._pandora_empty_confirmations = 0
        self._time_controls_cache = None
        self._time_controls_scan_lock = threading.RLock()
        self._time_controls_last_failed_scan = 0.0
        self._time_controls_scan_error = ""
        self._time_controls_scan_token = 0
        self._time_controls_scan_running = False
        self._wave_portal_controller = None
        self._wave_portal_lock = threading.RLock()
        self._dwarf_population_controller = None
        self._dwarf_population_lock = threading.RLock()
        self._map_cache_signature = None
        self._map_cache_key = ""
        # Independent objects are process/save scoped.  Their native visual
        # occupancy masks are kept only in memory: a stale mask from another
        # save must never be drawn on a newly loaded map.
        self._world_object_occupancy_cache = {"scope": None, "items": {}}
        self._special_entity_item_cache = {"scope": None, "items": {}}
        self._structure_save_identity_cache = {"pid": 0, "value": ""}
        self._mana_max_lock_guard = threading.RLock()
        self._mana_max_lock_enabled = False
        self._mana_max_lock_target = None
        self._mana_max_lock_generation = 0
        self._timer_lock_guard = threading.RLock()
        self._timer_locks = {
            "countdown": {"enabled": False, "target": None, "generation": 0},
            "game_time": {"enabled": False, "target": None, "generation": 0},
            "game_speed": {"enabled": False, "target": None, "generation": 0},
            "pandora": {"enabled": False, "target": None, "generation": 0},
        }
        self._memory_write_lock = threading.RLock()
        self._process_pause_lock = threading.RLock()
        self._runtime_session_lock = threading.RLock()
        self._runtime_session_generation = 0
        self._runtime_shutdown = False
        self._runtime_workers_lock = threading.RLock()
        self._runtime_workers = set()
        self._magic_scan_token = 0
        self._operation_history_lock = threading.RLock()
        self._operation_history = []
        self._operation_history_next_id = 1
        self._stable_baseline_save_readback = None
        self._compatibility_doctor = {"ok": False, "write_ready": False,
                                      "checked_pid": 0, "checks": [], "summary": "尚未检查"}
        self._compatibility_doctor_lock = threading.RLock()
        self._config_lock = threading.RLock()
        self._pet_house_runtime_cache = {"pid": 0, "base": 0, "at": 0.0,
                                         "houses": [], "pets": []}
        self._pet_limit_override_original = None
        self._pet_limit_override_value = None
        self._other_feature_profile_cache = {"pid": 0, "exe_path": "", "profile": None}
        self._locked_items = {}
        self._lock_restore_active = False
        self._proof = {}
        self._dwarf_names = {}
        self._translations = {}
        self._categories = []
        self._category_overrides = {}
        self._item_config_loaded = False
        self._save_manager_lock = threading.RLock()
        self._save_restore_tokens = {}
        self._offline_save_edit_tokens = {}
        self._offline_save_edit_history_context = {}
        self._modifier_window = None
        self._window_is_maximized = False
        self._window_close_requested = False

    def _begin_runtime_session(self):
        """Invalidate old workers and allow requests for a new connection."""
        self._invalidate_runtime_operation_history('游戏连接已重置，旧运行时地址不再有效')
        with self._runtime_session_lock:
            self._runtime_session_generation += 1
            self._runtime_shutdown = False
            self._magic_scan_token += 1
            self._magic_scan_running = False
            self._magic_scan_completed = False
            self._time_controls_scan_token += 1
            self._time_controls_scan_running = False
            self._task_runtime_candidates = {}
            self._task_runtime_candidates_generation = self._runtime_session_generation
            self._task_runtime_probe_baselines = {}
            self._stable_baseline_save_readback = None
            return self._runtime_session_generation

    def _end_runtime_session(self):
        """Stop background workers before process/window teardown."""
        self._invalidate_runtime_operation_history('游戏已断开，运行时操作不能跨会话撤销')
        with self._runtime_session_lock:
            self._runtime_shutdown = True
            self._runtime_session_generation += 1
            self._magic_scan_token += 1
            self._magic_scan_running = False
            self._magic_scan_completed = False
            self._time_controls_scan_token += 1
            self._time_controls_scan_running = False
            self._task_runtime_candidates = {}
            self._task_runtime_candidates_generation = self._runtime_session_generation
            self._task_runtime_probe_baselines = {}
            self._stable_baseline_save_readback = None
            return self._runtime_session_generation

    @staticmethod
    def _operation_history_value(value):
        '''Keep history JSON-safe and prevent later callers mutating it.'''
        if isinstance(value, dict):
            return {str(key): Api._operation_history_value(item) for key, item in value.items()}
        if isinstance(value, (list, tuple)):
            return [Api._operation_history_value(item) for item in value]
        if isinstance(value, (str, int, float, bool)) or value is None:
            return value
        return str(value)

    def _record_operation(self, kind, scope, target, field, before, after,
                          readback_ok=True, runtime_generation=None,
                          runtime_pid=None, meta=None):
        '''Append one verified, session-local operation history entry.'''
        with self._operation_history_lock:
            operation_id = int(self._operation_history_next_id)
            self._operation_history_next_id += 1
            entry = {
                'id': operation_id,
                'kind': str(kind),
                'scope': str(scope),
                # A live-memory readback proves only the current process
                # state. It is not a completed persistence test until the
                # player re-enters the save and the exact field is read again.
                'state': ('runtime_readback_verified_pending_reentry'
                          if str(scope) == 'runtime' else '已完成'),
                'verification_state': ('pending_reentry'
                                       if str(scope) == 'runtime' else 'not_required'),
                'verification_note': ('已完成暂停写入与即时读回；仍需退出并重新进入同一存档后复核。'
                                      if str(scope) == 'runtime' else ''),
                'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
                'target': self._operation_history_value(target or {}),
                'field': str(field or ''),
                'before': self._operation_history_value(before),
                'after': self._operation_history_value(after),
                'readback_ok': bool(readback_ok),
                'undo_available': bool(readback_ok),
                'undo_reason': '',
                'runtime_generation': runtime_generation,
                'runtime_pid': runtime_pid,
                'meta': self._operation_history_value(meta or {}),
            }
            self._operation_history.append(entry)
            overflow = len(self._operation_history) - int(self.OPERATION_HISTORY_LIMIT)
            if overflow > 0:
                del self._operation_history[:overflow]
            return self._operation_history_value(entry)

    def _invalidate_runtime_operation_history(self, reason):
        '''Disable undo for live-memory entries when their address session ends.'''
        with self._operation_history_lock:
            for entry in self._operation_history:
                if entry.get('scope') != 'runtime' or not entry.get('undo_available'):
                    continue
                entry['state'] = '已失效'
                entry['undo_available'] = False
                entry['undo_reason'] = str(reason or '运行时会话已失效')

    def _operation_history_entry(self, operation_id):
        try:
            operation_id = int(operation_id)
        except (TypeError, ValueError):
            return None
        with self._operation_history_lock:
            for entry in reversed(self._operation_history):
                if int(entry.get('id', -1)) == operation_id:
                    return entry
        return None

    def get_operation_history(self):
        '''Return newest-first copies suitable for the WebView frontend.'''
        with self._operation_history_lock:
            return [self._operation_history_value(entry)
                    for entry in reversed(self._operation_history)]

    def confirm_runtime_operation_reentry(self, operation_id):
        """Confirm a runtime operation only after the player reloads the save.

        This is deliberately a read-only confirmation. It re-resolves the live
        target and compares it with the operation snapshot before changing the
        audit state; it never treats an in-session write as persistent.
        """
        entry = self._operation_history_entry(operation_id)
        if not entry:
            return {'ok': False, 'error': '未找到操作记录'}
        if entry.get('scope') != 'runtime':
            return {'ok': False, 'error': '只有运行时写入需要重进存档复核'}
        verification = str(entry.get('verification_state') or '')
        if verification not in ('pending_reentry', 'undo_pending_reentry'):
            return {'ok': False, 'error': '该操作当前不需要重进存档复核'}
        if not self._runtime_operation_is_current(entry):
            return {'ok': False, 'error': '游戏连接已变化；请重新扫描并从新的会话开始验证'}
        target = entry.get('target') or {}
        expected = entry.get('before') if verification == 'undo_pending_reentry' else entry.get('after')
        try:
            kind = str(entry.get('kind') or '')
            if kind == 'dwarf_personal_skill':
                dwarf = self._live_dwarf_by_index(target.get('dwarf_index'))
                if not dwarf or (target.get('dwarf_name') and dwarf.get('name') != target.get('dwarf_name')):
                    raise RuntimeError('找不到原矮人；请刷新后确认编号和名称未变化')
                live = {row['id']: float(row['value'])
                        for row in self._read_v1_personal_skills(int(dwarf.get('edi') or 0))}
                if not isinstance(expected, dict) or any(
                        key not in live or abs(live[key] - float(value)) > 0.05
                        for key, value in expected.items()):
                    raise RuntimeError('个人技能读回与记录值不一致')
            elif kind == 'dwarf_equipment':
                dwarf = self._live_dwarf_by_index(target.get('dwarf_index'))
                if not dwarf or (target.get('dwarf_name') and dwarf.get('name') != target.get('dwarf_name')):
                    raise RuntimeError('找不到原矮人；请刷新后确认编号和名称未变化')
                info = self.get_dwarf_equipment(target.get('dwarf_index'))
                if not info.get('ok'):
                    raise RuntimeError(info.get('error') or '无法重新读取装备栏')
                live = {row['key']: int(row['value']) for row in info.get('slots', [])}
                if not isinstance(expected, dict) or any(
                        live.get(key) != int(value) for key, value in expected.items()):
                    raise RuntimeError('装备槽读回与记录值不一致')
            elif kind == 'dwarf_fields':
                dwarf = self._live_dwarf_by_index(target.get('dwarf_index'))
                if not dwarf or (target.get('dwarf_name') and dwarf.get('name') != target.get('dwarf_name')):
                    raise RuntimeError('找不到原矮人；请刷新后确认编号和名称未变化')
                edi = int(dwarf.get('edi') or 0)
                is_v2 = self._detect_v2()
                live = {}
                if isinstance(expected, dict):
                    if 'x' in expected:
                        live['x'] = pm.read_float(edi + (V2_DWARF_X if is_v2 else 0x428))
                    if 'y' in expected:
                        live['y'] = pm.read_float(edi + (V2_DWARF_Y if is_v2 else 0x42C))
                    if 'hp' in expected:
                        live['hp'] = self._read_live_dwarf_hp(edi, is_v2)
                    if 'sat' in expected:
                        live['sat'] = self._read_live_dwarf_satiety(edi, is_v2)
                if (not isinstance(expected, dict) or any(
                        live.get(key) is None or
                        abs(float(live[key]) - float(value)) > (0.05 if key == 'hp' else 0.02)
                        for key, value in expected.items())):
                    raise RuntimeError('矮人属性读回与记录值不一致')
            elif kind == 'runtime_item_qty':
                item_id = str(target.get('item_id') or '')
                item = next((row for row in item_cache if row.get('name_en') == item_id), None)
                if not item:
                    raise RuntimeError('未找到该物品的重新扫描结果；请先重新扫描仓库')
                if int(item.get('qty', -1)) != int(expected):
                    raise RuntimeError('物品数量读回与记录值不一致')
            elif kind == 'dwarf_training_preset':
                ok, error = self._verify_dwarf_training_snapshot(expected)
                if not ok:
                    raise RuntimeError(error)
            elif kind == 'magic_profile':
                ok, error = self._verify_magic_snapshot(expected)
                if not ok:
                    raise RuntimeError(error)
            else:
                raise RuntimeError('该操作类型尚不支持重进存档复核')
        except Exception as exc:
            return {'ok': False, 'error': '重进存档复核失败：%s' % exc}
        with self._operation_history_lock:
            entry['verification_state'] = 'passed'
            entry['verification_note'] = '已在退出并重新进入同一存档后读回，并由用户人工确认。'
            entry['verified_after_reentry_at'] = time.strftime('%Y-%m-%d %H:%M:%S')
            entry['state'] = ('已撤销（重进已确认）'
                              if verification == 'undo_pending_reentry' else '已完成')
        return {'ok': True, 'operation_id': entry.get('id'), 'state': entry.get('state')}

    def _runtime_operation_is_current(self, entry):
        if not entry or entry.get('scope') != 'runtime':
            return False
        try:
            expected_generation = int(entry.get('runtime_generation'))
            expected_pid = int(entry.get('runtime_pid'))
        except (TypeError, ValueError):
            return False
        with self._runtime_session_lock:
            if self._runtime_shutdown or expected_generation != int(self._runtime_session_generation):
                return False
        try:
            return bool(connected and pm is not None and int(pm.process_id) == expected_pid)
        except Exception:
            return False

    def _finish_operation_undo(self, entry, result):
        '''Mark a history entry only after the underlying transaction read back.'''
        if not isinstance(result, dict) or not result.get('ok'):
            return result
        with self._operation_history_lock:
            entry['state'] = '已撤销（待重进确认）'
            entry['verification_state'] = 'undo_pending_reentry'
            entry['verification_note'] = '撤销已完成即时读回；仍需退出并重新进入同一存档后复核。'
            entry['undo_available'] = False
            entry['undo_reason'] = '已成功撤销'
            entry['undone_at'] = time.strftime('%Y-%m-%d %H:%M:%S')
        result['operation_id'] = entry.get('id')
        return result

    def _invalidate_operation(self, entry, reason):
        with self._operation_history_lock:
            entry['state'] = '已失效'
            entry['undo_available'] = False
            entry['undo_reason'] = str(reason or '操作已失效')
        return {'ok': False, 'error': str(reason or '操作已失效')}

    def undo_operation(self, operation_id):
        '''Undo one verified operation only if its current state still matches.'''
        entry = self._operation_history_entry(operation_id)
        if not entry:
            return {'ok': False, 'error': '未找到操作记录'}
        if not entry.get('undo_available'):
            return {'ok': False, 'error': entry.get('undo_reason') or '该操作不能撤销'}
        kind = entry.get('kind')
        if entry.get('scope') == 'runtime':
            if not self._runtime_operation_is_current(entry):
                return self._invalidate_operation(entry, '游戏连接已变化，旧内存操作不能撤销')
            target = entry.get('target') or {}
            if kind == 'runtime_item_qty':
                result = self._modify_item_qty_transaction(
                    target.get('item_id'), entry.get('before'),
                    expected_current=entry.get('after'), record_history=False)
                return self._finish_operation_undo(entry, result)
            if kind == 'dwarf_equipment':
                result = self.save_dwarf_equipment(
                    target.get('dwarf_index'), entry.get('before'),
                    _expected_current=entry.get('after'), _record_history=False)
                return self._finish_operation_undo(entry, result)
            if kind == 'dwarf_personal_skill':
                ok = self._save_dwarf_personal_skills_transaction(
                    target.get('dwarf_index'), entry.get('before'),
                    _expected_current=entry.get('after'), _record_history=False)
                return self._finish_operation_undo(
                    entry, {'ok': bool(ok),
                            'error': '' if ok else '个人技能已变化或撤销写入未通过读回'})
            if kind == 'dwarf_fields':
                result = self.save_dwarf_fields(
                    target.get('dwarf_index'), entry.get('before'),
                    _expected_current=entry.get('after'), _record_history=False)
                return self._finish_operation_undo(entry, result)
            if kind == 'dwarf_training_preset':
                before_rows = entry.get('before') or []
                after_by_idx = {int(row.get('idx', -1)): row for row in (entry.get('after') or [])
                                if isinstance(row, dict)}
                restore_rows = []
                for before_row in before_rows:
                    if not isinstance(before_row, dict):
                        return self._invalidate_operation(entry, '培养预设快照格式无效')
                    idx = int(before_row.get('idx', -1))
                    after_row = after_by_idx.get(idx)
                    if not after_row:
                        return self._invalidate_operation(entry, '培养预设缺少撤销快照')
                    restore_rows.append({
                        'idx': idx, 'name': before_row.get('name') or '',
                        'skills_before': before_row.get('skills') or {},
                        'skills_after': after_row.get('skills') or {},
                        'equipment_before': before_row.get('equipment') or {},
                        'equipment_after': after_row.get('equipment') or {},
                    })
                result = self._restore_dwarf_training_rows(restore_rows, True)
                if not result.get('ok'):
                    # Best effort: do not leave an undo half-applied if a later
                    # guarded write rejects the batch because the game changed.
                    self._restore_dwarf_training_rows(restore_rows, False)
                return self._finish_operation_undo(entry, result)
            if kind == 'magic_profile':
                result = self._apply_magic_snapshot_transaction(
                    entry.get('before') or {}, entry.get('after') or {},
                    source='撤销魔法方案', record_history=False)
                return self._finish_operation_undo(entry, result)
            return self._invalidate_operation(entry, '该运行时操作类型不支持撤销')
        if entry.get('scope') != 'offline' or kind not in ('offline_inventory', 'offline_technology'):
            return self._invalidate_operation(entry, '该操作类型不支持撤销')
        with self._save_manager_lock:
            ok, error = self._save_require_game_stopped()
            if not ok:
                return {'ok': False, 'error': error}
            target = entry.get('target') or {}
            slot_key = target.get('slot_key')
            slot, error = self._save_slot_from_key(slot_key)
            if not slot:
                return self._invalidate_operation(entry, error)
            filename = target.get('file')
            source_path = os.path.join(slot['path'], str(filename or ''))
            expected_sha = (entry.get('meta') or {}).get('post_sha')
            if (not filename or not os.path.isfile(source_path) or not expected_sha or
                    self._save_hash(source_path) != expected_sha):
                return self._invalidate_operation(
                    entry, '存档已被其他操作或游戏改动，拒绝用旧记录覆盖')
            target_kind = 'inventory' if kind == 'offline_inventory' else 'technology'
            prepared = self._offline_save_prepare_edit(
                slot_key, target_kind, target.get('entry_id'), entry.get('before'),
                history_context={'record_history': False, 'undo_of': entry.get('id')})
            if not prepared.get('ok'):
                return prepared
            result = self.confirm_offline_save_edit(
                slot_key, prepared.get('token'), 'APPLY_OFFLINE_EDIT')
            return self._finish_operation_undo(entry, result)

    def _spawn_runtime_worker(self, target, args=(), name="ctw-worker"):
        """Register a short-lived runtime worker and remove it on exit."""
        holder = {}

        def runner():
            try:
                return target(*args)
            finally:
                thread = holder.get("thread")
                if thread is not None:
                    with self._runtime_workers_lock:
                        self._runtime_workers.discard(thread)

        thread = threading.Thread(target=runner, daemon=True, name=name)
        holder["thread"] = thread
        with self._runtime_workers_lock:
            self._runtime_workers.add(thread)
        try:
            thread.start()
        except Exception:
            with self._runtime_workers_lock:
                self._runtime_workers.discard(thread)
            raise
        return thread

    def _join_runtime_workers(self, timeout=1.5):
        """Reap invalidated background workers without ever joining self.

        Workers are bound to a session generation and therefore stop on the
        next loop boundary.  This method is intentionally called *after* a
        disconnect has cleared ``connected`` so that no worker can acquire a
        new process through the global handle while it is being reaped.
        """
        deadline = time.monotonic() + max(0.0, float(timeout))
        current = threading.current_thread()
        with self._runtime_workers_lock:
            workers = list(self._runtime_workers)
        for worker in workers:
            if worker is current:
                continue
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break
            try:
                worker.join(remaining)
            except RuntimeError:
                continue
        with self._runtime_workers_lock:
            self._runtime_workers = {worker for worker in self._runtime_workers
                                     if worker.is_alive()}
            alive = len(self._runtime_workers)
        if alive:
            _diagnostic("runtime workers still stopping:", alive)
        return alive

    def _runtime_session_current(self, generation, pm_obj=None):
        with self._runtime_session_lock:
            return (not self._runtime_shutdown and
                    int(generation) == int(self._runtime_session_generation) and
                    connected and pm is not None and
                    (pm_obj is None or pm is pm_obj))

    def _runtime_lock_worker_context(self):
        """Capture the exact process/session a recurring writer may touch."""
        with self._runtime_session_lock:
            return int(self._runtime_session_generation), pm

    def _runtime_lock_worker_current(self, name, generation, pm_obj):
        return bool(self.locks.get(name, False)) and self._runtime_session_current(generation, pm_obj)

    def _start_lock_worker(self, name, target, *args):
        """Bind a recurring writer to the exact Pymem session that starts it."""
        generation, pm_obj = self._runtime_lock_worker_context()
        if not self._runtime_lock_worker_current(name, generation, pm_obj):
            self.locks[name] = False
            return False
        self._spawn_runtime_worker(target,
                                   args=(*args, generation, pm_obj),
                                   name="ctw-%s-lock" % name)
        return True

    def _ensure_item_lock_restore_worker(self):
        """Start one item-lock worker, bound to the current process session."""
        if self._lock_restore_active:
            return True
        session_generation, pm_obj = self._runtime_lock_worker_context()
        if not self._runtime_session_current(session_generation, pm_obj):
            return False
        self._lock_restore_active = True
        self._spawn_runtime_worker(self._lock_restore_loop,
                                   args=(session_generation, pm_obj),
                                   name="ctw-item-lock")
        return True

    def shutdown(self):
        """Window-close hook: stop writers and detach before WebView2 dies."""
        with self._memory_write_lock:
            self._end_runtime_session()
            if connected or pm:
                try:
                    self.disconnect()
                except Exception as exc:
                    # Closing must not be cancelled just because the target has
                    # already exited; all background loops were invalidated above.
                    _diagnostic("modifier shutdown cleanup:", exc)
            else:
                self._set_mana_max_lock_runtime(False, None)
                self._clear_timer_locks()
                self._lock_restore_active = False
        self._join_runtime_workers()
        return True

    def window_control(self, action):
        """Handle only the chrome actions exposed by the custom title bar."""
        name = str(action or "").strip().lower()
        window_ref = getattr(self, "_modifier_window", None)
        if window_ref is None:
            return {"ok": False, "error": "窗口尚未就绪"}
        try:
            if name == "minimize":
                window_ref.minimize()
                return {"ok": True, "state": "minimized"}
            if name == "toggle_maximize":
                maximized = bool(getattr(self, "_window_is_maximized", False))
                if maximized:
                    window_ref.restore()
                    self._window_is_maximized = False
                    return {"ok": True, "state": "normal", "maximized": False}
                window_ref.maximize()
                self._window_is_maximized = True
                return {"ok": True, "state": "maximized", "maximized": True}
            if name == "close":
                if getattr(self, "_window_close_requested", False):
                    return {"ok": True, "state": "closing"}
                self._window_close_requested = True

                # Return the API result before destroying WebView2. This gives
                # the page a chance to stop its timers; the existing closing
                # hook then performs the synchronous runtime cleanup.
                def close_window():
                    try:
                        window_ref.destroy()
                    except Exception as exc:
                        _diagnostic("modifier window close:", exc)

                threading.Timer(0.08, close_window).start()
                return {"ok": True, "state": "closing"}
            return {"ok": False, "error": "未知窗口操作"}
        except Exception as exc:
            return {"ok": False, "error": "窗口操作失败：%s" % exc}

    def _config_path(self):
        """Return the clean, package-owned default configuration path."""
        return os.path.join(_package_config_dir(), "marks.json")

    def _user_config_path(self):
        """Return the writable per-user configuration path."""
        return os.path.join(_config_dir(), "user_data.json")

    def _legacy_config_paths(self):
        root = _application_dir()
        return (os.path.join(root, "marks.json"),
                os.path.join(root, "marks.json.bak"))

    def _legacy_user_config_paths(self):
        root = _application_dir()
        return (os.path.join(root, "config", "user_data.json"),
                os.path.join(root, "config", "user_data.json.bak"),
                os.path.join(root, "marks.json"),
                os.path.join(root, "marks.json.bak"))

    def _write_user_config_unlocked(self, cfg):
        """Atomically save only user-owned settings and retain one backup."""
        cfg_path = self._user_config_path()
        backup_path = cfg_path + ".bak"
        tmp_path = "%s.%s.%s.tmp" % (cfg_path, os.getpid(), threading.get_ident())
        backup_tmp = "%s.%s.%s.tmp" % (backup_path, os.getpid(), threading.get_ident())
        try:
            os.makedirs(os.path.dirname(cfg_path), exist_ok=True)
            _hide_user_data_root(_user_data_root())
            with open(tmp_path, "w", encoding="utf-8", newline="\n") as handle:
                json.dump(cfg if isinstance(cfg, dict) else {}, handle,
                          ensure_ascii=False, indent=2, sort_keys=True)
                handle.flush()
                os.fsync(handle.fileno())
            if os.path.exists(cfg_path):
                with open(cfg_path, "rb") as source, open(backup_tmp, "wb") as backup:
                    shutil.copyfileobj(source, backup)
                    backup.flush()
                    os.fsync(backup.fileno())
                os.replace(backup_tmp, backup_path)
            os.replace(tmp_path, cfg_path)
            return True
        except Exception as exc:
            _diagnostic("user_data.json atomic save error:", exc)
            return False
        finally:
            for stale in (tmp_path, backup_tmp):
                try:
                    if os.path.exists(stale):
                        os.remove(stale)
                except OSError:
                    pass

    def _read_config_unlocked(self):
        """Read defaults plus user settings, migrating the old flat files once."""
        defaults = _read_json_object(self._config_path()) or dict(DEFAULT_CONFIG)
        user_path = self._user_config_path()
        user = _read_json_object(user_path)
        migrated = False
        if user is None:
            user = _read_json_object(user_path + ".bak")
            if user is not None:
                _diagnostic("user_data.json 无效，已使用 user_data.json.bak")
        if user is None:
            for legacy_path in self._legacy_user_config_paths():
                user = _read_json_object(legacy_path)
                if user is not None:
                    migrated = True
                    break
            if user is None:
                user = {}

            # Older builds kept portal plans in a second sidecar file. They
            # are imported into the unified user configuration exactly once.
            if not isinstance(user.get("portal_director_presets"), dict):
                legacy_portal = _read_json_object(
                    os.path.join(_application_dir(), "portal_director_presets.json"))
                if isinstance(legacy_portal, dict):
                    user["portal_director_presets"] = legacy_portal
                    migrated = True
            if migrated:
                self._write_user_config_unlocked(user)
                _diagnostic("已将旧版用户配置迁移到 %LOCALAPPDATA%\\CraftWorldModifier\\config\\user_data.json")
        # 功能预设已从正式版移除。清理旧用户配置中的预设和默认预设，
        # 防止历史预设在连接游戏时继续恢复并触发旧的物品写入。
        if isinstance(user, dict):
            obsolete_feature_preset_keys = ("feature_presets", "default_feature_preset")
            if any(key in user for key in obsolete_feature_preset_keys):
                user = dict(user)
                for key in obsolete_feature_preset_keys:
                    user.pop(key, None)
                self._write_user_config_unlocked(user)
        return _merge_config(defaults, user)

    def _read_config(self):
        with self._config_lock:
            return self._read_config_unlocked()

    def _write_config_unlocked(self, cfg):
        """Write only user-owned settings; never overwrite package defaults."""
        return self._write_user_config_unlocked(cfg)

    def _update_config(self, update):
        """Serialize read-modify-write updates so independent settings persist."""
        with self._config_lock:
            cfg = self._read_config_unlocked()
            update(cfg)
            return self._write_config_unlocked(cfg)

    # ==================== 修改器更新中心 ====================
    @staticmethod
    def _update_version_tuple(value):
        """Parse a conservative numeric version; unknown suffixes are ignored."""
        parts = re.findall(r"\d+", str(value or ""))
        if not parts:
            return None
        values = [int(item) for item in parts[:4]]
        values.extend([0] * (4 - len(values)))
        return tuple(values)

    @staticmethod
    def _update_url(value):
        """Accept only HTTP(S), file URLs, or an explicit local file path."""
        value = str(value or "").strip()
        if not value:
            return ""
        # Windows drive letters are reported as a URI scheme by urlparse
        # (``C:\\...`` -> scheme ``c``); check an existing local file first.
        local_candidate = os.path.abspath(os.path.expanduser(value))
        if os.path.isfile(local_candidate):
            return local_candidate
        parsed = urllib.parse.urlparse(value)
        if parsed.scheme in ("http", "https"):
            return value
        if parsed.scheme == "file":
            return urllib.request.url2pathname(parsed.path)
        if parsed.scheme:
            return ""
        return ""

    @staticmethod
    def _update_safe_rel(value):
        """Normalize a relative package path and reject traversal/absolute paths."""
        value = str(value or "").replace("\\", "/").strip()
        if not value or value.startswith("/") or re.match(r"^[A-Za-z]:", value):
            return ""
        parts = [part for part in value.split("/") if part not in ("", ".")]
        if not parts or any(part == ".." for part in parts):
            return ""
        return "/".join(parts)

    @classmethod
    def _update_allowed_rel(cls, value):
        rel = cls._update_safe_rel(value)
        if not rel:
            return ""
        lower = rel.lower()
        name = lower.rsplit("/", 1)[-1]
        if lower in {item.lower() for item in UPDATE_ALLOWED_SOURCE_NAMES}:
            return rel
        if name in {item.lower() for item in UPDATE_ALLOWED_EXE_NAMES}:
            return rel
        if "/" not in rel and any(name.startswith(prefix.lower()) for prefix in UPDATE_ALLOWED_SOURCE_PREFIXES):
            return rel
        return ""

    @staticmethod
    def _update_strip_package_root(name):
        """Strip one common archive directory without accepting traversal."""
        rel = Api._update_safe_rel(name)
        if not rel:
            return ""
        allowed = Api._update_allowed_rel(rel)
        if allowed:
            return allowed
        pieces = rel.split("/")
        if len(pieces) > 1:
            return Api._update_allowed_rel("/".join(pieces[1:]))
        return ""

    @staticmethod
    def _update_stream_bytes(url, limit):
        """Read a bounded local/HTTP payload and return bytes plus resolved URL."""
        parsed = urllib.parse.urlparse(str(url or ""))
        if parsed.scheme in ("http", "https"):
            request = urllib.request.Request(str(url), headers={"User-Agent": "CraftWorldModifier/%s" % APP_VERSION,
                                                                  "Cache-Control": "no-cache"})
            with urllib.request.urlopen(request, timeout=20) as response:
                declared = int(response.headers.get("Content-Length") or 0)
                if declared and declared > int(limit):
                    raise ValueError("远程文件超过允许大小限制")
                chunks, total = [], 0
                while True:
                    chunk = response.read(min(1024 * 1024, int(limit) - total + 1))
                    if not chunk:
                        break
                    total += len(chunk)
                    if total > int(limit):
                        raise ValueError("远程文件超过允许大小限制")
                    chunks.append(chunk)
                resolved_url = response.geturl() if hasattr(response, "geturl") else str(url)
                return b"".join(chunks), str(resolved_url)
        path = str(url or "")
        if parsed.scheme == "file":
            path = urllib.request.url2pathname(parsed.path)
        path = os.path.abspath(os.path.expanduser(path))
        size = os.path.getsize(path)
        if size > int(limit):
            raise ValueError("本地文件超过允许大小限制")
        with open(path, "rb") as handle:
            return handle.read(), path

    def _read_update_manifest_from_release_page(self, api_source=""):
        """Read the latest tag and checksum through GitHub's release page.

        This path is used when the unauthenticated REST API returns 403 due
        to the shared network IP exhausting its 60 requests/hour quota.  The
        release page redirects to the concrete tag, and the published
        SHA256SUMS.txt supplies the same integrity value used by the API path.
        """
        try:
            page_source = self._update_url(UPDATE_RELEASE_PAGE_URL)
            if not page_source:
                return None, "备用 Release 页面地址无效"
            _, resolved = self._update_stream_bytes(page_source, 8 * 1024 * 1024)
            parsed = urllib.parse.urlparse(resolved)
            match = re.search(r"/releases/tag/([^/?#]+)", parsed.path or "")
            if not match:
                return None, "备用 Release 页面没有返回有效版本标签"
            tag = urllib.parse.unquote(match.group(1)).strip()
            version = tag.lstrip("vV")
            if not self._update_version_tuple(version):
                return None, "备用 Release 页面没有返回有效版本号"
            base = "https://github.com/dszwamn/CraftWorldModifier/releases/download/%s/" % urllib.parse.quote(tag, safe="")
            checksum_url = base + "SHA256SUMS.txt"
            checksum_raw, checksum_resolved = self._update_stream_bytes(checksum_url, 64 * 1024)
            checksum_text = checksum_raw.decode("utf-8-sig", errors="replace")
            checksum_match = re.search(
                r"(?im)^\s*([0-9a-f]{64})\s+\*?CraftWorldModifier\.exe\s*$",
                checksum_text,
            )
            if not checksum_match:
                return None, "备用 Release 页面没有返回有效 EXE 校验值"
            package_url = base + "CraftWorldModifier.exe"
            return {
                "app_id": APP_ID,
                "version": version,
                "channel": "stable",
                "published_at": "",
                "notes": "通过 GitHub Release 页面读取（API 暂时受限）；下载前仍会校验 SHA-256。",
                "package": {
                    "url": package_url,
                    "sha256": checksum_match.group(1).lower(),
                    "size": 0,
                    "format": "exe",
                },
                "feed_url": api_source or UPDATE_RELEASE_PAGE_URL,
                "resolved_feed_url": resolved,
                "fallback": True,
                "checksum_url": checksum_resolved,
            }, ""
        except urllib.error.HTTPError as exc:
            return None, "备用 Release 页面读取失败：HTTP %s" % exc.code
        except urllib.error.URLError as exc:
            return None, "备用 Release 页面读取失败：%s" % exc.reason
        except Exception as exc:
            return None, "备用 Release 页面读取失败：%s" % exc

    def _update_feed_url(self, supplied=""):
        """Return the immutable built-in release endpoint.

        Update sources are intentionally not user-configurable.  This avoids
        an environment variable or stale UI call silently redirecting a
        future packaged build to an unrelated download location.
        """
        value = str(UPDATE_RELEASE_API_URL or "").strip()
        return self._update_url(value)

    def get_update_info(self):
        """Return local version, built-in release source, staged package and mode."""
        ready = self._read_staged_update()
        return {"ok": True, "app": APP_ID, "name": "CraftWorld 修改器", "version": APP_VERSION,
                "current_version": APP_VERSION, "latest_version": "未检查",
                "frozen": bool(getattr(sys, "frozen", False)), "app_dir": _application_dir(),
                "feed_url": self._update_feed_url(), "staged": ready or None}

    def set_update_manifest_url(self, value):
        return {"ok": False, "error": "更新服务已内置，不需要设置更新清单地址"}

    def _read_update_manifest(self, manifest_url=""):
        source = self._update_feed_url(manifest_url)
        if not source:
            return None, "尚未配置内置更新服务"
        try:
            raw, resolved = self._update_stream_bytes(source, UPDATE_MAX_MANIFEST_BYTES)
            payload = json.loads(raw.decode("utf-8-sig"))
            if not isinstance(payload, dict):
                return None, "更新服务返回的数据格式无效"
            version = str(payload.get("version") or payload.get("tag_name") or "").strip().lstrip("vV")
            notes = str(payload.get("notes") or payload.get("body") or "")
            package = payload.get("package") if isinstance(payload.get("package"), dict) else {}
            if not package:
                assets = payload.get("assets") if isinstance(payload.get("assets"), list) else []
                asset = next((row for row in assets if isinstance(row, dict) and str(row.get("name") or "").lower() == "craftworldmodifier.exe"), None)
                if asset is None:
                    asset = next((row for row in assets if isinstance(row, dict) and str(row.get("name") or "").lower().startswith("craftworldmodifier") and str(row.get("name") or "").lower().endswith(".exe")), None)
                if asset:
                    package = {"url": asset.get("browser_download_url") or asset.get("url") or "",
                               "size": asset.get("size") or 0,
                               "sha256": asset.get("digest") or payload.get("sha256") or "",
                               "format": "exe"}
            package = dict(package)
            package_url = str(package.get("url") or payload.get("download_url") or "").strip()
            if package_url and not urllib.parse.urlparse(package_url).scheme:
                package_url = urllib.parse.urljoin(resolved, package_url)
            digest = str(package.get("sha256") or "").strip().lower()
            if digest.startswith("sha256:"):
                digest = digest.split(":", 1)[1]
            package.update({"url": package_url, "sha256": digest,
                            "size": int(package.get("size") or payload.get("size") or 0),
                            "format": str(package.get("format") or "exe").strip().lower()})
            if not self._update_version_tuple(version):
                return None, "更新服务没有返回有效版本号"
            return {"app_id": APP_ID, "version": version, "channel": payload.get("channel", "stable"),
                    "published_at": payload.get("published_at") or payload.get("published_at_at") or "",
                    "notes": notes, "package": package, "feed_url": source, "resolved_feed_url": resolved}, ""
        except urllib.error.HTTPError as exc:
            if int(getattr(exc, "code", 0) or 0) == 404:
                return None, "GitHub 暂未发布可用版本"
            if int(getattr(exc, "code", 0) or 0) == 403:
                fallback, fallback_error = self._read_update_manifest_from_release_page(source)
                if fallback:
                    return fallback, ""
                return None, "读取内置更新服务失败：HTTP 403（GitHub API 限流；%s）" % (fallback_error or "备用通道不可用")
            return None, "读取内置更新服务失败：HTTP %s" % exc.code
        except urllib.error.URLError as exc:
            return None, "读取内置更新服务失败：%s" % exc.reason
        except Exception as exc:
            return None, "读取内置更新服务失败：%s" % exc

    def check_for_update(self, manifest_url=""):
        manifest, error = self._read_update_manifest(manifest_url)
        if not manifest:
            # A missing GitHub Release is a normal "no update yet" state.
            # Transport, API and data-format failures must remain visible to
            # the UI instead of being mistaken for an unpublished release.
            if error != "GitHub 暂未发布可用版本":
                return {"ok": False, "available": False, "version": APP_VERSION,
                        "current_version": APP_VERSION, "latest_version": "检查失败",
                        "package_ready": False, "error": error or "更新检查失败"}
            return {"ok": True, "available": False, "version": APP_VERSION,
                    "current_version": APP_VERSION, "latest_version": "未发布",
                    "package_ready": False, "message": error or "暂无可用版本"}
        remote_version = self._update_version_tuple(manifest.get("version"))
        current_version = self._update_version_tuple(APP_VERSION)
        available = bool(remote_version and current_version and remote_version > current_version)
        package = manifest.get("package") or {}
        package_ready = bool(package.get("url"))
        if available and not package_ready:
            manifest["notes"] = (manifest.get("notes") + "\n" if manifest.get("notes") else "") + "该版本暂未提供下载包。"
        return {"ok": True, "available": available, "current_version": APP_VERSION,
                "latest_version": str(manifest.get("version")),
                "version": str(manifest.get("version")), "manifest": manifest,
                "package_ready": package_ready, "message": "发现新版本" if available else "当前已是最新版本"}

    def _read_staged_update(self):
        updates_root = os.path.abspath(_update_staging_root())
        ready_path = os.path.join(updates_root, "ready.json")
        ready = _read_json_object(ready_path)
        if not isinstance(ready, dict):
            # Migrate away from the old visible app\updates staging folder.
            try:
                shutil.rmtree(os.path.join(_application_dir(), "updates"), ignore_errors=True)
            except Exception:
                pass
            return None
        stage_dir = os.path.abspath(str(ready.get("stage_dir") or ""))
        try:
            if os.path.commonpath([stage_dir, updates_root]) != updates_root:
                return None
        except ValueError:
            return None
        files = [self._update_safe_rel(item) for item in (ready.get("files") or [])]
        files = [item for item in files if item and os.path.isfile(os.path.join(stage_dir, *item.split("/")))]
        if not stage_dir or not files:
            return None
        ready["files"] = files
        saved_hashes = ready.get("file_sha256") if isinstance(ready.get("file_sha256"), dict) else {}
        ready["file_sha256"] = {
            rel: str(saved_hashes.get(rel) or "").strip().lower()
            for rel in files
            if re.fullmatch(r"[0-9a-f]{64}", str(saved_hashes.get(rel) or "").strip().lower())
        }
        return ready

    def stage_update(self, manifest_url=""):
        checked = self.check_for_update(manifest_url)
        if not checked.get("ok") or not checked.get("available"):
            return checked
        manifest = checked.get("manifest") or {}
        package = manifest.get("package") or {}
        package_url = self._update_url(package.get("url"))
        if not package_url:
            return {"ok": False, "error": "新版本没有可用下载地址"}
        try:
            raw, resolved = self._update_stream_bytes(package_url, UPDATE_MAX_PACKAGE_BYTES)
            expected_size = int(package.get("size") or 0)
            if expected_size and expected_size != len(raw):
                return {"ok": False, "error": "更新包大小校验失败"}
            digest = hashlib.sha256(raw).hexdigest().lower()
            expected_hash = str(package.get("sha256") or "").lower()
            if expected_hash and digest != expected_hash:
                return {"ok": False, "error": "更新包 SHA-256 校验失败"}
            updates_root = _update_staging_root()
            os.makedirs(updates_root, exist_ok=True)
            stage_dir = tempfile.mkdtemp(prefix="stage-", dir=updates_root)
            package_format = str(package.get("format") or "").lower()
            if not package_format:
                package_format = "zip" if str(package_url).lower().split("?", 1)[0].endswith(".zip") else "exe"
            files = []
            file_sha256 = {}
            if package_format == "zip":
                with zipfile.ZipFile(io.BytesIO(raw), "r") as archive:
                    for info in archive.infolist():
                        if info.is_dir() or (info.external_attr >> 16) & 0o170000 == 0o120000:
                            continue
                        rel = self._update_strip_package_root(info.filename)
                        if not rel:
                            continue
                        target = os.path.abspath(os.path.join(stage_dir, *rel.split("/")))
                        if os.path.commonpath([target, os.path.abspath(stage_dir)]) != os.path.abspath(stage_dir):
                            raise ValueError("更新包包含越界路径")
                        os.makedirs(os.path.dirname(target), exist_ok=True)
                        with archive.open(info, "r") as source, open(target, "wb") as destination:
                            shutil.copyfileobj(source, destination, length=1024 * 1024)
                        files.append(rel)
                        file_sha256[rel] = self._preflight_file_hash(target).lower()
            elif package_format in ("exe", "binary"):
                rel = "CraftWorldModifier.exe"
                target = os.path.join(stage_dir, rel)
                with open(target, "wb") as handle:
                    handle.write(raw)
                files.append(rel)
                file_sha256[rel] = digest
            else:
                shutil.rmtree(stage_dir, ignore_errors=True)
                return {"ok": False, "error": "不支持的更新包格式：%s" % package_format}
            if not files:
                shutil.rmtree(stage_dir, ignore_errors=True)
                return {"ok": False, "error": "更新包没有包含允许替换的修改器文件"}
            ready = {"app_id": APP_ID, "version": str(manifest.get("version")), "current_version": APP_VERSION,
                     "stage_dir": stage_dir, "files": sorted(set(files)), "format": package_format,
                     "package_sha256": digest, "file_sha256": file_sha256,
                     "package_size": len(raw), "manifest": manifest,
                     "staged_at": datetime.now().astimezone().isoformat(timespec="seconds")}
            ready_path = os.path.join(updates_root, "ready.json")
            temporary = ready_path + ".tmp"
            with open(temporary, "w", encoding="utf-8", newline="\n") as handle:
                json.dump(ready, handle, ensure_ascii=False, indent=2)
                handle.flush(); os.fsync(handle.fileno())
            os.replace(temporary, ready_path)
            return {"ok": True, "available": True, "version": ready["version"], "files": ready["files"],
                    "stage_dir": stage_dir, "size": len(raw), "sha256": digest,
                    "restart_supported": bool(getattr(sys, "frozen", False) or os.path.isfile(__file__))}
        except zipfile.BadZipFile:
            return {"ok": False, "error": "更新包不是有效 ZIP 文件"}
        except Exception as exc:
            return {"ok": False, "error": "下载或暂存更新失败：%s" % exc}

    def apply_staged_update(self):
        """Schedule a verified replacement after this process exits.

        Windows keeps the running executable locked.  The previous updater
        launched a short ``cmd.exe`` script and assumed that destroying the
        WebView had already terminated the Python process.  In practice that
        assumption is false on some WebView2/runtime combinations, so the
        copy silently failed and only the ``updates`` directory remained.
        The helper below waits for this exact PID to disappear, retries the
        copy, verifies every destination, and leaves a diagnostic log when a
        replacement cannot be completed.
        """
        ready = self._read_staged_update()
        if not ready:
            return {"ok": False, "error": "没有已校验的暂存更新"}
        stage_dir = os.path.abspath(ready["stage_dir"])
        app_dir = os.path.abspath(_application_dir())
        mappings = []
        staged_hashes = ready.get("file_sha256") if isinstance(ready.get("file_sha256"), dict) else {}
        if getattr(sys, "frozen", False):
            exe_source = os.path.join(stage_dir, "CraftWorldModifier.exe")
            if not os.path.isfile(exe_source):
                return {"ok": False, "error": "更新包中没有 CraftWorldModifier.exe"}
            mappings.append((exe_source, os.path.abspath(sys.executable), "CraftWorldModifier.exe"))
        else:
            current_script = os.path.abspath(__file__)
            current_ui = os.path.abspath(_resource_path("ui_v1.0.html"))
            for rel in ready["files"]:
                source = os.path.abspath(os.path.join(stage_dir, *rel.split("/")))
                if rel.lower().startswith("craft_web_"):
                    target = current_script
                elif rel.lower().startswith("ui_v"):
                    target = current_ui
                else:
                    target = os.path.abspath(os.path.join(app_dir, *rel.split("/")))
                mappings.append((source, target, rel))
        if not mappings:
            return {"ok": False, "error": "没有可应用的更新文件"}
        def ps_literal(value):
            return "'" + str(value).replace("'", "''") + "'"

        script_path = os.path.join(tempfile.gettempdir(), "ctw_modifier_update_%s.ps1" % uuid.uuid4().hex)
        launcher_path = os.path.join(tempfile.gettempdir(), "ctw_modifier_launcher_%s.cmd" % uuid.uuid4().hex)
        updates_root = _update_staging_root()
        ready_path = os.path.join(updates_root, "ready.json")
        # Keep the diagnostic beside ready.json so a user can find it even
        # after the temporary PowerShell helper has finished.
        log_path = os.path.join(updates_root, "update.log")
        stage_root = os.path.dirname(stage_dir)
        script_lines = [
            "$ErrorActionPreference = 'Stop'",
            "$ownerPid = %d" % os.getpid(),
            "$logPath = %s" % ps_literal(log_path),
            "$stageRoot = %s" % ps_literal(stage_root),
            "$readyPath = %s" % ps_literal(ready_path),
            "$launchPath = %s" % ps_literal(os.path.abspath(sys.executable) if os.path.isfile(str(sys.executable)) else str(sys.executable)),
            "$launchArgs = @(%s)" % (ps_literal(os.path.abspath(__file__)) if not getattr(sys, "frozen", False) else ""),
            "$items = @(",
        ]
        for source, target, rel in mappings:
            # Single-file EXE releases historically stored only the package
            # digest.  Keep that format compatible while ZIP releases verify
            # every extracted file against its own recorded digest.
            expected = str(staged_hashes.get(rel) or "").strip().lower()
            if not expected and str(ready.get("format") or "").lower() in ("exe", "binary"):
                expected = str(ready.get("package_sha256") or "").strip().lower()
            script_lines.append("  @{ Source = %s; Target = %s; ExpectedHash = %s }" % (
                ps_literal(source), ps_literal(target), ps_literal(expected)))
        target_exe = next((target for _source, target, _rel in mappings
                           if os.path.basename(target).lower() == "craftworldmodifier.exe"), "")
        script_lines.extend([
            ")",
            "$targetExePath = %s" % ps_literal(target_exe),
            "function Write-UpdateLog([string]$Message) {",
            "  try { Add-Content -LiteralPath $logPath -Value ((Get-Date -Format o) + ' ' + $Message) -Encoding UTF8 } catch {}",
            "}",
            "function Get-LiveTargetProcesses([string]$TargetPath) {",
            "  try {",
            "    $fullTarget = [System.IO.Path]::GetFullPath($TargetPath)",
            "    @(Get-CimInstance Win32_Process -Filter \"Name='CraftWorldModifier.exe'\" -ErrorAction SilentlyContinue | Where-Object {",
            "      $candidate = [string]$_.ExecutablePath",
            "      $candidate -and [String]::Equals([System.IO.Path]::GetFullPath($candidate), $fullTarget, [System.StringComparison]::OrdinalIgnoreCase)",
            "    })",
            "  } catch { @() }",
            "}",
            "function Test-TargetUnlocked([string]$Path) {",
            "  if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $true }",
            "  $stream = $null",
            "  try {",
            "    $stream = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)",
            "    return $true",
            "  } catch { return $false }",
            "  finally { if ($null -ne $stream) { $stream.Dispose() } }",
            "}",
            "function Get-FileSha256([string]$Path) {",
            "  $sha = [System.Security.Cryptography.SHA256]::Create()",
            "  try { return ([BitConverter]::ToString($sha.ComputeHash([System.IO.File]::ReadAllBytes($Path))).Replace('-', '').ToLowerInvariant()) } finally { $sha.Dispose() }",
            "}",
            "try {",
            "  Write-UpdateLog '更新助手已启动'",
            "  $exited = $false",
            "  for ($i = 0; $i -lt 300; $i++) {",
            "    if (-not (Get-Process -Id $ownerPid -ErrorAction SilentlyContinue)) { $exited = $true; break }",
            "    Start-Sleep -Milliseconds 200",
            "  }",
            "  if (-not $exited) { throw '修改器进程未在 30 秒内退出，已取消替换' }",
            "  if ($targetExePath) {",
            "    $unlocked = $false",
            "    for ($i = 0; $i -lt 300; $i++) {",
            "      $live = @(Get-LiveTargetProcesses $targetExePath)",
            "      if ($live.Count -eq 0 -and (Test-TargetUnlocked $targetExePath)) { $unlocked = $true; break }",
            "      Start-Sleep -Milliseconds 200",
            "    }",
            "    if (-not $unlocked) { throw '修改器父/子进程仍占用目标文件，已取消替换' }",
            "  }",
            "  foreach ($item in $items) {",
            "    if (-not (Test-Path -LiteralPath $item.Source -PathType Leaf)) { throw ('更新文件不存在：' + $item.Source) }",
            "    $parent = [System.IO.Path]::GetDirectoryName([string]$item.Target)",
            "    if ($parent) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }",
            "    $copied = $false",
            "    for ($attempt = 1; $attempt -le 120; $attempt++) {",
            "      try {",
            "        Copy-Item -LiteralPath $item.Source -Destination $item.Target -Force",
            "        if (-not (Test-Path -LiteralPath $item.Target -PathType Leaf)) { throw '目标文件未生成' }",
            "        $copied = $true; break",
            "      } catch { Write-UpdateLog ('第 ' + $attempt + ' 次复制失败：' + $_.Exception.Message); Start-Sleep -Milliseconds 300 }",
            "    }",
            "    if (-not $copied) { throw ('无法替换文件：' + $item.Target) }",
        ])
        script_lines.extend([
            "    if ($item.ExpectedHash -and (Get-FileSha256 ([string]$item.Target)) -ne [string]$item.ExpectedHash) { throw ('目标文件校验失败：' + $item.Target) }",
        ])
        script_lines.extend([
            "    Write-UpdateLog ('已替换：' + $item.Target)",
            "  }",
            "  if ($launchArgs.Count -gt 0) { Start-Process -FilePath $launchPath -ArgumentList $launchArgs } else { Start-Process -FilePath $launchPath }",
            "  Write-UpdateLog '更新完成，已重新启动修改器'",
            "  try { Remove-Item -LiteralPath $stageRoot -Recurse -Force -ErrorAction SilentlyContinue } catch {}",
            "  try { Remove-Item -LiteralPath $readyPath -Force -ErrorAction SilentlyContinue } catch {}",
            "} catch {",
            "  Write-UpdateLog ('更新失败：' + $_.Exception.Message)",
            "  exit 1",
            "}",
        ])
        try:
            # Windows PowerShell 5.1 needs the UTF-8 BOM; without it a path or
            # Chinese diagnostic text is decoded as the legacy code page and
            # the helper can fail to parse before it ever reaches Copy-Item.
            with open(script_path, "w", encoding="utf-8-sig", newline="\r\n") as handle:
                handle.write("\r\n".join(script_lines) + "\r\n")
            # Start a separate PowerShell worker through ``start`` so it
            # survives the PyInstaller host process exiting.
            launcher_lines = [
                "@echo off",
                'start "" /b powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -File "%s"' % script_path.replace('"', '""'),
                'del "%~f0"',
            ]
            with open(launcher_path, "w", encoding="utf-8", newline="\r\n") as handle:
                handle.write("\r\n".join(launcher_lines) + "\r\n")
            flags = int(getattr(subprocess, "CREATE_NO_WINDOW", 0))
            subprocess.Popen(["cmd.exe", "/d", "/c", launcher_path], close_fds=True, creationflags=flags)
            threading.Thread(target=self._close_after_update, name="ctw-update-exit", daemon=True).start()
            return {"ok": True, "restarting": True, "version": ready.get("version"),
                    "log_path": log_path,
                    "message": "更新已排队；修改器退出后将自动替换并重新启动。若失败，可查看更新日志：%s" % log_path}
        except Exception as exc:
            return {"ok": False, "error": "无法启动更新程序：%s" % exc}

    @staticmethod
    def _close_after_update():
        """Let the JS response return, then close the pywebview window."""
        time.sleep(0.8)
        try:
            windows = list(getattr(webview, "windows", []) or [])
            if windows:
                windows[0].destroy()
        except Exception:
            pass
        # ``destroy()`` does not terminate the Python host on every WebView2
        # backend.  Force the host to exit after the close callback has had
        # time to run, otherwise Windows keeps the EXE locked for the helper.
        time.sleep(2.0)
        os._exit(0)

    @staticmethod
    def _valid_game_root(value):
        """Return a verified Craft The World directory, or an empty string."""
        try:
            root = os.path.abspath(os.path.expanduser(str(value or "").strip()))
            if os.path.isfile(root) and os.path.basename(root).lower() == MODULE_NAME.lower():
                root = os.path.dirname(root)
            data_dir = os.path.join(root, "data")
            executable = os.path.join(root, MODULE_NAME)
            if os.path.isdir(data_dir) and os.path.isfile(executable):
                return root
        except Exception:
            pass
        return ""

    def _running_game_root(self):
        try:
            if not pm or not getattr(pm, "process_id", 0):
                return ""
            import psutil
            return self._valid_game_root(os.path.dirname(psutil.Process(pm.process_id).exe()))
        except Exception:
            return ""

    @staticmethod
    def _local_data_summary(root):
        """Count the local files which power translations, recipes and gear."""
        data_dir = os.path.join(root, "data")
        try:
            data_files = os.listdir(data_dir)
        except OSError:
            data_files = []
        is_resource = lambda name: bool(re.fullmatch(r"craft_resources(?:_(\d+))?\.xml", name, re.I))
        is_recipe = lambda name: bool(re.fullmatch(r"recipes(?:_(\d+))?\.xml", name, re.I))
        mods_dir = os.path.join(root, "mods")
        mod_dirs, mod_resource_files, mod_translation_files = set(), 0, 0
        if os.path.isdir(mods_dir):
            for current, _dirs, files in os.walk(mods_dir):
                relative = os.path.relpath(current, mods_dir)
                if relative != ".":
                    mod_dirs.add(relative.split(os.sep, 1)[0])
                mod_resource_files += sum(1 for name in files if is_resource(name))
                mod_translation_files += sum(1 for name in files if name.lower() == "craft_resources.csv")
        return {
            "resources": sum(1 for name in data_files if is_resource(name)),
            "recipes": sum(1 for name in data_files if is_recipe(name)),
            "mods": len(mod_dirs),
            "mod_resources": mod_resource_files,
            "mod_translations": mod_translation_files,
            "tech_locale": os.path.isfile(os.path.join(root, "lang", "tech_locale.csv")),
        }

    def _activate_local_game_root(self, root, source):
        """Reload every local-data cache without touching game memory."""
        global GAME_ROOT, GAME_DATA_DIR, ITEM_NAME_MAP
        root = self._valid_game_root(root)
        if not root:
            return {"ok": False, "needs_path": True,
                    "error": "未找到有效的 CraftTheWorld 游戏目录，请选择包含 CraftWorld.exe 与 data 文件夹的位置"}
        GAME_ROOT = root
        GAME_DATA_DIR = os.path.join(root, "data")
        _ensure_local_resource_metadata(force=True)
        ITEM_NAME_MAP = load_item_name_map()
        self._item_config_loaded = False
        self._translations = {}
        self._v1_equipment_class_map_cache = None
        self._v1_equipment_catalog_cache = None
        self._update_config(lambda cfg: cfg.update({"local_game_root": root}))
        files = self._local_data_summary(root)
        return {"ok": True, "game_root": root, "source": source, "files": files,
                "message": "本地数据已同步"}

    def sync_local_data(self):
        """Find the installed game automatically and refresh local data caches."""
        candidates = []
        try:
            saved = self._read_config().get("local_game_root", "")
            if saved:
                candidates.append((saved, "已保存的位置"))
        except Exception:
            pass
        running = self._running_game_root()
        if running:
            candidates.append((running, "当前游戏进程"))
        candidates.append((GAME_ROOT, "当前目录"))
        candidates.append((DEFAULT_GAME_ROOT, "默认 Steam 目录"))
        seen = set()
        for candidate, source in candidates:
            key = os.path.normcase(os.path.abspath(str(candidate or ""))) if candidate else ""
            if not key or key in seen:
                continue
            seen.add(key)
            if self._valid_game_root(candidate):
                return self._activate_local_game_root(candidate, source)
        return {"ok": False, "needs_path": True,
                "error": "没有自动定位到游戏目录。请选择包含 CraftWorld.exe 与 data 文件夹的位置"}

    def read_embedded_data(self):
        """Report the bundled data snapshot without scanning the game directory."""
        structures = len(EMBEDDED_STRUCTURE_INDEX)
        valid_structures = 0
        for item in EMBEDDED_STRUCTURE_INDEX.values():
            try:
                valid_structures += int(bool(item[3]))
            except (IndexError, TypeError, ValueError):
                continue
        return {
            "ok": bool(structures),
            "structures": structures,
            "valid_structures": valid_structures,
            "pandora_events": bool(EMBEDDED_PANDORA_EVENTS_XML),
            "tech_trees": len(EMBEDDED_TECH_TREE_FILES or {}),
            "message": "修改器内嵌数据已读取",
        }

    def choose_local_game_dir(self):
        """Let the player choose a game folder after automatic discovery fails."""
        initial = GAME_ROOT if os.path.isdir(GAME_ROOT) else os.path.expanduser("~")
        try:
            window = webview.windows[0] if getattr(webview, "windows", None) else None
            selected = window.create_file_dialog(webview.FOLDER_DIALOG, directory=initial) if window else None
        except Exception as exc:
            return {"ok": False, "needs_path": True, "error": "无法打开目录选择窗口：%s" % exc}
        if not selected:
            return {"ok": False, "cancelled": True, "error": "未选择游戏目录"}
        if isinstance(selected, (list, tuple)):
            selected = selected[0] if selected else ""
        return self._activate_local_game_root(selected, "手动选择")

    @staticmethod
    def _valid_runtime_pointer(value):
        try:
            # 32-bit CraftWorld allocations can legitimately reside above 2 GB
            # (for example 0x9Axxxxxx under WOW64).  The former 0x7FFF0000 cap
            # silently discarded every such live Worker before object validation.
            pointer = int(value or 0) & 0xFFFFFFFF
            return 0x10000 <= pointer < 0xFFF00000
        except Exception:
            return False

    def _run_compatibility_doctor(self):
        """Read-only validation for the loaded game layout.

        This is intentionally limited to structures that all direct writers
        already depend on: the executable image, the active resource vector,
        and (for Steam V1) the dwarf manager vector.  It is not a guessed
        version number and it never writes executable or save data.
        """
        checks = []
        errors = []

        def add(key, label, state, detail, verification=None):
            if verification is None:
                if state == "ok":
                    verification = self.STATUS_VERIFIED
                elif any(word in str(detail) for word in ("不匹配", "不支持", "不是受支持")):
                    verification = self.STATUS_UNSUPPORTED
                else:
                    verification = self.STATUS_FAILED
            checks.append({"key": key, "label": label, "state": state,
                           "verification": verification, "detail": detail})
            if state == "error":
                errors.append(detail)

        try:
            if not pm or not getattr(pm, "process_id", 0):
                add("process", "游戏进程", "error", "未连接游戏进程")
            else:
                pid = int(pm.process_id)
                base = int(get_base() or 0)
                if not self._valid_runtime_pointer(base):
                    add("module", "游戏模块", "error", "无法读取 CraftWorld.exe 模块基址")
                elif pm.read_bytes(base, 2) != b"MZ":
                    add("module", "游戏模块", "error", "模块头校验失败，当前进程不是受支持的游戏映像")
                else:
                    add("module", "游戏模块", "ok", "CraftWorld.exe 模块头已确认")

                is_v2 = self._detect_v2()
                manager_ptr_addr = base + (V2_RESOURCE_MGR if is_v2 else ITEM_BASE_OFFSET)
                manager = pm.read_int(manager_ptr_addr) if base else 0
                if not self._valid_runtime_pointer(manager):
                    add("resource_manager", "资源表", "error", "资源管理器尚未就绪；请进入已载入的存档后重试")
                else:
                    begin = pm.read_int(manager + (V2_RES_ARR_BASE if is_v2 else ITEM_ARR_PTR))
                    end = pm.read_int(manager + (V2_RES_ARR_END if is_v2 else ITEM_ARR_END))
                    stride = V2_RES_ELEM_SIZE if is_v2 else SLOT_SIZE
                    if (not self._valid_runtime_pointer(begin) or not self._valid_runtime_pointer(end) or
                            int(end) < int(begin) or (int(end) - int(begin)) % stride):
                        add("resource_vector", "资源数组", "error", "资源数组结构与当前版本不匹配")
                    else:
                        count = (int(end) - int(begin)) // stride
                        if count < 1 or count > 10000:
                            add("resource_vector", "资源数组", "error", "资源数组数量异常：%d" % count)
                        else:
                            add("resource_vector", "资源数组", "ok", "已确认 %d 个资源槽" % count)

                if not is_v2:
                    dwarf_mgr = (int(pm.read_int(base + 0xDC3614) or 0) & 0xFFFFFFFF) if base else 0
                    if not self._valid_runtime_pointer(dwarf_mgr):
                        add("dwarf_manager", "矮人列表", "warn", "矮人管理器尚未载入；矮人写入将保持禁用",
                            self.STATUS_FAILED)
                    else:
                        begin = int(pm.read_int(dwarf_mgr + 0x40) or 0) & 0xFFFFFFFF
                        end = int(pm.read_int(dwarf_mgr + 0x44) or 0) & 0xFFFFFFFF
                        if (not self._valid_runtime_pointer(begin) or not self._valid_runtime_pointer(end) or
                                int(end) < int(begin) or (int(end) - int(begin)) % 4 or
                                (int(end) - int(begin)) // 4 > 256):
                            add("dwarf_manager", "矮人列表", "warn", "矮人列表当前不可用；请载入存档后再修改矮人",
                                self.STATUS_FAILED)
                        else:
                            add("dwarf_manager", "矮人列表", "ok", "矮人列表结构已确认")
                else:
                    add("dwarf_manager", "矮人列表", "warn", "巨龙版矮人写入仍由各功能单独校验",
                        self.STATUS_UNSUPPORTED)
        except Exception as exc:
            add("doctor", "兼容检查", "error", "兼容检查读取失败：%s" % exc)

        # World writes intentionally remain outside the compatibility verdict.
        # The low-level layout can be readable while the semantics of a writer
        # have not yet been established for this game build/save state.
        add("world_write_policy", "世界写入入口", "可用",
            "保留地图、潘多拉、传送门、时间与波次等既有入口；Doctor 仅报告当前版本的定位状态，不会隐藏功能。",
            self.STATUS_UNVERIFIED)

        ok = not errors
        result = {
            "ok": ok, "write_ready": ok,
            "checked_pid": int(getattr(pm, "process_id", 0) or 0),
            "checked_at": time.strftime("%H:%M:%S"),
            "version": "巨龙版" if (pm and self._detect_v2()) else "Steam 原版",
            "checks": checks,
            "summary": "兼容检查通过，可安全使用已验证写入功能" if ok else (errors[0] if errors else "兼容检查未通过"),
        }
        with self._compatibility_doctor_lock:
            self._compatibility_doctor = result
        return result

    def get_compatibility_doctor(self, refresh=False):
        """Expose the latest read-only compatibility result to the UI."""
        with self._compatibility_doctor_lock:
            cached = dict(self._compatibility_doctor or {})
        if (refresh or not cached.get("checked_pid") or
                int(cached.get("checked_pid", 0) or 0) != int(getattr(pm, "process_id", 0) or 0)):
            cached = self._run_compatibility_doctor()
        # The Doctor result must also describe the hard boundary around legacy
        # world writes. This is metadata only: asking for it never probes or
        # changes game memory.
        result = dict(cached or {})
        result["write_policy"] = self.get_write_safety_status()
        return result

    @staticmethod
    def _preflight_file_hash(path):
        """Hash an executable incrementally; this is only called on demand."""
        digest = hashlib.sha256()
        with open(path, "rb") as handle:
            while True:
                block = handle.read(1024 * 1024)
                if not block:
                    break
                digest.update(block)
        return digest.hexdigest()

    def _preflight_executable_fingerprint(self, pid, base):
        """Read an evidence-oriented PE fingerprint without assuming a build."""
        result = {
            "state": self.STATUS_FAILED, "edition": "未识别", "exe_path": "",
            "exe_name": "", "exe_size": 0, "exe_sha256": "", "pe_timestamp": "",
            "module_base": "0x%X" % int(base or 0), "signatures": [],
        }
        try:
            import psutil
            exe_path = os.path.abspath(psutil.Process(int(pid)).exe())
            result.update({"exe_path": exe_path, "exe_name": os.path.basename(exe_path),
                           "exe_size": int(os.path.getsize(exe_path)),
                           "exe_sha256": self._preflight_file_hash(exe_path),
                           "edition": "巨龙版" if self._detect_v2() else "Steam 原版"})
            if os.path.basename(exe_path).lower() != MODULE_NAME.lower():
                result["state"] = self.STATUS_FAILED
                result["error"] = "当前修改器目标不是 CraftWorld.exe"
                return result
            result["state"] = self.STATUS_VERIFIED
        except Exception as exc:
            result["error"] = "主程序文件指纹读取失败：%s" % exc
            return result

        def raw_at(address, size):
            try:
                value = pm.read_bytes(int(address), int(size))
                return bytes(value or b"")
            except Exception:
                return b""

        mz = raw_at(base, 2)
        result["signatures"].append({
            "key": "module_mz", "label": "模块 DOS 头", "address": "0x%X" % int(base or 0),
            "expected": "4D 5A", "actual": mz.hex(" ").upper() or "未读取",
            "state": self.STATUS_VERIFIED if mz == b"MZ" else self.STATUS_FAILED,
            "detail": "CraftWorld.exe 映像 MZ 原始字节匹配" if mz == b"MZ" else "模块原始字节不匹配或无法读取",
        })
        pe_offset_raw = raw_at(int(base or 0) + 0x3C, 4)
        pe_offset = struct.unpack("<I", pe_offset_raw)[0] if len(pe_offset_raw) == 4 else 0
        pe = raw_at(int(base or 0) + pe_offset, 4) if pe_offset else b""
        timestamp_raw = raw_at(int(base or 0) + pe_offset + 8, 4) if pe == b"PE\0\0" else b""
        if len(timestamp_raw) == 4:
            timestamp = struct.unpack("<I", timestamp_raw)[0]
            result["pe_timestamp"] = "%d (0x%08X)" % (timestamp, timestamp)
        result["signatures"].append({
            "key": "module_pe", "label": "PE 签名", "address": "0x%X" % (int(base or 0) + pe_offset),
            "expected": "50 45 00 00", "actual": pe.hex(" ").upper() or "未读取",
            "state": self.STATUS_VERIFIED if pe == b"PE\0\0" else self.STATUS_FAILED,
            "detail": "PE 原始字节匹配；时间戳 %s" % (result["pe_timestamp"] or "未读取") if pe == b"PE\0\0" else "PE 头无法确认",
        })
        legacy_addr = int(base or 0) + int(self.LEGACY_SAVE_PATCH_RVA)
        legacy = raw_at(legacy_addr, len(self.LEGACY_SAVE_PATCH_BYTES))
        dangerous = legacy == self.LEGACY_SAVE_PATCH_BYTES
        result["signatures"].append({
            "key": "legacy_save_patch", "label": "旧存档补丁保护", "address": "0x%X" % legacy_addr,
            "expected": "不得为 " + self.LEGACY_SAVE_PATCH_BYTES.hex(" ").upper(),
            "actual": legacy.hex(" ").upper() or "未读取",
            "state": self.STATUS_FAILED if dangerous or not legacy else self.STATUS_VERIFIED,
            "detail": "检测到已知会破坏调用栈的旧补丁；禁止继续写入" if dangerous else ("未检测到已知危险旧补丁" if legacy else "无法读取该保护字节"),
        })
        return result

    def _preflight_runtime_capabilities(self, doctor):
        """Perform only small, read-only probes; never initiate a full scan."""
        rows = []
        def add(key, label, state, detail):
            rows.append({"key": key, "label": label, "state": state, "detail": detail})

        if not connected or not pm:
            for key, label in (("map", "地图读取"), ("dwarves", "矮人读取"),
                               ("equipment", "装备读取"), ("tasks", "任务 / Chronicles")):
                add(key, label, self.STATUS_FAILED, "未连接游戏，未执行运行时读取。")
            return rows
        try:
            map_info = self.map_status()
            if map_info.get("ok"):
                detail = "地图结构已解析"
                if map_info.get("changed"):
                    detail += "；地图缓存待重建，未进行全图读取"
                else:
                    detail += "；当前地图 %s × %s" % (map_info.get("width", "?"), map_info.get("height", "?"))
                add("map", "地图读取", "可用", detail)
            else:
                add("map", "地图读取", self.STATUS_FAILED, map_info.get("error") or "地图结构未准备好")
        except Exception as exc:
            add("map", "地图读取", self.STATUS_FAILED, str(exc))

        dwarf_check = next((row for row in doctor.get("checks", []) if row.get("key") == "dwarf_manager"), {})
        dwarves = _dwarf_cache_snapshot()
        if dwarf_check.get("verification") == self.STATUS_VERIFIED:
            add("dwarves", "矮人读取", "可用", "矮人列表结构已确认；当前缓存 %d 名（不会在体检中强制刷新）。" % len(dwarves))
        elif dwarves:
            add("dwarves", "矮人读取", self.STATUS_UNVERIFIED, "缓存有 %d 名矮人，但当前结构未在本次体检中确认。" % len(dwarves))
        else:
            add("dwarves", "矮人读取", self.STATUS_FAILED, dwarf_check.get("detail") or "尚未读到矮人列表")

        if self._detect_v2():
            add("equipment", "装备读取", self.STATUS_UNSUPPORTED, "装备结构目前仅验证 Steam 原版。")
        elif not dwarves:
            add("equipment", "装备读取", self.STATUS_UNVERIFIED, "没有已读取矮人样本；不会在体检中强制刷新矮人。")
        elif dwarves[0].get("idx") is None:
            add("equipment", "装备读取", self.STATUS_UNVERIFIED, "当前矮人缓存缺少稳定索引；不会猜测装备对象地址。")
        else:
            equipment = self.get_dwarf_equipment(int(dwarves[0].get("idx")))
            if equipment.get("ok"):
                add("equipment", "装备读取", "可用", "已对一名当前缓存矮人只读验证 %d 个装备槽。" % len(equipment.get("slots") or []))
            else:
                add("equipment", "装备读取", self.STATUS_FAILED, equipment.get("error") or "装备样本读取失败")

        try:
            world = self.get_world_diagnostics(False)
            task = ((world.get("tasks") or {}).get("runtime") or {})
            definitions = ((world.get("tasks") or {}).get("definitions") or [])
            if task.get("verification") == self.STATUS_VERIFIED:
                add("tasks", "任务 / Chronicles", "可用", task.get("reason") or "已验证运行时任务读取")
            elif definitions:
                add("tasks", "任务 / Chronicles", self.STATUS_UNVERIFIED,
                    "本地任务定义可读；实时任务阶段/目标仍未验证（不会在体检中触发全内存扫描）。")
            else:
                add("tasks", "任务 / Chronicles", task.get("verification") or self.STATUS_FAILED,
                    task.get("reason") or "任务定义或运行时状态未读取")
        except Exception as exc:
            add("tasks", "任务 / Chronicles", self.STATUS_FAILED, str(exc))
        return rows

    def _preflight_save_status(self):
        """Summarise save roots and backups without creating or modifying them."""
        state, processes, process_error = self._save_game_state()
        backup_root = self._save_backup_root()
        roots = []
        for root in self._save_roots():
            path = root.get("path", "")
            roots.append({"label": root.get("label", "存档目录"), "path": path,
                          "exists": os.path.isdir(path), "readable": os.access(path, os.R_OK) if os.path.isdir(path) else False})
        slots = []
        try:
            catalog = self.get_save_manager_catalog()
            for slot in catalog.get("slots", []):
                slots.append({"slot": slot.get("slot"), "profile_label": slot.get("profile_label"),
                              "files": len(slot.get("files") or []), "snapshots": len(slot.get("snapshots") or [])})
        except Exception as exc:
            process_error = (process_error + "；" if process_error else "") + "存档目录读取失败：%s" % exc
        return {
            "game_state": state, "processes": processes, "process_error": process_error,
            "roots": roots, "slots": slots, "backup_root": backup_root,
            "backup_exists": os.path.isdir(backup_root),
            "backup_writable": os.access(backup_root, os.W_OK) if os.path.isdir(backup_root) else os.access(os.path.dirname(backup_root), os.W_OK),
            "steam_cloud_warning": "Steam Cloud 可能在后续同步时覆盖本地存档；体检只提示风险，不修改 Steam Cloud 或存档。",
        }

    def get_connection_preflight_report(self, refresh=True):
        """Return the full on-demand connection preflight report (read-only)."""
        created_at = datetime.now().astimezone().isoformat(timespec="seconds")
        pid = int(getattr(pm, "process_id", 0) or 0) if connected and pm else 0
        base = int(get_base() or 0) if pid else 0
        doctor = self.get_compatibility_doctor(bool(refresh))
        fingerprint = self._preflight_executable_fingerprint(pid, base) if pid else {
            "state": self.STATUS_FAILED, "edition": "未识别", "exe_path": "", "exe_name": "",
            "exe_size": 0, "exe_sha256": "", "pe_timestamp": "", "module_base": "0x0",
            "signatures": [], "error": "未连接游戏进程",
        }
        capabilities = self._preflight_runtime_capabilities(doctor)
        policy = self.get_write_safety_status()
        save = self._preflight_save_status()
        process_ok = bool(pid and fingerprint.get("exe_name", "").lower() == MODULE_NAME.lower())
        connection = {
            "connected": bool(connected and pm), "pid": pid, "target_process": fingerprint.get("exe_name") or "未连接",
            "target_path": fingerprint.get("exe_path") or "", "state": "可用" if process_ok else self.STATUS_FAILED,
            "detail": "修改器已连接到 CraftWorld.exe（PID %d）" % pid if process_ok else (fingerprint.get("error") or "修改器尚未连接到正确的 CraftWorld.exe"),
            "ce_state": self.STATUS_UNVERIFIED,
            "ce_detail": "修改器无法可靠读取 Cheat Engine 当前目标；请在 CE 顶部进程栏手动确认 PID %s。" % (pid or "—"),
        }
        failed = [row for row in capabilities if row.get("state") == self.STATUS_FAILED]
        failed += [row for row in fingerprint.get("signatures", []) if row.get("state") == self.STATUS_FAILED]
        summary = "连接前体检完成：%d 项可用，%d 项读取失败，%d 项语义未验证；定位异常会报告，不会自动隐藏既有功能。" % (
            sum(1 for row in capabilities if row.get("state") == "可用"), len(failed),
            sum(1 for row in capabilities if row.get("state") == self.STATUS_UNVERIFIED))
        return {"ok": process_ok and not failed, "read_only": True, "report_version": 1,
                "created_at": created_at, "summary": summary, "connection": connection,
                "fingerprint": fingerprint, "doctor": doctor, "runtime_capabilities": capabilities,
                "write_policy": policy, "save": save}

    @staticmethod
    def _preflight_report_text(report):
        """Produce a compact, attachable plain-text counterpart to report JSON."""
        lines = ["Craft The World 修改器 — 连接前体检报告", "生成时间：" + str(report.get("created_at") or ""),
                 "摘要：" + str(report.get("summary") or ""), "", "[连接]"]
        conn = report.get("connection") or {}
        lines.extend(["状态：%s" % conn.get("state", "读取失败"), "PID：%s" % conn.get("pid", "—"),
                      "目标：%s" % conn.get("target_path", "未读取"), "CE：%s" % conn.get("ce_detail", "未验证")])
        fp = report.get("fingerprint") or {}
        lines.extend(["", "[主程序指纹]", "版本：%s" % fp.get("edition", "未识别"),
                      "大小：%s" % fp.get("exe_size", "—"), "SHA-256：%s" % fp.get("exe_sha256", "未读取"),
                      "PE 时间戳：%s" % fp.get("pe_timestamp", "未读取")])
        for row in fp.get("signatures") or []:
            lines.append("- [%s] %s：%s（期望 %s，实际 %s）" % (row.get("state"), row.get("label"), row.get("detail"), row.get("expected"), row.get("actual")))
        lines.append("\n[运行时能力]")
        for row in report.get("runtime_capabilities") or []:
            lines.append("- [%s] %s：%s" % (row.get("state"), row.get("label"), row.get("detail")))
        lines.append("\n[写入许可]")
        for row in (report.get("write_policy") or {}).get("entries") or []:
            lines.append("- [%s] %s：%s" % (row.get("state"), row.get("feature"), row.get("reason")))
        save = report.get("save") or {}
        lines.extend(["", "[存档与备份]", "游戏状态：%s" % save.get("game_state", "未知"),
                      "备份目录：%s（存在=%s，可写=%s）" % (save.get("backup_root", ""), save.get("backup_exists"), save.get("backup_writable")),
                      "提示：%s" % save.get("steam_cloud_warning", "")])
        for root in save.get("roots") or []:
            lines.append("- 存档根目录 %s：%s（存在=%s，可读=%s）" % (root.get("label"), root.get("path"), root.get("exists"), root.get("readable")))
        for slot in save.get("slots") or []:
            lines.append("- %s / %s：%s 个文件，%s 个快照" % (slot.get("profile_label"), slot.get("slot"), slot.get("files"), slot.get("snapshots")))
        return "\n".join(lines) + "\n"

    def export_connection_preflight_report(self):
        """Export local JSON/TXT diagnostics; game memory and saves stay read-only."""
        report = self.get_connection_preflight_report(True)
        root = os.path.join(_application_dir(), "diagnostics")
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        pid = int((report.get("connection") or {}).get("pid") or 0)
        stem = "ctw_preflight_%s_pid%s" % (stamp, pid or "offline")
        try:
            os.makedirs(root, exist_ok=True)
            json_path, text_path = os.path.join(root, stem + ".json"), os.path.join(root, stem + ".txt")
            for path, content in ((json_path, json.dumps(report, ensure_ascii=False, indent=2)),
                                  (text_path, self._preflight_report_text(report))):
                tmp = path + ".tmp"
                with open(tmp, "w", encoding="utf-8", newline="\n") as handle:
                    handle.write(content)
                    handle.flush()
                    os.fsync(handle.fileno())
                os.replace(tmp, path)
            return {"ok": True, "json_path": json_path, "text_path": text_path, "report": report}
        except Exception as exc:
            return {"ok": False, "error": "诊断报告导出失败：%s" % exc, "report": report}

    def _stable_baseline_file(self, path):
        """Return a compact, human-checkable source fingerprint without writes."""
        absolute = os.path.abspath(path)
        try:
            with open(absolute, "rb") as handle:
                digest = hashlib.sha256(handle.read()).hexdigest()[:12]
            return {"path": absolute, "exists": True, "sha256": digest}
        except Exception as exc:
            return {"path": absolute, "exists": False, "sha256": "", "error": str(exc)}

    @staticmethod
    def _stable_baseline_row(key, label, status, detail):
        return {"key": key, "label": label, "status": status, "detail": detail}

    def get_stable_baseline_status(self):
        """Expose the exact running source pair and the safe-write policy.

        This intentionally does not read game memory. It is safe to call before
        connecting and makes an old copied script immediately visible in the UI.
        """
        packaged = bool(getattr(sys, "frozen", False))
        script_path = os.path.abspath(sys.executable if packaged else __file__)
        source_dir = _application_dir() if packaged else os.path.dirname(script_path)
        ui_path = _resource_path("ui_v1.0.html")
        # A packaged build has no source .py beside the EXE; its stable pair is
        # the executable plus the resolved UI resource. In source mode the
        # active directory is the explicit test/release target.
        expected_root = source_dir
        script_info = self._stable_baseline_file(script_path)
        ui_info = self._stable_baseline_file(ui_path)
        expected = os.path.normcase(source_dir) == os.path.normcase(expected_root)
        source_status = "可用" if (expected and script_info.get("exists") and ui_info.get("exists")) else "读取失败"
        source_detail = ("实际启动源：%s | Python #%s | HTML #%s" % (
            source_dir, script_info.get("sha256") or "—", ui_info.get("sha256") or "—"
        ))
        if not expected:
            source_detail = "当前脚本不在稳定版目录：%s；应从 %s 启动" % (source_dir, expected_root)
        elif not script_info.get("exists") or not ui_info.get("exists"):
            source_detail = "稳定版源文件不完整：%s" % (script_info.get("error") or ui_info.get("error") or "未知错误")
        readback = getattr(self, "_stable_baseline_save_readback", None)
        if isinstance(readback, dict) and readback.get("ok"):
            readback_status = "可用"
            readback_detail = ("已完成当前会话的单矮人生命同值写入与即时读回："
                               "#%d %s，%.1f → %.1f。" % (
                                   int(readback.get("idx", -1)),
                                   str(readback.get("name", "未命名")),
                                   float(readback.get("before", 0.0)),
                                   float(readback.get("after", 0.0))))
        elif isinstance(readback, dict):
            readback_status = "读取失败"
            readback_detail = "当前会话的同值写后读回失败：%s" % (readback.get("error") or "未知错误")
        else:
            readback_status = "语义未验证"
            readback_detail = "尚未执行当前会话的单对象同值写后读回；不会因此把写入功能伪装成可用。"
        checks = [
            self._stable_baseline_row("runtime_source", "运行来源", source_status, source_detail),
            self._stable_baseline_row("map_edit", "地图编辑写入",
                                      "已开启" if self.MAP_DIRECT_WRITES_ENABLED else "可手动开启",
                                      "地图页可手动开关编辑；其它世界入口保留并由各功能自身校验。"),
            self._stable_baseline_row("save_readback", "保存与读回", readback_status, readback_detail),
        ]
        return {"ok": source_status == "可用", "checked_at": time.strftime("%H:%M:%S"),
                "script": script_info, "ui": ui_info, "expected_root": expected_root,
                "connected_pid": int(getattr(pm, "process_id", 0) or 0) if connected and pm else 0,
                "checks": checks}

    def run_stable_baseline_regression(self):
        """Run an explicit, read-only real-game regression for stable features.

        No game value, map tile, save file, equipment or skill is written here.
        A write/readback result remains semantically unverified until a user
        chooses a deliberate, narrowly scoped verification in the UI.
        """
        report = self.get_stable_baseline_status()
        checks = list(report.get("checks", []))
        def add(key, label, status, detail):
            checks.append(self._stable_baseline_row(key, label, status, detail))
        if not pm or not connected:
            for key, label in (("dwarf_refresh", "矮人刷新"), ("map_local_refresh", "地图局部刷新"),
                               ("item_filter", "物品筛选"), ("equipment_read", "装备编辑读取"),
                               ("personal_skill_read", "个人技能读取")):
                add(key, label, "读取失败", "未连接游戏，未执行读取。")
            report.update({"ok": False, "checks": checks,
                           "summary": "未连接游戏；仅确认了稳定版运行来源与写入策略。"})
            return report
        doctor = self.get_compatibility_doctor(True)
        if not doctor.get("ok"):
            add("compatibility", "版本结构", "版本不支持", doctor.get("summary") or "兼容检查未通过")
        else:
            add("compatibility", "版本结构", "可用", doctor.get("summary") or "兼容结构已通过只读检查")
        dwarves = []
        try:
            dwarves = self.scan_dwarves_stable()
            expected_dwarves = None if self._detect_v2() else self._v1_dwarf_vector_count()
            if isinstance(dwarves, list) and expected_dwarves is not None and len(dwarves) < expected_dwarves:
                add("dwarf_refresh", "矮人刷新", "读取失败", "矮人列表正在变动：结构为 %d 名，稳定读取到 %d 名；不会把缺失伪装成空数据。" % (expected_dwarves, len(dwarves)))
            elif isinstance(dwarves, list) and dwarves:
                ready = sum(1 for row in dwarves if isinstance(row, dict) and row.get("skills_ready"))
                add("dwarf_refresh", "矮人刷新", "可用", "已读取 %d 名矮人；个人技能就绪 %d 名。" % (len(dwarves), ready))
            elif isinstance(dwarves, list):
                add("dwarf_refresh", "矮人刷新", "读取失败", "矮人列表为空；可能正在载入存档或当前版本结构不匹配。")
            else:
                add("dwarf_refresh", "矮人刷新", "读取失败", "矮人读取返回了无效结构。")
        except Exception as exc:
            add("dwarf_refresh", "矮人刷新", "读取失败", "矮人读取异常：%s" % exc)
        try:
            map_meta = self.map_metadata()
            if not map_meta.get("ok"):
                add("map_local_refresh", "地图局部刷新", "读取失败", map_meta.get("error") or "地图元数据读取失败")
            else:
                width, height = int(map_meta.get("width", 0)), int(map_meta.get("height", 0))
                if width < 1 or height < 1:
                    add("map_local_refresh", "地图局部刷新", "读取失败", "地图尺寸无效：%dx%d" % (width, height))
                else:
                    row, col = height // 2, width // 2
                    region = self.map_read_regions([{"r0": row, "c0": col, "r1": row, "c1": col}])
                    if region.get("ok") and not region.get("changed"):
                        add("map_local_refresh", "地图局部刷新", "可用", "已读取中心 1×1 区块；地图 %d×%d。" % (width, height))
                    elif region.get("changed"):
                        add("map_local_refresh", "地图局部刷新", "读取失败", "地图缓冲区在回归期间改变，请重新执行回归。")
                    else:
                        add("map_local_refresh", "地图局部刷新", "读取失败", region.get("error") or "局部区块返回无效")
        except Exception as exc:
            add("map_local_refresh", "地图局部刷新", "读取失败", "地图局部读取异常：%s" % exc)
        # This retired read-only regression must never alter the user's
        # explicit map-edit session state.  It only reports the current state.
        map_enabled = bool(self.MAP_DIRECT_WRITES_ENABLED)
        add("map_edit_gate", "地图编辑开关", "可用" if map_enabled else "写入已关闭",
            "当前地图编辑%s；可由地图页的手动开关切换。" % ("已开启" if map_enabled else "已关闭"))
        try:
            count = int(self.scan_items() or 0)
            rows = self.get_items(0, min(80, max(1, count))) if count else []
            if count > 0 and isinstance(rows, list):
                add("item_filter", "物品筛选", "可用", "已读取 %d 个物品；筛选数据源有效。" % count)
            elif count == 0:
                add("item_filter", "物品筛选", "读取失败", "物品容器为空或未能识别；不会把空列表伪装成可用。")
            else:
                add("item_filter", "物品筛选", "读取失败", "物品筛选数据结构无效。")
        except Exception as exc:
            add("item_filter", "物品筛选", "读取失败", "物品读取异常：%s" % exc)
        if not dwarves:
            add("equipment_read", "装备编辑读取", "读取失败", "没有可验证的矮人对象。")
            add("personal_skill_read", "个人技能读取", "读取失败", "没有可验证的矮人对象。")
        else:
            idx = int(dwarves[0].get("idx", 0))
            try:
                equipment = self.get_dwarf_equipment(idx)
                if equipment.get("ok") and isinstance(equipment.get("slots"), list):
                    add("equipment_read", "装备编辑读取", "可用", "已读取矮人 #%d 的 %d 个装备槽。" % (idx, len(equipment.get("slots", []))))
                else:
                    detail = equipment.get("error") or "装备槽返回无效"
                    status = "版本不支持" if "仅验证" in detail or "版本" in detail else "读取失败"
                    add("equipment_read", "装备编辑读取", status, detail)
            except Exception as exc:
                add("equipment_read", "装备编辑读取", "读取失败", "装备读取异常：%s" % exc)
            try:
                row = next((item for item in dwarves if int(item.get("idx", -1)) == idx), {})
                skills = row.get("skills") if isinstance(row, dict) else None
                if row.get("skills_ready") and isinstance(skills, list):
                    add("personal_skill_read", "个人技能读取", "可用", "已读取矮人 #%d 的 %d 项个人技能。" % (idx, len(skills)))
                elif isinstance(skills, list):
                    add("personal_skill_read", "个人技能读取", "语义未验证", "技能记录暂未完全就绪；显示为空不等于没有技能。")
                else:
                    add("personal_skill_read", "个人技能读取", "读取失败", "个人技能读取结构无效。")
            except Exception as exc:
                add("personal_skill_read", "个人技能读取", "读取失败", "个人技能读取异常：%s" % exc)
        summary_counts = {}
        for row in checks:
            summary_counts[row.get("status", "读取失败")] = summary_counts.get(row.get("status", "读取失败"), 0) + 1
        report.update({"ok": all(row.get("status") not in ("读取失败", "版本不支持") for row in checks),
                       "checks": checks, "doctor": doctor,
                       "summary": " · ".join("%s %d" % (key, value) for key, value in summary_counts.items()),
                       "checked_at": time.strftime("%H:%M:%S")})
        return report

    def _require_safe_write(self, feature):
        """Require a live target; Doctor remains diagnostic, not a feature gate."""
        if not pm or not connected:
            return "请先连接游戏"
        return ""

    def _require_high_risk_world_write(self, feature):
        """Keep the minimum runtime guard for restored legacy world actions.

        The former stable-build policy used this helper as an unconditional
        deny switch.  That made implemented controls appear available while
        every request was refused.  Feature methods still perform their own
        map/object/range checks; this only blocks detached-process writes.
        """
        if not pm or not connected:
            return "请先连接游戏后再执行%s" % feature
        return ""

    def get_write_safety_status(self):
        """Return the authoritative state of every legacy write entrypoint.

        Kept separate from Compatibility Doctor so the UI (and a stale cached
        page) can explain a blocked operation without touching game memory.
        """
        rows = []
        for endpoint, policy in _WRITE_SAFETY_POLICY.items():
            rows.append({
                "endpoint": endpoint,
                "feature": policy["feature"],
                "state": policy["state"],
                # Verified endpoints do not need a block reason. Keep the
                # diagnostics schema uniform without making normal writes
                # fail merely because that optional description is absent.
                "reason": policy.get("reason", "已完成独立验证，可在对应功能中使用。"),
            })
        rows.sort(key=lambda row: (row["state"], row["feature"], row["endpoint"]))
        return {
            "ok": True,
            "read_only": False,
            "safe_state": WRITE_SAFETY_VERIFIED,
            "user_tested_state": WRITE_SAFETY_USER_TESTED,
            "experimental_state": WRITE_SAFETY_EXPERIMENTAL,
            "disabled_state": WRITE_SAFETY_DISABLED,
            "safe_count": sum(1 for row in rows if row["state"] == WRITE_SAFETY_VERIFIED),
            "user_tested_count": sum(1 for row in rows if row["state"] == WRITE_SAFETY_USER_TESTED),
            "experimental_count": sum(1 for row in rows if row["state"] == WRITE_SAFETY_EXPERIMENTAL),
            "disabled_count": sum(1 for row in rows if row["state"] == WRITE_SAFETY_DISABLED),
            "entries": rows,
        }

    @staticmethod
    def _game_version_info(exe_path):
        """Return a truthful, read-only version label for the running game.

        The current CraftWorld Steam PE has no usable semantic file version,
        so its Steam appmanifest buildid is the only stable release marker.
        Keep the source and state in the response so the UI can distinguish a
        real read from an unavailable/non-Steam version.
        """
        path = os.path.abspath(str(exe_path or "")) if exe_path else ""
        file_version = _read_windows_file_version(path)
        if file_version:
            return {"ok": True, "display": "游戏版本 " + file_version,
                    "file_version": file_version, "steam_build_id": "",
                    "source": "CraftWorld.exe 文件版本", "state": "已读取",
                    "detail": "已读取 CraftWorld.exe 的正式文件版本"}
        build_id = _read_steam_build_id(path)
        if build_id:
            return {"ok": True, "display": "Steam 构建 " + build_id,
                    "file_version": "", "steam_build_id": build_id,
                    "source": "Steam appmanifest", "state": "已读取",
                    "detail": "当前 CraftWorld.exe 对应 Steam 构建 " + build_id}
        if not path:
            detail = "未读取到 CraftWorld.exe 路径"
        elif not os.path.isfile(path):
            detail = "CraftWorld.exe 文件不存在或路径不可读"
        else:
            detail = "程序没有文件版本信息，且未找到 Steam appmanifest buildid"
        return {"ok": False, "display": "未识别", "file_version": "",
                "steam_build_id": "", "source": "", "state": "未识别",
                "detail": detail}

    def get_game_version(self, pid=0):
        """Read the current game's version marker without touching memory."""
        try:
            import psutil
            target_pid = int(pid or getattr(pm, "process_id", 0) or 0)
            if not target_pid:
                return {"ok": False, "display": "未连接", "state": self.STATUS_DISCONNECTED,
                        "source": "", "detail": "尚未连接游戏进程"}
            exe_path = psutil.Process(target_pid).exe()
            return self._game_version_info(exe_path)
        except Exception as exc:
            return {"ok": False, "display": "未识别", "state": "未识别",
                    "source": "", "detail": "游戏版本读取失败：%s" % exc}

    LEVEL_CONFIG_SINGLETON_RVA = 0xDC3E64
    LEVEL_CONFIG_SOURCE_OFF = 0xC8
    LEVEL_CONFIG_WORLD_OFF = 0x270
    LEVEL_CONFIG_SIZE_OFF = 0x288
    LEVEL_CONFIG_HUMIDITY_OFF = 0x2A0
    LEVEL_CONFIG_LANDSCAPE_OFF = 0x2B8
    LEVEL_CONFIG_TEMPERATURE_OFF = 0x2D0
    LEVEL_CONFIG_NAME_OFF = 0x318
    LEVEL_CONFIG_DIFFICULTY_OFF = 0x330

    @staticmethod
    def _overview_label(value, labels):
        raw = str(value or "").strip()
        return labels.get(raw.lower(), raw or "未读取")

    @staticmethod
    def _overview_level_definition(source):
        """Read the active campaign level's authored settings, if available.

        ``LevelConfig`` keeps several copied strings, but campaign maps do not
        consistently populate every one after a world switch.  The currently
        loaded ``levels/*.xml`` is the authoritative definition for static
        settings such as difficulty and humidity, and is safe to inspect.
        """
        try:
            relative = str(source or "").replace("\\", "/").strip().lstrip("/")
            if not relative.lower().startswith("levels/") or not relative.lower().endswith(".xml"):
                return {}
            game_root = os.path.abspath(GAME_ROOT)
            filename = os.path.abspath(os.path.join(game_root, relative.replace("/", os.sep)))
            if os.path.commonpath((game_root, filename)) != game_root or not os.path.isfile(filename):
                return {}
            root = ET.parse(filename).getroot()
            params = root.find("./level/params")
            if params is None:
                return {}
            fields = {
                "planetType": "world_key", "sizeTemplate": "size_key",
                "humidityTemplate": "humidity_key", "lanscapeTemplate": "landscape_key",
                "temperatureTemplate": "temperature_key", "difficulty": "difficulty_key",
                "techTreeTemplate": "tech_tree_key",
            }
            result = {}
            for tag, field in fields.items():
                node = params.find(tag)
                value = str(node.get("value") or "").strip() if node is not None else ""
                if value:
                    result[field] = value
            return result
        except Exception:
            return {}

    @staticmethod
    def _overview_source_display(source, campaign):
        normalized = str(source or "").replace("\\", "/").strip()
        match = re.fullmatch(r"levels/(\d+)\.xml", normalized, flags=re.IGNORECASE)
        if match:
            return "战役第%s关" % int(match.group(1))
        if campaign:
            return "战役关卡"
        return "自定义世界"

    def _read_level_config_overview(self):
        """Return verified LevelConfig fields for the startup overview.

        The singleton and string offsets were read from the live Steam V1
        object.  This path is deliberately observational: unsupported builds
        return an explicit unavailable state rather than inferred world data.
        """
        try:
            module_base = int(get_base())
            config = int(pm.read_int(module_base + self.LEVEL_CONFIG_SINGLETON_RVA) or 0)
            if config < 0x10000:
                return None, "世界配置尚未加载"
            source = _read_msvc_string(pm, config + self.LEVEL_CONFIG_SOURCE_OFF, 260)
            world_key = _read_msvc_string(pm, config + self.LEVEL_CONFIG_WORLD_OFF, 80)
            size_key = _read_msvc_string(pm, config + self.LEVEL_CONFIG_SIZE_OFF, 80)
            humidity_key = _read_msvc_string(pm, config + self.LEVEL_CONFIG_HUMIDITY_OFF, 80)
            landscape_key = _read_msvc_string(pm, config + self.LEVEL_CONFIG_LANDSCAPE_OFF, 80)
            temperature_key = _read_msvc_string(pm, config + self.LEVEL_CONFIG_TEMPERATURE_OFF, 80)
            world_name = _read_msvc_string(pm, config + self.LEVEL_CONFIG_NAME_OFF, 120)
            difficulty_key = _read_msvc_string(pm, config + self.LEVEL_CONFIG_DIFFICULTY_OFF, 80)
            if not any((source, world_key, size_key, humidity_key, landscape_key, difficulty_key)):
                return None, "世界配置字段未通过校验"

            source_lower = source.replace("\\", "/").lower()
            campaign = source_lower.startswith("levels/")
            # Campaign XML supplies the values LevelConfig leaves blank or
            # stale after switching worlds.  It describes the loaded map,
            # while live memory remains the source for its identity.
            level_values = self._overview_level_definition(source) if campaign else {}
            world_key = level_values.get("world_key") or world_key
            size_key = level_values.get("size_key") or size_key
            humidity_key = level_values.get("humidity_key") or humidity_key
            landscape_key = level_values.get("landscape_key") or landscape_key
            temperature_key = level_values.get("temperature_key") or temperature_key
            difficulty_key = level_values.get("difficulty_key") or difficulty_key
            tech_tree_key = level_values.get("tech_tree_key") or ("default_techtree" if campaign else "")
            return {
                "source": source,
                "source_display": self._overview_source_display(source, campaign),
                "mode": "战役" if campaign else "自定义游戏",
                "world": self._overview_label(world_key, {
                    "usual_medium": "森林", "biome_usual_medium": "森林",
                    "usual_cold": "冰雪", "cold": "冰雪",
                    "usual_desert": "沙漠", "hot": "沙漠",
                    "underground": "地底", "biome_underground": "地底",
                    "dlc_temples": "山谷", "lonely_mountain": "孤山",
                    "two_fortress": "双塔奇兵", "wonderwood": "奇妙的森林",
                    "biome1": "狂野平原", "biome_beetles": "极寒冰洞",
                }) if world_key else (world_name or "未读取"),
                "world_key": world_key,
                "size": self._overview_label(size_key, {
                    "small": "小型", "normal": "中型", "medium": "中型", "large": "大型",
                    "large_vertical": "大型（纵向）", "huge": "巨大",
                }),
                "weather": self._overview_label(humidity_key, {
                    "low": "低湿度", "normal": "标准湿度", "high": "高湿度",
                    "dry": "干燥", "wet": "潮湿", "rainy": "多雨",
                }),
                "terrain": self._overview_label(landscape_key, {
                    "plain": "平原", "hills": "丘陵", "mountains": "山地",
                }),
                "temperature": self._overview_label(temperature_key, {
                    "cold": "寒冷", "normal": "适中", "hot": "炎热",
                }),
                "difficulty": self._overview_label(difficulty_key, {
                    "very_easy": "非常简单", "easy": "简单", "normal": "普通",
                    "hard": "困难", "very_hard": "非常困难", "nightmare": "噩梦",
                }),
                "tech_mode": self._overview_label(tech_tree_key, {
                    "default_techtree": "默认科技树", "underground_techtree": "地下世界科技树",
                    "mountain_techtree": "高山科技树", "fortresses_techtree": "堡垒科技树",
                    "ww_dlc_techtree": "奇妙森林科技树",
                }),
            }, ""
        except Exception as exc:
            return None, "世界配置读取失败：%s" % exc

    def get_overview_state(self):
        """Read the small, read-only snapshot used by the overview homepage."""
        if not connected or not pm:
            return {"ok": False, "state": self.STATUS_DISCONNECTED,
                    "error": "请先连接游戏并进入已载入的地图"}
        details, error = self._read_level_config_overview()
        game_version = self.get_game_version(pm.process_id)
        response = {
            "ok": details is not None,
            "state": self.STATUS_VERIFIED if details else self.STATUS_STALE,
            "game_version": game_version,
            "world": details or {},
            "error": error,
            "day_count": None,
            "time_state": "读取中",
        }
        time_state = self.get_game_time_state()
        if time_state.get("ok"):
            response["day_count"] = time_state.get("day_count")
            response["time_state"] = time_state.get("phase", "已读取")
        elif time_state.get("error"):
            response["time_state"] = time_state.get("error")
        return response

    def list_processes(self):
        """列出所有 CraftWorld.exe 进程"""
        import psutil
        try:
            matches = []
            for p in psutil.process_iter(['pid', 'name']):
                try:
                    nm = p.info.get('name', '')
                except Exception:
                    continue
                if nm and nm.lower() == MODULE_NAME.lower():
                    try:
                        exe_path = p.exe()
                    except Exception:
                        exe_path = ""
                    ver = "v1 \u539f\u7248"
                    exe_lower = exe_path.lower()
                    if "dragon" in exe_lower or "\u5de8\u9f99" in exe_path:
                        ver = "v2 \u5de8\u9f99\u7248"
                    matches.append({"pid": p.info['pid'], "label": ver, "exe": exe_path})
                    if len(matches) >= 2:
                        break
            return matches
        except Exception:
            return []

    def connect(self, pid=0):
        """连接到游戏进程"""
        return self.connect_pid(pid)
    def connect_pid(self, pid=0):
        """通过 PID 连接到游戏进程"""
        self._begin_runtime_session()
        # A reconnect must not let a writer from the old process continue with
        # the newly assigned global pm object. The serialized connect gate is
        # held by the API wrapper, so clear every recurring writer first.
        self.locks["gold"] = False
        self._stop_gold_economy_runtime()
        self._stop_mana_reserve_runtime()
        self.locks["mana"] = False
        self.locks["xp"] = False
        self._lock_restore_active = False
        self._set_mana_max_lock_runtime(False, None)
        self._clear_timer_locks()
        with self._portal_lock_guard:
            self._portal_locks.clear()
        self._restore_pet_limit_override_internal()
        self._dispose_dwarf_population_controller()
        self._dispose_wave_portal_controller()
        self._v2_cache = None
        self._other_feature_profile_cache = {"pid": 0, "exe_path": "", "profile": None}
        self._skill_base_cache = None
        self._skill_base_ver = None
        self._magic_cache = {}
        self._magic_scan_ms = 0
        self._magic_process_id = 0
        self._magic_scan_running = False
        self._magic_scan_completed = False
        self._magic_scan_error = ""
        self._magic_stable_values = {}
        self._native_magic_resources = {}
        self._pandora_cache = None
        self._pandora_cache_pid = 0
        self._pandora_scan_ms = 0
        self._pandora_forced_key = ""
        self._clear_pandora_runtime_cache()
        self._v2_portal_objects = []
        self._v2_portal_scan_at = 0.0
        self._v2_portal_scan_pid = 0
        self._clear_time_controls_cache()
        self._map_cache_signature = None
        self._map_cache_key = ""
        self._world_object_occupancy_cache = {"scope": None, "items": {}}
        self._special_entity_item_cache = {"scope": None, "items": {}}
        self._structure_save_identity_cache = {"pid": 0, "value": ""}
        # Structure annotations are deliberately session-only until the
        # game's native Room/UnderRoom container has been located.  Never
        # carry records from an earlier process or save into this session.
        with self._structure_history_lock:
            self._structure_runtime_history = []
        self._pet_house_runtime_cache = {"pid": 0, "base": 0, "at": 0.0, "houses": [], "pets": []}
        self._pet_limit_override_original = None
        self._pet_limit_override_value = None
        self._load_dwarf_names()
        self._load_item_config()
        global pm, connected, dwarf_cache, item_cache
        try:
            if pid and pid > 0:
                _diagnostic("Connecting to PID:", pid)
                pm = pymem.Pymem(); pm.open_process_from_id(pid); connected = True; get_base()
            else:
                _diagnostic("Connecting by name:", MODULE_NAME)
                pm = pymem.Pymem(MODULE_NAME); connected = True; get_base()
            if self._has_legacy_save_patch():
                # Never try to repair executable bytes in a running process.
                # A full game restart restores the clean image safely.
                pm = None; connected = False; dwarf_cache = []; item_cache = []
                return {"success":False,"error":"检测到旧版修改器遗留的存档代码补丁；请完全退出并重新启动游戏后再连接"}
            native_layout = self._apply_v1_native_layout()
            # Start the independent DayTime locator before roster/item reads.
            # This lets the overview receive the saved-day value during the
            # existing connection work instead of only at the end.
            self._start_time_controls_scan()
            doctor = self._run_compatibility_doctor()
            self.scan_dwarves_stable()
            self.scan_items()
            self.scan_shop()
            self._restore_mana_max_lock()
            # Magic parameters are loaded lazily when the Magic tab is opened.
            # They use a broad heap pass; keeping that work out of connection
            # avoids delaying the independent time reader and the first usable
            # game state.
            dwarf_state = _get_cached_read_state("dwarves")
            item_state = _get_cached_read_state("items")
            game_version = self.get_game_version(pm.process_id)
            return {"success":True,"pid":pm.process_id,
                    # A count is meaningful only after a verified read.  Do
                    # not turn a locator failure into a convincing-looking 0
                    # in the connection banner.
                    "dwarves": len(dwarf_cache) if dwarf_state.get("state") == self.STATUS_VERIFIED else None,
                    "items": len(item_cache) if item_state.get("state") == self.STATUS_VERIFIED else None,
                    "dwarves_state": dwarf_state,
                    "items_state": item_state,
                    "magic":None,"magic_scanning":False,"magic_unloaded":True,"doctor":doctor,
                    "native_layout": native_layout,
                    "game_version": game_version}
        except Exception as e:
            return {"success":False,"error":str(e)}

    def _has_legacy_save_patch(self):
        """Detect, but deliberately never modify, the known corrupt code patch."""
        try:
            raw = pm.read_bytes(get_base() + self.LEGACY_SAVE_PATCH_RVA, 3)
            return raw == self.LEGACY_SAVE_PATCH_BYTES
        except Exception:
            return False

    def disconnect(self):
        """断开与游戏进程的连接"""
        self._restore_pet_limit_override_internal()
        self._end_runtime_session()
        self._set_mana_max_lock_runtime(False, None)
        self._lock_restore_active = False
        self.locks["gold"] = False
        self._stop_gold_economy_runtime()
        self._stop_mana_reserve_runtime()
        self.locks["mana"] = False
        self.locks["xp"] = False
        self._clear_timer_locks()
        self._dispose_dwarf_population_controller()
        self._dispose_wave_portal_controller()
        self._v2_cache = None
        self._v1_native_layout = {"key": "unknown", "label": "未收录版本",
                                  "recognized": False, "sha256": "", "error": "已断开游戏"}
        self._other_feature_profile_cache = {"pid": 0, "exe_path": "", "profile": None}
        global pm, connected, dwarf_cache, item_cache
        try:
            if pm and (self._pa1 or self._pa2):
                b = get_base()
                if self._pa1 and self._pet_house_original:
                    is_v2 = self._detect_v2()
                    off = V2_PET_LIMIT1_OFFSET if is_v2 else V1_PET_LIMIT1_OFFSET
                    pm.write_bytes(b + off, self._pet_house_original, len(self._pet_house_original))
                for off, raw in self._pet_infinite_original.items():
                    pm.write_bytes(b + off, raw, len(raw))
        except Exception:
            pass
        self._pa1 = False
        self._pa2 = False
        self._pet_house_original = None
        self._pet_infinite_original = {}
        self._portal_locks = {}
        self._portal_samples = {}
        self._portal_stability = {}
        self._v2_portal_objects = []
        self._v2_portal_scan_at = 0.0
        self._v2_portal_scan_pid = 0
        self._magic_cache = {}
        self._magic_scan_ms = 0
        self._magic_process_id = 0
        self._magic_scan_running = False
        self._magic_scan_completed = False
        self._magic_scan_error = ""
        self._magic_stable_values = {}
        self._native_magic_resources = {}
        self._clear_pandora_runtime_cache()
        self._clear_time_controls_cache()
        self._map_cache_signature = None
        self._map_cache_key = ""
        self._world_object_occupancy_cache = {"scope": None, "items": {}}
        self._special_entity_item_cache = {"scope": None, "items": {}}
        with self._structure_history_lock:
            self._structure_runtime_history = []
        self._pet_house_runtime_cache = {"pid": 0, "base": 0, "at": 0.0, "houses": [], "pets": []}
        self._pet_limit_override_original = None
        self._pet_limit_override_value = None
        with self._compatibility_doctor_lock:
            self._compatibility_doctor = {"ok": False, "write_ready": False,
                                          "checked_pid": 0, "checks": [],
                                          "summary": "已断开游戏"}
        # Clear the global handle before the serialized wrapper joins workers.
        # A stale scanner can then only observe an invalid session and exit;
        # it can never publish data from a detached/reused process.
        pm=None;connected=False;dwarf_cache=[];item_cache=[]
        _set_cached_read_state("dwarves", self.STATUS_DISCONNECTED, "已断开游戏连接")
        _set_cached_read_state("items", self.STATUS_DISCONNECTED, "已断开游戏连接")
        return True


    # ==================== ?????? ====================
    MAP_COL_W = 0x20
    MAP_DATA_OFF = 0x20
    MAP_BLOCK_SIZE = 0xB4000
    MAP_SAFE_EDIT_LIMIT = 128
    # Whole-map exploration only changes the proven per-tile exploration bit.
    # Keep its larger limit separate from regular map edit operations.
    MAP_EXPLORE_ALL_MAX_CELLS = 250000
    MAP_DIRECT_WRITES_ENABLED = False
    # Read-only live refresh limits.  The browser uses small dwarf-nearby
    # regions plus one background band, so normal worlds stay far below this.
    MAP_REGION_MAX_COUNT = 24
    MAP_REGION_MAX_CELLS = 150000
    MAP_EMPTY = bytes.fromhex("FF FF FF FF FF FF 00 00 00 00 00 00 00 00 FF 32 00 00 00 00 00 00 00 00 00 00 00 00 00 00 80 3F")

    def _map_row_stride(self, width):
        """The map payload is tightly packed; its row width changes per save."""
        return int(width) * self.MAP_COL_W

    def _map_identity(self, width, height, world_width, world_height, payload):
        """Build a stable per-map key.

        The previous key sampled tile metadata.  Native room placement changes
        those bytes, so every placement silently moved annotations to a new
        key and made earlier structures disappear.  Dimensions are stable for
        the lifetime of a save and are sufficient for the local annotation
        cache; the payload argument remains for call-site compatibility.
        """
        digest = __import__("hashlib").blake2s(digest_size=12)
        digest.update(f"{width}x{height}:{world_width:.1f}x{world_height:.1f}".encode("ascii"))
        return "world-" + digest.hexdigest()

    def _map_cache_id(self, data, width, height, world_width, world_height):
        """Small identity used by map_status; it deliberately reads no tiles."""
        try:
            pid = int(pm.process_id) if pm else 0
        except Exception:
            pid = 0
        return (pid, int(data), int(width), int(height),
                round(float(world_width), 3), round(float(world_height), 3))

    def _structure_map_key(self):
        """Return a persistent save key for structure annotations on demand.

        ``map_metadata`` intentionally avoids reading tile data and has only a
        process-local key. Structure annotations are rare and need to survive
        a restart, so this path reads the map once and uses the same stable
        identity already used by per-save map pins.
        """
        resolved = self._map_resolve()
        if not resolved:
            return ""
        data, width, height, world_width, world_height = resolved
        # Keep the same stable dimensions/world-size identity used by the
        # full map scan.  This intentionally survives restarting the modifier,
        # while native Room records still remain authoritative for natural
        # structures in the currently loaded save.
        # Dimensions alone identify a map layout, not a save slot.  Include a
        # per-save identity so records from another slot/world cannot appear
        # after reconnecting to a same-sized map.
        save_identity = self._active_save_identity()
        digest = hashlib.blake2s(digest_size=12)
        digest.update(self._map_identity(width, height, world_width, world_height, None).encode("ascii"))
        digest.update(str(save_identity).encode("utf-8", "replace"))
        key = "world-" + digest.hexdigest()
        self._map_cache_signature = self._map_cache_id(data, width, height, world_width, world_height)
        self._map_cache_key = key
        return key

    def _active_save_identity(self):
        """Resolve the loaded save path when the game exposes it in memory.

        CraftWorld does not keep a source filename in Room records.  The save
        provider does retain ``.../saves/slotN/game1.sav`` as a diagnostic
        string while a slot is loaded, which is a much stronger cache key than
        map dimensions.  If it cannot be recovered, fall back to the process
        id so stale annotations never cross a game session.
        """
        try:
            pid = int(pm.process_id) if pm else 0
        except Exception:
            pid = 0
        cached = getattr(self, "_structure_save_identity_cache", {}) or {}
        if int(cached.get("pid", 0)) == pid and cached.get("value"):
            return str(cached["value"])
        value = "process-%d" % pid
        try:
            if pm and pid:
                hits = pymem.pattern.pattern_scan_all(pm.process_handle, b"game1.sav", return_multiple=True) or []
                for hit in hits[:24]:
                    start = max(0, int(hit) - 768)
                    blob = pm.read_bytes(start, 1024) or b""
                    text = blob.decode("ascii", "ignore")
                    match = re.search(r"([A-Za-z]:)?[/\\][^\x00\r\n]*?[/\\]saves[/\\]slot\d+[/\\]game1\.sav", text, re.IGNORECASE)
                    if not match:
                        continue
                    path = os.path.normcase(os.path.abspath(match.group(0).replace("/", os.sep)))
                    file_hash = ""
                    if os.path.isfile(path):
                        try:
                            file_hash = self._save_hash(path)
                        except OSError:
                            file_hash = ""
                    value = "save-%s" % hashlib.sha256((path + "|" + file_hash).encode("utf-8", "replace")).hexdigest()[:32]
                    break
        except Exception:
            pass
        self._structure_save_identity_cache = {"pid": pid, "value": value}
        return value

    def _clean_structure_records(self, records):
        """Keep display metadata; source map files remain game-owned.

        ``mask`` is an optional post-placement readback captured by the
        modifier.  It is deliberately kept small (one bit-like character per
        local cell) so the map overlay can draw the real silhouette instead
        of guessing from whatever terrain happens to surround the anchor.
        """
        clean, seen = [], set()
        for record in records if isinstance(records, list) else []:
            try:
                filename = str(record.get("file") or "").strip()
                row, col = int(record.get("row")), int(record.get("col"))
                width, height = int(record.get("width")), int(record.get("height"))
                if (not filename or row < 0 or col < 0 or width < 1 or height < 1):
                    continue
                key = (filename.lower(), row, col)
                if key in seen:
                    continue
                seen.add(key)
                item = {
                    "file": filename, "row": row, "col": col,
                    "width": min(width, 400), "height": min(height, 400),
                    "category": str(record.get("category") or "已确认结构")[:40],
                    "source": str(record.get("source") or "modifier-session")[:40],
                    "confidence": str(record.get("confidence") or self.STATUS_VERIFIED)[:40],
                    "timestamp": int(record.get("timestamp") or 0),
                }
                # Keep the real World::UnderRoom vector slot.  It is not the
                # browser list index, and is required for native deletion.
                try:
                    native_slot = int(record.get("native_record_index", record.get("record_index", -1)))
                    if native_slot >= 0:
                        item["native_record_index"] = native_slot
                except (TypeError, ValueError, OverflowError):
                    pass
                item["live_native_room"] = "native_record_index" in item
                for key in ("native_anchor_col", "native_anchor_row", "bounds_source",
                            "mask_origin_col", "mask_origin_row", "mask_width",
                            "mask_height", "occupied_cells", "mask_source",
                            "mask_confidence", "occupied_bounds"):
                    if key in record:
                        item[key] = record[key]
                mask = record.get("mask")
                mask_width = int(record.get("mask_width", width) or width)
                mask_height = int(record.get("mask_height", height) or height)
                if isinstance(mask, list) and len(mask) == mask_height:
                    valid = []
                    for line in mask[:mask_height]:
                        text = str(line or "")[:mask_width]
                        valid.append("".join("1" if ch == "1" else "0" for ch in text.ljust(mask_width, "0")))
                    if any("1" in line for line in valid):
                        item["mask"] = valid
                        item["mask_source"] = str(record.get("mask_source") or "placement-readback")[:32]
                        item["mask_width"] = mask_width
                        item["mask_height"] = mask_height
                        item["mask_origin_col"] = int(record.get("mask_origin_col", col))
                        item["mask_origin_row"] = int(record.get("mask_origin_row", row))
                clean.append(item)
            except (AttributeError, TypeError, ValueError, OverflowError):
                continue
        return clean[:96]

    def _read_native_room_records(self):
        """Read the live World::UnderRoom vector without touching map tiles.

        The current Steam build keeps room footprints as 0x34-byte POD
        records at ``World+0x310``.  This is runtime evidence for both
        naturally generated and event-created rooms; unlike the old marker
        cache it is process-scoped and disappears with the loaded save.
        The first byte at +0x30 is the native hidden/removed flag, so hidden
        records are deliberately excluded from the visible list.
        """
        if not connected or pm is None:
            return []
        try:
            resolved = self._map_resolve()
            if not resolved:
                return []
            _map_data, map_width, map_height, _world_width, _world_height = resolved
            world = int(pm.read_int(base_addr + ITEM_BASE_OFFSET) or 0)
            if not world:
                return []
            begin = int(pm.read_int(world + 0x310) or 0)
            end = int(pm.read_int(world + 0x314) or 0)
            span = end - begin
            if (begin <= 0 or end <= begin or span > 0x34 * 2048
                    or span % 0x34 != 0):
                return []
            count = span // 0x34
            raw = pm.read_bytes(begin, span)
            if not raw or len(raw) < span:
                return []
            records = []
            for index in range(count):
                offset = index * 0x34
                # UnderRoom layout observed in the current build:
                # +04/+08 = anchor column/row, +0C/+10 = footprint,
                # +30 (one byte) = native hidden/removed flag.  The remaining
                # bytes in the record are retained native metadata and
                # are retained by the game and intentionally not guessed.
                col_f, row_f, width_f, height_f = struct.unpack_from(
                    "<4f", raw, offset + 0x04)
                # RemoveHiddenRoom writes only the byte at +0x30.  The
                # remaining bytes belong to adjacent native metadata and may
                # legitimately be non-zero; reading a DWORD here hid valid
                # room records from the scanner.
                hidden = raw[offset + 0x30]
                if hidden:
                    continue
                if not all(math.isfinite(value) for value in
                           (col_f, row_f, width_f, height_f)):
                    continue
                # These fields are the native room centre, not the upper-left
                # tile.  Keep both representations: the centre is required
                # by RemoveHiddenRoom, while the derived top-left bounds are
                # what the map overlay and selection UI need.
                center_col, center_row = int(round(col_f)), int(round(row_f))
                width, height = int(round(width_f)), int(round(height_f))
                if not (0 <= center_col < int(map_width) and 0 <= center_row < int(map_height)
                        and 1 <= width <= 400 and 1 <= height <= 400):
                    continue
                col = center_col - (width // 2)
                row = center_row - (height // 2)
                if col < 0 or row < 0 or col + width > int(map_width) or row + height > int(map_height):
                    continue
                records.append({
                    "file": "native_room_%03d" % index,
                    "row": row,
                    "col": col,
                    "width": width,
                    "height": height,
                    "category": "原生房间",
                    "source": "native-room-container",
                    "confidence": self.STATUS_VERIFIED,
                    "record_index": index,
                    "native_anchor_col": center_col,
                    "native_anchor_row": center_row,
                    "bounds_source": "native-room-centre-size",
                })
            # Enrich each native record with a conservative, irregular mask.
            # This is display/deletion evidence only; failure to derive one is
            # safe and leaves the native record visible without enabling a
            # destructive rectangular fallback.
            for item in records:
                occupancy = self._native_structure_occupancy(item, map_width, map_height)
                if occupancy:
                    item.update(occupancy)
                    item["occupied_bounds"] = {
                        "col": int(occupancy["mask_origin_col"]),
                        "row": int(occupancy["mask_origin_row"]),
                        "width": int(occupancy["mask_width"]),
                        "height": int(occupancy["mask_height"]),
                    }
            return records
        except (AttributeError, OSError, struct.error, TypeError, ValueError,
                OverflowError):
            return []

    def _saved_map_structures(self, map_key):
        """Load modifier-created structure records for the current map.

        The source filename is not retained by the game after ``putRoom``
        merges the tiles, so these records are the only way to keep a
        generated structure named after the modifier is restarted.  Records
        are keyed by the stable map dimensions/world size key and are removed
        again by the native delete workflow.
        """
        try:
            if not isinstance(map_key, str) or not map_key.startswith("world-"):
                return []
            cfg = self._read_config()
            groups = cfg.get("map_structures", {}) if isinstance(cfg, dict) else {}
            records = groups.get(map_key, []) if isinstance(groups, dict) else []
            # Drop annotations written by the retired test-map recovery path.
            # Only records produced by a successful native placement are
            # eligible for persistence; natural structures come from the
            # live UnderRoom container instead.
            records = [item for item in records if isinstance(item, dict)
                        and str(item.get("source") or "").startswith("native-runtime")]
            return self._clean_structure_records(records)
        except Exception:
            return []

    def _save_map_structures(self, map_key, records):
        """Persist only sanitized structure metadata in hidden user config."""
        try:
            if not isinstance(map_key, str) or not map_key.startswith("world-"):
                return False
            clean = self._clean_structure_records(records)
            # UnderRoom slots are process-local vector positions.  Persisting
            # one across a restart could make a later delete target a wholly
            # different room, so the live scanner always reattaches it.
            for item in clean:
                item.pop("native_record_index", None)
            def update(cfg):
                groups = dict(cfg.get("map_structures", {}) or {})
                groups[map_key] = clean[:128]
                cfg["map_structures"] = groups
            return bool(self._update_config(update))
        except Exception as exc:
            _diagnostic("save_map_structures error:", exc)
            return False

    def _map_dwarf_markers(self, width, height, world_width, world_height, live=False):
        """Return dwarf markers, optionally rereading only their coordinates."""
        dwarves = []
        is_v2 = self._detect_v2() if live else None
        for dwarf in _dwarf_cache_snapshot():
            try:
                if live:
                    edi = int(dwarf.get("edi") or 0) & 0xFFFFFFFF
                    if not self._valid_runtime_pointer(edi):
                        continue
                    x_off = V2_DWARF_X if is_v2 else 0x428
                    y_off = V2_DWARF_Y if is_v2 else 0x42C
                    x, y = float(pm.read_float(edi + x_off)), float(pm.read_float(edi + y_off))
                else:
                    x, y = float(dwarf["x"]), float(dwarf["y"])
                col, row = x * width / world_width, y * height / world_height
                if 0 <= col < width and 0 <= row < height:
                    marker = dict(dwarf)
                    marker.update({"col": col, "row": row})
                    dwarves.append(marker)
            except Exception:
                # A dwarf may be destroyed between two coordinate reads. This
                # marker path is display-only, so skip that one entry and keep
                # the remaining markers responsive.
                continue
        return dwarves

    def _map_resolve(self):
        global pm, connected, base_addr
        if not connected or pm is None or not base_addr:
            return None
        # base_addr stores the CraftWorld.exe module base; the world/map root
        # is held at the V1 static offset below.
        obj = pm.read_int(base_addr + ITEM_BASE_OFFSET)
        data = pm.read_int(obj + 0x43C)
        w = pm.read_int(obj + 0x450)
        h = pm.read_int(obj + 0x454)
        world_w = pm.read_float(obj + 0x1C0)
        world_h = pm.read_float(obj + 0x1C4)
        if not data or not (1 <= w <= 1000 and 1 <= h <= 1000):
            return None
        if not world_w or not world_h:
            world_w, world_h = float(w * 60), float(h * 60)
        return data, w, h, float(world_w), float(world_h)

    def _runtime_read_unavailable_state(self):
        """Classify a missing runtime structure without substituting fake data."""
        if not connected or pm is None:
            return self.STATUS_DISCONNECTED, "尚未连接游戏"
        try:
            if not self._map_resolve():
                return self.STATUS_EMPTY, "游戏已连接，但当前没有载入可读取的存档地图"
        except Exception:
            pass
        return self.STATUS_STALE, "当前版本的定位地址或对象结构已失效，请重新连接或检查版本"

    @staticmethod
    def _read_envelope(ok, state, data=None, error="", **extra):
        """Stable shape for UI reads with an unambiguous failure payload.

        A failed read must never look like a valid empty inventory or empty
        dwarf roster.  Consumers receive ``data=None`` for every failure and
        may only treat an empty list as a confirmed, successful empty result.
        """
        result = {
            "ok": bool(ok),
            "state": str(state),
            "data": data if ok else None,
        }
        if ok and result["data"] is None:
            result["data"] = []
        if error:
            result["error"] = str(error)
        result.update(extra)
        return result

    def _map_bases(self, data):
        # data is the live map payload pointer returned by the map manager.
        # Old code searched the whole process for similarly shaped allocations
        # and wrote every match, including stale buffers.  That could corrupt
        # retired maps and cause a delayed crash in the world/AI update.
        return [data - self.MAP_DATA_OFF]

    def map_blocks(self):
        m = {}
        by_en = {}
        tpath = _resource_path("item_translations.txt")
        if os.path.exists(tpath):
            try:
                for line in open(tpath, encoding="utf-8", errors="replace"):
                    line = line.strip()
                    if not line or line.startswith("#") or "=" not in line:
                        continue
                    k, v = line.split("=", 1)
                    k = k.strip()
                    v = v.strip()
                    if not k or not v:
                        continue
                    if k.isdigit() and "|" in v:
                        en, zh = v.split("|", 1)
                        m[int(k)] = {"en": en.strip(), "zh": zh.strip(), "src": "runtime", "bg": ""}
                    else:
                        by_en[k.lower()] = v
            except Exception:
                pass
        if not m:
            rpath = _resource_path("runtime_blocks.csv")
            if os.path.exists(rpath):
                try:
                    import csv as _csv
                    with open(rpath, encoding="utf-8-sig") as f:
                        rd = _csv.reader(f)
                        next(rd, None)
                        for line in rd:
                            if len(line) >= 2:
                                try:
                                    wid = int(line[0])
                                except Exception:
                                    continue
                                m[wid] = {"en": line[1], "zh": "", "src": "runtime", "bg": ""}
                except Exception:
                    pass
        for wid, it in m.items():
            if not it.get("zh"):
                it["zh"] = by_en.get(str(it.get("en", "")).lower(), "")
        return m

    def get_map_favorite_blocks(self):
        """Return the user's small, portable list of frequently used blocks."""
        try:
            values = self._read_config().get("map_favorite_blocks", [])
            ids = []
            for value in values if isinstance(values, list) else []:
                number = int(value)
                if 0 <= number <= 0xFFFF and number not in ids:
                    ids.append(number)
            return {"ok": True, "ids": ids}
        except Exception as exc:
            return {"ok": False, "ids": [], "error": str(exc)}

    def save_map_favorite_blocks(self, values):
        """Persist at most 24 validated block IDs in user configuration."""
        try:
            ids = []
            for value in values if isinstance(values, list) else []:
                number = int(value)
                if 0 <= number <= 0xFFFF and number not in ids:
                    ids.append(number)
            ids = ids[:24]
            if not self._update_config(lambda cfg: cfg.update({"map_favorite_blocks": ids})):
                return {"ok": False, "error": "无法保存常用方块"}
            return {"ok": True, "ids": ids}
        except Exception as exc:
            return {"ok": False, "error": str(exc)}

    def map_metadata(self):
        """Read map dimensions and live markers without transferring tile payload."""
        try:
            resolved = self._map_resolve()
            if not resolved:
                state, error = self._runtime_read_unavailable_state()
                return {"ok": False, "state": state, "error": error}
            data, width, height, world_width, world_height = resolved
            signature = self._map_cache_id(data, width, height, world_width, world_height)
            # A metadata-only identity is intentionally temporary. map_read_regions
            # will adopt the same signature before any tile request is accepted.
            self._map_cache_signature = signature
            map_key = self._map_cache_key or ("live-%d-%dx%d" % (int(pm.process_id), int(width), int(height)))
            self._map_cache_key = map_key
            return {"ok": True, "state": self.STATUS_VERIFIED, "width": int(width), "height": int(height),
                    "world_width": float(world_width), "world_height": float(world_height),
                    "map_key": map_key, "dwarves": self._map_dwarf_markers(width, height, world_width, world_height),
                    "write_enabled": bool(self.MAP_DIRECT_WRITES_ENABLED), "edit_limit": int(self.MAP_SAFE_EDIT_LIMIT), "tile_mode": "viewport_only"}
        except Exception as exc:
            return {"ok": False, "state": self.STATUS_STALE, "error": "地图元数据读取异常：%s" % exc}

    def get_portal_director_surface_profile(self):
        """Read only the top terrain cell of every map column for portal placement.

        This intentionally transfers a compact per-column profile rather than
        the entire map.  Scenario placement can therefore choose ground/sky
        coordinates without ever placing a portal inside underground terrain.
        """
        try:
            resolved = self._map_resolve()
            if not resolved:
                state, error = self._runtime_read_unavailable_state()
                return {"ok": False, "state": state, "error": error}
            data, width, height, world_width, world_height = resolved
            row_len = self._map_row_stride(width)
            payload = pm.read_bytes(data, row_len * height)
            if payload is None or len(payload) != row_len * height:
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "地图地表轮廓读取不完整"}
            surface_rows, surface_water = [], []
            for col in range(int(width)):
                surface = -1
                water = 0
                for row in range(int(height)):
                    off = row * row_len + col * self.MAP_COL_W
                    ground = struct.unpack_from("<H", payload, off + 2)[0]
                    if ground != 0xFFFF:
                        surface = row - 1
                        if surface >= 0:
                            above = surface * row_len + col * self.MAP_COL_W
                            water = int(payload[above + 12]) & 31
                        break
                surface_rows.append(surface)
                surface_water.append(water)
            return {"ok": True, "state": self.STATUS_VERIFIED,
                    "width": int(width), "height": int(height),
                    "surface_rows": surface_rows, "surface_water": surface_water,
                    "dwarves": self._map_dwarf_markers(width, height, world_width, world_height)}
        except Exception as exc:
            return {"ok": False, "state": self.STATUS_STALE,
                    "error": "地图地表轮廓读取失败：%s" % exc}

    def get_portal_director_grid_map(self, max_width=240, max_height=140):
        """Return a compact occupancy grid for click-to-place portal previews.

        Each returned character represents whether its source map area contains
        any foreground terrain block.  It deliberately ignores inner/outer
        material identity: the director only needs to distinguish air from
        terrain so it can refuse underground placements.
        """
        try:
            resolved = self._map_resolve()
            if not resolved:
                state, error = self._runtime_read_unavailable_state()
                return {"ok": False, "state": state, "error": error}
            data, width, height, world_width, world_height = resolved
            width, height = int(width), int(height)
            row_len = self._map_row_stride(width)
            payload = pm.read_bytes(data, row_len * height)
            if payload is None or len(payload) != row_len * height:
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "方格地图读取不完整"}
            try:
                grid_width = max(1, min(width, int(max_width)))
                grid_height = max(1, min(height, int(max_height)))
            except (TypeError, ValueError, OverflowError):
                grid_width, grid_height = min(width, 240), min(height, 140)
            rows = []
            occupied_count = 0
            for gy in range(grid_height):
                r0 = gy * height // grid_height
                r1 = max(r0 + 1, (gy + 1) * height // grid_height)
                chars = []
                for gx in range(grid_width):
                    c0 = gx * width // grid_width
                    c1 = max(c0 + 1, (gx + 1) * width // grid_width)
                    occupied = False
                    for row in range(r0, r1):
                        base = row * row_len
                        for col in range(c0, c1):
                            if struct.unpack_from("<H", payload, base + col * self.MAP_COL_W + 2)[0] != 0xFFFF:
                                occupied = True
                                break
                        if occupied:
                            break
                    chars.append("1" if occupied else "0")
                    if occupied:
                        occupied_count += 1
                rows.append("".join(chars))
            return {"ok": True, "state": self.STATUS_VERIFIED,
                    "width": width, "height": height,
                    "grid_width": grid_width, "grid_height": grid_height,
                    "rows": rows, "occupied_count": occupied_count,
                    "dwarves": self._map_dwarf_markers(width, height, world_width, world_height)}
        except Exception as exc:
            return {"ok": False, "state": self.STATUS_STALE,
                    "error": "方格地图读取失败：%s" % exc}

    def map_scan(self):
        global pm, connected
        try:
            r = self._map_resolve()
            if not r:
                state, error = self._runtime_read_unavailable_state()
                return {"ok": False, "state": state, "error": error}
            data, w, h, world_w, world_h = r
            row_len = self._map_row_stride(w)
            payload = pm.read_bytes(data, row_len * h)
            if payload is None or len(payload) != row_len * h:
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "地图数据读取不完整；地图缓冲区可能已重建，请重新进入存档后再试"}
            bg, w2, water, front, explored = [], [], [], [], []
            bgcnt = {}
            for row in range(h):
                row_start = row * row_len
                for col in range(w):
                    off = row_start + col * self.MAP_COL_W
                    d0 = struct.unpack_from("<I", payload, off)[0]
                    w2v = struct.unpack_from("<H", payload, off + 2)[0]
                    bgb = struct.unpack_from("<i", payload, off + 8)[0]
                    wv = payload[off + 12]
                    ev = 0 if (bgb & 2) else 1
                    low = d0 & 0xFFFF
                    fv = low if low != 0xFFFF else 0xFFFF
                    bg.append(bgb); w2.append(w2v); water.append(wv); front.append(fv); explored.append(ev)
                    bgcnt.setdefault(w2v, {})
                    bgcnt[w2v][bgb] = bgcnt[w2v].get(bgb, 0) + 1
            bg_hint = {k: max(v.items(), key=lambda x: x[1])[0] for k, v in bgcnt.items()}
            map_key = self._map_identity(w, h, world_w, world_h, payload)
            self._map_cache_signature = self._map_cache_id(data, w, h, world_w, world_h)
            self._map_cache_key = map_key
            dwarves = self._map_dwarf_markers(w, h, world_w, world_h)
            return {"ok": True, "state": self.STATUS_VERIFIED, "width": w, "height": h, "world_width": world_w, "world_height": world_h, "map_key": map_key, "bg": bg, "w2": w2, "water": water, "front": front, "explored": explored, "bg_hint": bg_hint, "dwarves": dwarves,
                    "write_enabled": bool(self.MAP_DIRECT_WRITES_ENABLED), "edit_limit": int(self.MAP_SAFE_EDIT_LIMIT)}
        except Exception as e:
            return {"ok": False, "state": self.STATUS_STALE, "error": "地图读取异常：%s" % e}

    def map_status(self):
        """Cheap map heartbeat used after the initial full map read.

        It resolves the current map and refreshes dwarf markers, but never
        reads or transfers the 32-byte-per-cell payload.  A changed map buffer
        (such as loading another save) tells the browser to perform one full
        map_scan and rebuild its cache.
        """
        try:
            r = self._map_resolve()
            if not r:
                state, error = self._runtime_read_unavailable_state()
                return {"ok": False, "state": state, "error": error}
            data, w, h, world_w, world_h = r
            signature = self._map_cache_id(data, w, h, world_w, world_h)
            changed = signature != self._map_cache_signature
            result = {"ok": True, "state": self.STATUS_VERIFIED, "changed": changed,
                      "write_enabled": bool(self.MAP_DIRECT_WRITES_ENABLED),
                      "edit_limit": int(self.MAP_SAFE_EDIT_LIMIT)}
            if changed:
                result["reason"] = "map_buffer_changed"
                return result
            result.update({"width": w, "height": h,
                           "world_width": world_w, "world_height": world_h,
                           "map_key": self._map_cache_key,
                           "dwarves": self._map_dwarf_markers(w, h, world_w, world_h)})
            return result
        except Exception as e:
            return {"ok": False, "state": self.STATUS_STALE, "error": "地图状态读取异常：%s" % e}

    def map_dwarf_markers(self):
        """Fast marker heartbeat: read only cached dwarves' X/Y coordinates.

        This intentionally skips the full dwarf roster refresh (health, hunger,
        skills and equipment) and avoids transferring map cells.  It is used
        solely by the map overlay at a short interval.
        """
        try:
            r = self._map_resolve()
            if not r:
                state, error = self._runtime_read_unavailable_state()
                return {"ok": False, "state": state, "error": error}
            data, w, h, world_w, world_h = r
            signature = self._map_cache_id(data, w, h, world_w, world_h)
            if signature != self._map_cache_signature:
                return {"ok": True, "state": self.STATUS_VERIFIED, "changed": True,
                        "reason": "map_buffer_changed"}
            return {"ok": True, "state": self.STATUS_VERIFIED, "changed": False,
                    "dwarves": self._map_dwarf_markers(w, h, world_w, world_h, live=True)}
        except Exception as e:
            return {"ok": False, "state": self.STATUS_STALE,
                    "error": "矮人地图坐标读取异常：%s" % e}

    def map_read_regions(self, regions):
        """Read selected live map rectangles without serialising the full map.

        Regions use inclusive r0/c0/r1/c1 coordinates.  This endpoint is
        intentionally read-only: the browser requests the visible area and,
        when necessary, small areas around live dwarf markers.
        """
        try:
            r = self._map_resolve()
            if not r:
                state, error = self._runtime_read_unavailable_state()
                return {"ok": False, "state": state, "error": error}
            data, w, h, world_w, world_h = r
            signature = self._map_cache_id(data, w, h, world_w, world_h)
            if signature != self._map_cache_signature:
                return {"ok": True, "changed": True, "reason": "map_buffer_changed"}
            if not isinstance(regions, list):
                return {"ok": False, "state": self.STATUS_FAILED, "error": "区域参数无效"}
            if len(regions) > self.MAP_REGION_MAX_COUNT:
                return {"ok": False, "state": self.STATUS_FAILED, "error": "区域数量过多"}

            clean = []
            total_cells = 0
            for region in regions:
                if not isinstance(region, dict):
                    return {"ok": False, "state": self.STATUS_FAILED, "error": "区域格式无效"}
                try:
                    r0, c0 = int(region["r0"]), int(region["c0"])
                    r1, c1 = int(region["r1"]), int(region["c1"])
                except (KeyError, TypeError, ValueError):
                    return {"ok": False, "state": self.STATUS_FAILED, "error": "区域坐标无效"}
                r0, c0 = max(0, r0), max(0, c0)
                r1, c1 = min(h - 1, r1), min(w - 1, c1)
                if r0 > r1 or c0 > c1:
                    continue
                cells = (r1 - r0 + 1) * (c1 - c0 + 1)
                total_cells += cells
                if total_cells > self.MAP_REGION_MAX_CELLS:
                    return {"ok": False, "state": self.STATUS_FAILED, "error": "本次地图区域过大"}
                clean.append((r0, c0, r1, c1))

            stride = self._map_row_stride(w)
            result_regions = []
            for r0, c0, r1, c1 in clean:
                rows, cols = r1 - r0 + 1, c1 - c0 + 1
                bg, w2, water, front, explored = [], [], [], [], []
                for row in range(r0, r1 + 1):
                    row_addr = data + row * stride + c0 * self.MAP_COL_W
                    payload = pm.read_bytes(row_addr, cols * self.MAP_COL_W)
                    if payload is None or len(payload) != cols * self.MAP_COL_W:
                        return {"ok": False, "state": self.STATUS_STALE,
                                "error": "地图区域读取不完整；地图缓冲区可能已重建"}
                    for col in range(cols):
                        off = col * self.MAP_COL_W
                        d0 = struct.unpack_from("<I", payload, off)[0]
                        low = d0 & 0xFFFF
                        front.append(low if low != 0xFFFF else 0xFFFF)
                        w2.append(struct.unpack_from("<H", payload, off + 2)[0])
                        flags = struct.unpack_from("<i", payload, off + 8)[0]
                        bg.append(flags)
                        # Bit 1 is the fog/exploration flag.  Keep it in the
                        # live region response as well as the full scan, or
                        # the exploration view becomes stale until a manual
                        # whole-map refresh.
                        explored.append(0 if (flags & 0x02) else 1)
                        water.append(payload[off + 12])
                result_regions.append({"r0": r0, "c0": c0, "rows": rows, "cols": cols,
                                       "bg": bg, "w2": w2, "water": water, "front": front,
                                       "explored": explored})
            return {"ok": True, "state": self.STATUS_VERIFIED, "changed": False,
                    "dwarves": self._map_dwarf_markers(w, h, world_w, world_h),
                    "regions": result_regions,
                    "write_enabled": bool(self.MAP_DIRECT_WRITES_ENABLED), "edit_limit": int(self.MAP_SAFE_EDIT_LIMIT)}
        except Exception as e:
            return {"ok": False, "state": self.STATUS_STALE,
                    "error": "地图局部读取异常：%s" % e}


    def map_find_resource(self, resource_id, limit=30):
        """Find a selected resource on demand without mutating the map.

        This intentionally performs a complete, explicit scan only after the
        user presses the resource-location button. Normal rendering and
        timer-driven refreshes never call it.
        """
        try:
            target = int(resource_id)
            result_limit = max(1, min(int(limit), 100))
        except (TypeError, ValueError):
            return {"ok": False, "error": "资源 ID 无效"}
        if target < 0 or target > 0xFFFF:
            return {"ok": False, "error": "资源 ID 超出地图字段范围"}
        try:
            resolved = self._map_resolve()
            if not resolved:
                return {"ok": False, "error": "未连接或当前地图未载入"}
            data, width, height, world_width, world_height = resolved
            signature = self._map_cache_id(data, width, height, world_width, world_height)
            if signature != self._map_cache_signature:
                return {"ok": True, "changed": True, "reason": "map_buffer_changed"}
            stride, matches = self._map_row_stride(width), []
            for row in range(height):
                payload = pm.read_bytes(data + row * stride, stride)
                if payload is None or len(payload) != stride:
                    return {"ok": False, "error": "资源定位时地图行读取不完整"}
                for col in range(width):
                    off = col * self.MAP_COL_W
                    inner = struct.unpack_from("<H", payload, off + 2)[0]
                    outer_raw = struct.unpack_from("<I", payload, off)[0] & 0xFFFF
                    outer = outer_raw if outer_raw != 0xFFFF else 0xFFFF
                    if inner == target:
                        matches.append({"row": row, "col": col, "layer": "inner"})
                    if outer == target:
                        matches.append({"row": row, "col": col, "layer": "outer"})
                    if len(matches) >= result_limit:
                        return {"ok": True, "changed": False, "resource_id": target,
                                "matches": matches, "truncated": True,
                                "write_enabled": False}
            return {"ok": True, "changed": False, "resource_id": target,
                    "matches": matches, "truncated": False, "write_enabled": False}
        except Exception as exc:
            return {"ok": False, "error": str(exc)}

    def open_project_url(self):
        """Open the public project page in the user's default browser."""
        url = "https://github.com/dszwamn/CraftWorldModifier"
        try:
            opened = bool(webbrowser.open(url, new=2))
            return {"ok": opened, "url": url, "error": "系统未能打开默认浏览器" if not opened else ""}
        except Exception as exc:
            return {"ok": False, "url": url, "error": str(exc)}

    def get_map_pins(self, map_key):
        """Return pins belonging to one generated world/save."""
        try:
            cfg = self._read_config()
            pins = (cfg.get("map_pins", {}) or {}).get(str(map_key), [])
            return [pin for pin in pins if isinstance(pin, dict)]
        except Exception:
            return []

    def _clean_map_pins(self, pins):
        """Return only the portable part of a map-pin collection."""
        clean = []
        for pin in pins if isinstance(pins, list) else []:
            try:
                row, col = int(pin.get("row")), int(pin.get("col"))
                if row < 0 or col < 0:
                    continue
                name = str(pin.get("name", "标记点")).strip()[:36] or "标记点"
                clean.append({"name": name, "row": row, "col": col})
            except (AttributeError, TypeError, ValueError):
                continue
        return clean

    def save_map_pins(self, map_key, pins):
        """Persist a sanitised pin list without disturbing other settings."""
        try:
            if not isinstance(map_key, str) or not map_key.startswith("world-"):
                return False
            clean = self._clean_map_pins(pins)
            def update(cfg):
                all_pins = dict(cfg.get("map_pins", {}) or {})
                all_pins[map_key] = clean
                cfg["map_pins"] = all_pins
            return self._update_config(update)
        except Exception as e:
            _diagnostic("save_map_pins error:", e)
            return False

    def map_replace(self, row, col, bg, word, water=0):
        global pm
        try:
            if not self.MAP_DIRECT_WRITES_ENABLED:
                return {"ok": False, "error": "安全模式：地图方块写入已暂停，避免破坏寻路/碰撞等游戏内部状态"}
            r = self._map_resolve()
            if not r:
                return {"ok": False, "error": "\u672a\u8fde\u63a5"}
            data, w, h, *_ = r
            if not (0 <= row < h and 0 <= col < w):
                return {"ok": False, "error": "\u5750\u6807\u8d8a\u754c"}
            bases = self._map_bases(data)
            off = row * self._map_row_stride(w) + col * self.MAP_COL_W
            hnd = self._suspend(pm.process_id)
            try:
                for base in bases:
                    cell = base + self.MAP_DATA_OFF + off
                    d0 = ((word & 0xFFFF) << 16) | 0xFFFF
                    pm.write_int(cell, d0)
                    pm.write_int(cell + 8, bg)
                    pm.write_bytes(cell + 12, bytes([0x80 | (water & 0x1F)]), 1)
            finally:
                self._resume(hnd)
            a = bases[0] + self.MAP_DATA_OFF + off
            return {"ok": True, "row": row, "col": col, "bg": pm.read_int(a + 8), "word": pm.read_int(a + 2) & 0xFFFF}
        except Exception as e:
            return {"ok": False, "error": str(e)}

    def map_replace_front(self, row, col, front_id):
        """????????d0 ? 16 ? = front_id?0 ????"""
        global pm
        try:
            if not self.MAP_DIRECT_WRITES_ENABLED:
                return {"ok": False, "error": "安全模式：地图方块写入已暂停，避免破坏寻路/碰撞等游戏内部状态"}
            r = self._map_resolve()
            if not r:
                return {"ok": False, "error": "\u672a\u8fde\u63a5"}
            data, w, h, *_ = r
            if not (0 <= row < h and 0 <= col < w):
                return {"ok": False, "error": "\u5750\u6807\u8d8a\u754c"}
            bases = self._map_bases(data)
            off = row * self._map_row_stride(w) + col * self.MAP_COL_W
            hnd = self._suspend(pm.process_id)
            try:
                for base in bases:
                    cell = base + self.MAP_DATA_OFF + off
                    d0 = pm.read_int(cell) & 0xFFFFFFFF
                    new_d0 = (d0 & 0xFFFF0000) | (front_id & 0xFFFF)
                    pm.write_int(cell, new_d0)
            finally:
                self._resume(hnd)
            return {"ok": True}
        except Exception as e:
            return {"ok": False, "error": str(e)}

    def map_apply_cells(self, cells):
        """Atomically update known map fields while preserving the other 32-byte cell data."""
        global pm
        try:
            if not self.MAP_DIRECT_WRITES_ENABLED:
                return {"ok": False, "error": "安全模式：区域填充已暂停，避免破坏寻路/碰撞等游戏内部状态"}
            if not isinstance(cells, list) or not cells:
                return {"ok": False, "error": "没有可写入的格子"}
            if len(cells) > self.MAP_SAFE_EDIT_LIMIT:
                return {"ok": False, "error": "安全模式下单次最多修改 128 格；请分批操作"}
            r = self._map_resolve()
            if not r:
                return {"ok": False, "error": "未连接"}
            data, w, h, *_ = r
            rows = {}
            for item in cells:
                if not isinstance(item, dict):
                    return {"ok": False, "error": "格子数据格式错误"}
                row, col = int(item["row"]), int(item["col"])
                if not (0 <= row < h and 0 <= col < w):
                    return {"ok": False, "error": "坐标越界"}
                inner = int(item["inner"]) & 0xFFFF
                front = int(item["front"]) & 0xFFFF
                bg = int(item["bg"])
                water = max(0, min(31, int(item.get("water", 0))))
                preserve_water = bool(item.get("preserve_water", False))
                rows.setdefault(row, {})[col] = (inner, front, bg, water, preserve_water)

            bases = self._map_bases(data)
            hnd = self._suspend(pm.process_id)
            try:
                for base in bases:
                    for row, changes in rows.items():
                        row_addr = base + self.MAP_DATA_OFF + row * self._map_row_stride(w)
                        row_data = bytearray(pm.read_bytes(row_addr, w * self.MAP_COL_W))
                        for col, (inner, front, bg, water, preserve_water) in changes.items():
                            off = col * self.MAP_COL_W
                            struct.pack_into("<H", row_data, off, front)
                            struct.pack_into("<H", row_data, off + 2, inner)
                            struct.pack_into("<i", row_data, off + 8, bg)
                            if not preserve_water:
                                # The low five bits hold water level and bit 7
                                # marks a live water cell. Preserve the complete
                                # byte for terrain-only edits; re-encoding it
                                # can clear nearby water simulation flags.
                                row_data[off + 12] = (row_data[off + 12] & 0x60) | 0x80 | water
                        pm.write_bytes(row_addr, bytes(row_data), len(row_data))
            finally:
                self._resume(hnd)
            return {"ok": True, "cells": len(cells)}
        except Exception as e:
            return {"ok": False, "error": str(e)}

    def map_set_water(self, row, col, level):
        global pm
        try:
            if not self.MAP_DIRECT_WRITES_ENABLED:
                return {"ok": False, "error": "安全模式：地图水位写入已暂停，避免破坏寻路/碰撞等游戏内部状态"}
            r = self._map_resolve()
            if not r:
                return {"ok": False, "error": "\u672a\u8fde\u63a5"}
            data, w, h, *_ = r
            bases = self._map_bases(data)
            off = row * self._map_row_stride(w) + col * self.MAP_COL_W
            hnd = self._suspend(pm.process_id)
            try:
                for base in bases:
                    pm.write_bytes(base + self.MAP_DATA_OFF + off + 12, bytes([0x80 | (level & 0x1F)]), 1)
            finally:
                self._resume(hnd)
            return {"ok": True}
        except Exception as e:
            return {"ok": False, "error": str(e)}

    def map_set_explored(self, cells, explored=True):
        """Batch set or clear the per-tile explored flag."""
        global pm
        try:
            if not self.MAP_DIRECT_WRITES_ENABLED:
                return {"ok": False, "error": "安全模式：探索标志写入已暂停，避免破坏寻路/碰撞等游戏内部状态"}
            if not isinstance(cells, list) or not cells:
                return {"ok": False, "error": "没有可写入的格子"}
            if len(cells) > self.MAP_SAFE_EDIT_LIMIT:
                return {"ok": False, "error": "安全模式下单次最多修改 128 格；请分批操作"}
            r = self._map_resolve()
            if not r:
                return {"ok": False, "error": "未连接"}
            data, w, h, *_ = r
            rows = {}
            for item in cells:
                if isinstance(item, dict):
                    row, col = int(item["row"]), int(item["col"])
                else:
                    row, col = int(item[0]), int(item[1])
                if not (0 <= row < h and 0 <= col < w):
                    return {"ok": False, "error": "坐标越界"}
                rows.setdefault(row, set()).add(col)

            bases = self._map_bases(data)
            hnd = self._suspend(pm.process_id)
            try:
                for base in bases:
                    for row, cols in rows.items():
                        row_addr = base + self.MAP_DATA_OFF + row * self._map_row_stride(w)
                        row_data = bytearray(pm.read_bytes(row_addr, w * self.MAP_COL_W))
                        for col in cols:
                            off = col * self.MAP_COL_W + 8
                            flags = struct.unpack_from("<I", row_data, off)[0]
                            if explored:
                                flags &= ~0x02
                            else:
                                flags |= 0x02
                            struct.pack_into("<I", row_data, off, flags)
                        pm.write_bytes(row_addr, bytes(row_data), len(row_data))
            finally:
                self._resume(hnd)
            return {"ok": True, "cells": len(cells), "explored": bool(explored)}
        except Exception as e:
            return {"ok": False, "error": str(e)}

    def map_explore_all(self):
        """Mark every tile in the current live map as explored.

        This is intentionally separate from ``map_set_explored``: normal map
        edits remain capped at a small selection, while this operation changes
        only the verified ``0x02`` unexplored flag.  Rows are snapshotted before
        modification and restored if a write/readback check fails.
        """
        global pm
        if not self.MAP_DIRECT_WRITES_ENABLED:
            return {"ok": False, "error": "请先开启地图编辑，再执行全图探索"}
        try:
            resolved = self._map_resolve()
            if not resolved:
                state, error = self._runtime_read_unavailable_state()
                return {"ok": False, "state": state, "error": error}
            data, width, height, *_ = resolved
            width, height = int(width), int(height)
            total = width * height
            if total <= 0 or total > int(self.MAP_EXPLORE_ALL_MAX_CELLS):
                return {"ok": False, "error": "当前地图面积异常（%d 格），未执行写入" % total}

            bases = self._map_bases(data)
            if len(bases) != 1:
                return {"ok": False, "error": "未确认唯一的活动地图数据缓冲区，未执行写入"}
            base = int(bases[0])
            row_size = width * self.MAP_COL_W
            snapshots = []
            changed = 0
            hnd = self._suspend(pm.process_id)
            try:
                for row in range(height):
                    row_addr = base + self.MAP_DATA_OFF + row * self._map_row_stride(width)
                    original = bytes(pm.read_bytes(row_addr, row_size))
                    row_data = bytearray(original)
                    row_changed = 0
                    for col in range(width):
                        off = col * self.MAP_COL_W + 8
                        flags = struct.unpack_from("<I", row_data, off)[0]
                        if flags & 0x02:
                            struct.pack_into("<I", row_data, off, flags & ~0x02)
                            row_changed += 1
                    if row_changed:
                        snapshots.append((row_addr, original))
                        pm.write_bytes(row_addr, bytes(row_data), row_size)
                        changed += row_changed

                # Full readback, not a UI-only success indicator.  It also
                # catches a changed map pointer or an ignored write immediately.
                remaining = 0
                for row in range(height):
                    row_addr = base + self.MAP_DATA_OFF + row * self._map_row_stride(width)
                    row_data = pm.read_bytes(row_addr, row_size)
                    for col in range(width):
                        flags = struct.unpack_from("<I", row_data, col * self.MAP_COL_W + 8)[0]
                        if flags & 0x02:
                            remaining += 1
                if remaining:
                    raise RuntimeError("写后读回发现 %d 格仍为未探索" % remaining)
            except Exception:
                for row_addr, original in reversed(snapshots):
                    try:
                        pm.write_bytes(row_addr, original, len(original))
                    except Exception:
                        pass
                raise
            finally:
                self._resume(hnd)

            return {"ok": True, "width": width, "height": height, "cells": total,
                    "changed": changed, "message": "已将全图 %d 格标记为已探索（实际更新 %d 格）" % (total, changed)}
        except Exception as e:
            return {"ok": False, "error": "全图探索失败，已尝试回滚：%s" % e}

    def map_fill(self, bg, word, water=0):
        global pm
        try:
            if not self.MAP_DIRECT_WRITES_ENABLED:
                return {"ok": False, "error": "安全模式已禁用全图填充；请先开启地图编辑"}
            r = self._map_resolve()
            if not r:
                return {"ok": False, "error": "\u672a\u8fde\u63a5"}
            data, w, h, *_ = r
            bases = self._map_bases(data)
            hnd = self._suspend(pm.process_id)
            try:
                for base in bases:
                    for row in range(h):
                        row_addr = base + self.MAP_DATA_OFF + row * self._map_row_stride(w)
                        row_data = bytearray(pm.read_bytes(row_addr, w * self.MAP_COL_W))
                        for col in range(w):
                            off = col * self.MAP_COL_W
                            struct.pack_into("<H", row_data, off, 0xFFFF)
                            struct.pack_into("<H", row_data, off + 2, word & 0xFFFF)
                            struct.pack_into("<i", row_data, off + 8, int(bg))
                            row_data[off + 12] = (row_data[off + 12] & 0xE0) | (water & 0x1F)
                        pm.write_bytes(row_addr, bytes(row_data), len(row_data))
            finally:
                self._resume(hnd)
            return {"ok": True, "cells": w * h}
        except Exception as e:
            return {"ok": False, "error": str(e)}

    def map_clear(self):
        global pm
        try:
            if not self.MAP_DIRECT_WRITES_ENABLED:
                return {"ok": False, "error": "安全模式已禁用全图清空；请先开启地图编辑"}
            r = self._map_resolve()
            if not r:
                return {"ok": False, "error": "\u672a\u8fde\u63a5"}
            data, w, h, *_ = r
            bases = self._map_bases(data)
            hnd = self._suspend(pm.process_id)
            try:
                for base in bases:
                    for row in range(h):
                        row_addr = base + self.MAP_DATA_OFF + row * self._map_row_stride(w)
                        row_data = bytearray(pm.read_bytes(row_addr, w * self.MAP_COL_W))
                        for col in range(w):
                            off = col * self.MAP_COL_W
                            struct.pack_into("<H", row_data, off, 0xFFFF)
                            struct.pack_into("<H", row_data, off + 2, 0xFFFF)
                            struct.pack_into("<i", row_data, off + 8, 0)
                            row_data[off + 12] = row_data[off + 12] & 0xE0
                        pm.write_bytes(row_addr, bytes(row_data), len(row_data))
            finally:
                self._resume(hnd)
            return {"ok": True, "cells": w * h}
        except Exception as e:
            return {"ok": False, "error": str(e)}

    def set_map_write_enabled(self, enabled):
        """Explicitly enable or disable the limited live map editor."""
        if not bool(enabled):
            self.MAP_DIRECT_WRITES_ENABLED = False
            return {"ok": True, "write_enabled": False,
                    "edit_limit": int(self.MAP_SAFE_EDIT_LIMIT),
                    "message": "地图编辑已关闭"}
        global pm, connected
        if not connected or pm is None:
            self.MAP_DIRECT_WRITES_ENABLED = False
            return {"ok": False, "write_enabled": False,
                    "edit_limit": int(self.MAP_SAFE_EDIT_LIMIT),
                    "error": "请先连接游戏"}
        try:
            if not self._map_resolve():
                self.MAP_DIRECT_WRITES_ENABLED = False
                return {"ok": False, "write_enabled": False,
                        "edit_limit": int(self.MAP_SAFE_EDIT_LIMIT),
                        "error": "未读取到有效地图；请先进入已加载的存档地图"}
            self.MAP_DIRECT_WRITES_ENABLED = True
            return {"ok": True, "write_enabled": True,
                    "edit_limit": int(self.MAP_SAFE_EDIT_LIMIT),
                    "message": "地图编辑已开启：单次最多 %d 格" % int(self.MAP_SAFE_EDIT_LIMIT)}
        except Exception as e:
            self.MAP_DIRECT_WRITES_ENABLED = False
            return {"ok": False, "write_enabled": False,
                    "edit_limit": int(self.MAP_SAFE_EDIT_LIMIT),
                    "error": "地图编辑初始化失败：%s" % e}

    def _structure_descriptor(self, filename):
        """Read only the stable header fields needed to draw a placed room.

        The game still owns parsing and placement. We use the saved map header
        only for the visible rectangle of a structure already accepted by
        ``luaWorld::putRoom``; no map records are reconstructed here.
        """
        filename = os.path.basename(str(filename or "").strip())
        path = os.path.join(GAME_ROOT, "Levels", filename)
        fallback = {
            "file": str(filename or ""), "category": "小型矿洞",
            "category_id": "other",
            "name": "未分类结构",
            "width": 0, "height": 0, "header_ok": False,
        }
        if filename == "t.map":
            fallback["category"] = "空测试结构"
            fallback["category_id"] = "test"
            fallback["name"] = "空测试结构"
        else:
            stem = os.path.splitext(str(filename or ""))[0].lower()
            if stem.startswith("grotto"):
                suffix = stem[len("grotto"):].lstrip("_ -")
                fallback.update({"category": "矿洞结构", "category_id": "grotto", "name": "矿洞结构" + ((" · " + _structure_chinese_suffix(suffix)) if suffix else "")})
            elif stem.startswith("ancient_room"):
                suffix = stem[len("ancient_room"):].lstrip("_ -")
                fallback.update({"category": "远古房间", "category_id": "ancient_room", "name": "远古房间" + ((" · " + _structure_chinese_suffix(suffix)) if suffix else "")})
            elif stem.startswith("aliens_room"):
                suffix = stem[len("aliens_room"):].lstrip("_ -")
                fallback.update({"category": "异星房间", "category_id": "aliens_room", "name": "异星房间" + ((" · " + _structure_chinese_suffix(suffix)) if suffix else "")})
            elif "room" in stem:
                fallback.update({"category": "房间结构", "category_id": "room", "name": "房间结构 · " + _structure_chinese_suffix(stem)})
            elif stem.startswith("mnt_"):
                fallback.update({"category": "矿脉与地形片段", "category_id": "terrain",
                                 "name": "矿脉/地形片段 · " + _structure_chinese_suffix(stem[4:])})
            elif stem.startswith("ww_"):
                fallback.update({"category": "世界遗迹结构", "category_id": "world",
                                 "name": "世界遗迹 · " + _structure_chinese_suffix(stem[3:])})
            elif stem.startswith("evil_"):
                fallback.update({"category": "邪恶势力场景", "category_id": "evil",
                                 "name": "邪恶势力场景 · " + _structure_chinese_suffix(stem[5:])})
            elif stem.startswith("frt_"):
                fallback.update({"category": "森林场景", "category_id": "forest_scene",
                                 "name": "森林场景 · " + _structure_chinese_suffix(stem[4:])})
            elif stem.startswith("l1_"):
                fallback.update({"category": "剧情场景", "category_id": "story",
                                 "name": "剧情场景 · " + _structure_chinese_suffix(stem[3:])})
            else:
                fallback.update({"category": "其它结构", "category_id": "other",
                                 "name": "其它结构 · " + _structure_chinese_suffix(stem)})
        # The bundled directory is the source for filenames and dimensions.
        # The game still loads the actual map through its native putRoom path.
        embedded = EMBEDDED_STRUCTURE_INDEX.get(filename.lower())
        if embedded:
            try:
                fallback.update({
                    "width": int(embedded[1]),
                    "height": int(embedded[2]),
                    "header_ok": bool(embedded[3]),
                    "size": int(embedded[4]),
                    "catalog_source": "modifier-embedded",
                })
                return fallback
            except (IndexError, TypeError, ValueError, OverflowError):
                pass
        try:
            with open(path, "rb") as handle:
                header = handle.read(32)
            if len(header) != 32:
                return fallback
            words = struct.unpack("<8I", header)
            # Level room files have two closely related headers.  Version
            # 616 stores dimensions in words 3/4; newer 617 files (used by
            # many temple/ruin rooms) store them in words 1/2 and otherwise
            # carry the same native putRoom payload.
            if words[0] == 617:
                width, height = int(words[1]), int(words[2])
            else:
                width, height = int(words[3]), int(words[4])
            # ``t.map`` is the deliberately minimal one-cell test room. Its
            # header keeps zero dimensions because it is a resource probe,
            # but the native putRoom call materialises one tile in the world.
            # Give it a real display extent so the generated marker is not
            # silently dropped by the map overlay.
            if filename == "t.map" and width == 0 and height == 0:
                width, height = 1, 1
            # The first word is format version. Current scheme files keep
            # tile dimensions in header integers #3/#4 after that version.
            # Do not draw arbitrary extents if a future format changes them.
            if words[0] not in (616, 617) or not (1 <= width <= 400 and 1 <= height <= 400):
                return fallback
            fallback.update({"width": width, "height": height,
                             "header_ok": True, "header": list(words)})
        except (OSError, struct.error, ValueError):
            pass
        return fallback

    def _structure_catalog_files(self):
        """Return the bundled structure directory, with a local fallback."""
        if EMBEDDED_STRUCTURE_INDEX:
            return sorted((str(item[0]) for item in EMBEDDED_STRUCTURE_INDEX.values()),
                          key=lambda value: value.lower())
        root = os.path.join(GAME_ROOT, "Levels")
        try:
            names = []
            for entry in os.scandir(root):
                if entry.is_file() and entry.name.lower().endswith(".map"):
                    names.append(entry.name)
            return sorted(names, key=lambda value: value.lower())
        except OSError:
            return []

    @staticmethod
    def _structure_readback_mask(before, after, width, height):
        """Return cells changed by one native room placement.

        The World merges a room into ordinary map tiles and discards its
        filename.  Comparing all tile fields before/after the native call is
        the only reliable display evidence available at placement time.  A
        later map read must never turn unrelated terrain inside the source
        rectangle into part of this structure.
        """
        if not isinstance(before, dict) or not isinstance(after, dict):
            return []
        try:
            width, height = int(width), int(height)
        except (TypeError, ValueError, OverflowError):
            return []
        count = width * height
        if width < 1 or height < 1 or count > 160000:
            return []
        fields = ("w2", "front", "bg", "water")
        if any(not isinstance(before.get(key), list) or not isinstance(after.get(key), list)
               or len(before[key]) != count or len(after[key]) != count for key in fields):
            return []
        rows, changes = [], 0
        for row in range(height):
            chars = []
            for col in range(width):
                index = row * width + col
                changed = any(before[key][index] != after[key][index] for key in fields)
                chars.append("1" if changed else "0")
                changes += 1 if changed else 0
            rows.append("".join(chars))
        return rows if changes else []

    @staticmethod
    def _structure_live_mask(region, width, height):
        """Build an irregular occupancy mask from the current map cells.

        This is only a display fallback for annotations written by older
        builds (which have no before/after mask).  A cell is considered part of
        the visible structure only when the live map contains a foreground or
        outer entity value.  Empty cells stay empty, so the UI never invents a
        rectangular outline around an old annotation.
        """
        try:
            width, height = int(width), int(height)
            cols, rows = int(region.get("cols")), int(region.get("rows"))
            w2, front = region.get("w2"), region.get("front")
            if width < 1 or height < 1 or cols < 1 or rows < 1:
                return []
            if not isinstance(w2, list) or not isinstance(front, list):
                return []
            if len(w2) != cols * rows or len(front) != cols * rows:
                return []
            result = []
            changed = False
            for rr in range(height):
                line = []
                for cc in range(width):
                    if rr >= rows or cc >= cols:
                        present = False
                    else:
                        index = rr * cols + cc
                        try:
                            present = int(w2[index]) != 0xFFFF or int(front[index]) != 0xFFFF
                        except (TypeError, ValueError, OverflowError):
                            present = False
                    line.append("1" if present else "0")
                    changed = changed or present
                result.append("".join(line))
            return result if changed else []
        except (AttributeError, TypeError, ValueError, OverflowError):
            return []

    @staticmethod
    def _structure_mask_cells(record, map_width, map_height):
        """Return only cells proven to belong to a placed structure.

        A structure's header is always rectangular, while its actual tile
        footprint often is not.  The placement readback mask is the only
        evidence that distinguishes source tiles from terrain in the unused
        portions of that rectangle.  Never infer a deletion mask from live
        terrain: it can include blocks placed by the player after generation.
        """
        try:
            # Native Room records keep their original bounds for display, while
            # a conservative material probe may add a one-cell edge outside
            # that container.  Honour the probe origin when present; this
            # avoids silently shifting an irregular mask back to a rectangle.
            col = int(record.get("mask_origin_col", record.get("col", -1)))
            row = int(record.get("mask_origin_row", record.get("row", -1)))
            width = int(record.get("mask_width", record.get("width", 0)))
            height = int(record.get("mask_height", record.get("height", 0)))
            mask = record.get("mask")
        except (AttributeError, TypeError, ValueError, OverflowError):
            return []
        if (col < 0 or row < 0 or width < 1 or height < 1
                or not isinstance(mask, list) or len(mask) != height):
            return []
        cells = []
        for rr, raw_line in enumerate(mask):
            line = str(raw_line or "")
            # A truncated line cannot prove that all source cells were known.
            # Refuse the whole destructive map step rather than treating its
            # missing suffix as part of the room's rectangle.
            if len(line) != width or any(flag not in "01" for flag in line):
                return []
            for cc, flag in enumerate(line):
                if flag != "1":
                    continue
                target_row, target_col = row + rr, col + cc
                if 0 <= target_row < int(map_height) and 0 <= target_col < int(map_width):
                    cells.append((target_row, target_col))
        return cells

    def _native_structure_occupancy(self, record, map_width, map_height):
        """Derive a conservative irregular mask for a live native Room.

        ``UnderRoom`` exposes the room centre and container size, but not the
        source ``.map`` filename or its sparse tile silhouette.  We therefore
        use a read-only neighbourhood probe: a tile pair must occur at least
        twice inside the native bounds and must not occur in the surrounding
        one-cell ring.  Only such distinctive pairs are marked, and a ring
        tile is admitted when it is adjacent to an already marked tile.  This
        deliberately prefers an incomplete mask over deleting ordinary
        terrain that happens to share a common material id.
        """
        try:
            left, top = int(record.get("col")), int(record.get("row"))
            width, height = int(record.get("width")), int(record.get("height"))
        except (AttributeError, TypeError, ValueError, OverflowError):
            return None
        if left < 0 or top < 0 or width < 1 or height < 1:
            return None
        pad = 1
        r0, c0 = max(0, top - pad), max(0, left - pad)
        r1 = min(int(map_height) - 1, top + height - 1 + pad)
        c1 = min(int(map_width) - 1, left + width - 1 + pad)
        if r1 < r0 or c1 < c0:
            return None
        try:
            region = self.map_read_regions([{"r0": r0, "c0": c0,
                                             "r1": r1, "c1": c1}])
            region = (region.get("regions") or [None])[0] if region.get("ok") else None
            if not region:
                return None
            cols, rows = int(region.get("cols")), int(region.get("rows"))
            fronts, grounds = region.get("front"), region.get("w2")
            if len(fronts) != cols * rows or len(grounds) != cols * rows:
                return None
        except (AttributeError, TypeError, ValueError, IndexError, OSError):
            return None

        def pair_at(cc, rr):
            idx = (rr - r0) * cols + (cc - c0)
            return int(fronts[idx]) & 0xFFFF, int(grounds[idx]) & 0xFFFF

        inside, ring = collections.Counter(), collections.Counter()
        for rr in range(top, top + height):
            for cc in range(left, left + width):
                if 0 <= cc < int(map_width) and 0 <= rr < int(map_height):
                    pair = pair_at(cc, rr)
                    if pair != (0xFFFF, 0xFFFF):
                        inside[pair] += 1
        for rr in range(r0, r1 + 1):
            for cc in range(c0, c1 + 1):
                if left <= cc < left + width and top <= rr < top + height:
                    continue
                pair = pair_at(cc, rr)
                if pair != (0xFFFF, 0xFFFF):
                    ring[pair] += 1
        # These ids were confirmed from the native-room deletion samples.  A
        # known structure material may legitimately continue into the ring,
        # so permit it when it has multiple interior samples; unknown/common
        # terrain still requires a clean ring to be considered distinctive.
        known_ids = {326, 328, 329, 334, 2408, 1947, 1964, 1444}
        distinctive = {pair for pair, count in inside.items()
                       if count >= 2 and 1388 not in pair
                       and (ring.get(pair, 0) == 0
                            or any(int(value) in known_ids for value in pair))}
        if not distinctive:
            return None
        occupied = set()
        for rr in range(top, top + height):
            for cc in range(left, left + width):
                if pair_at(cc, rr) in distinctive:
                    occupied.add((cc, rr))
        # Capture only a directly adjacent one-cell extension.  This covers
        # the observed structure edge spill without growing through terrain.
        for rr in range(r0, r1 + 1):
            for cc in range(c0, c1 + 1):
                if (cc, rr) in occupied or pair_at(cc, rr) not in distinctive:
                    continue
                if any((cc + dc, rr + dr) in occupied
                       for dc, dr in ((1, 0), (-1, 0), (0, 1), (0, -1))):
                    occupied.add((cc, rr))
        if not occupied:
            return None
        min_col = max(0, min(cc for cc, _ in occupied))
        max_col = min(int(map_width) - 1, max(cc for cc, _ in occupied))
        min_row = max(0, min(rr for _, rr in occupied))
        max_row = min(int(map_height) - 1, max(rr for _, rr in occupied))
        mask = []
        for rr in range(min_row, max_row + 1):
            mask.append("".join("1" if (cc, rr) in occupied else "0"
                                for cc in range(min_col, max_col + 1)))
        if not any("1" in line for line in mask):
            return None
        return {"mask": mask, "mask_origin_col": min_col,
                "mask_origin_row": min_row, "mask_width": max_col - min_col + 1,
                "mask_height": max_row - min_row + 1,
                "occupied_cells": len(occupied),
                "mask_source": "native-material-neighborhood",
                "mask_confidence": "conservative"}

    def get_structure_catalog(self):
        """Return the bundled structure directory with safe preview metadata."""
        rows = []
        for filename in self._structure_catalog_files():
            path = os.path.join(GAME_ROOT, "Levels", filename)
            row = self._structure_descriptor(filename)
            # Both inline SSO and longer ASCII names are placeable. Long names
            # are staged and allocated by the game-thread controller before
            # entering luaWorld::putRoom.
            row["placeable"] = bool(filename and filename.isascii()
                                     and len(filename.encode("ascii")) <= 0x200)
            row["preview_only"] = not row["placeable"]
            bundled = filename.lower() in EMBEDDED_STRUCTURE_INDEX
            if bundled:
                # Do not stat 1,000+ game files while opening the list. The
                # actual native placement path validates the selected file.
                # ``available`` means the catalog entry is available, not that
                # the local game resource has already been verified.
                row.update({"available": True, "catalog_available": True,
                            "game_file_available": None,
                            "size": int(row.get("size") or 0),
                            "source": "modifier-embedded"})
            else:
                available = os.path.isfile(path)
                row.update({"available": available, "catalog_available": available,
                            "game_file_available": available,
                            "size": os.path.getsize(path) if available else 0,
                            "source": "game-levels"})
            rows.append(row)
        with self._structure_history_lock:
            placed = [dict(item) for item in self._structure_runtime_history
                      if str(item.get("source") or "").startswith("native-runtime")]
        return {"ok": True, "state": self.STATUS_VERIFIED, "structures": rows,
                "placed": placed,
                "source": "modifier-embedded" if EMBEDDED_STRUCTURE_INDEX else "game-levels",
                "note": "结构目录、名称和尺寸由修改器内嵌；生成时仍由游戏原生读取 Levels 中对应的 .map 文件。"}

    def get_structure_resource_status(self, filename):
        """Verify one selected Levels resource without rescanning the catalog."""
        name = os.path.basename(str(filename or "").strip())
        if not name or name.lower() not in EMBEDDED_STRUCTURE_INDEX:
            return {"ok": False, "state": self.STATUS_UNSUPPORTED,
                    "error": "该结构不在修改器内嵌目录中"}
        path = os.path.join(GAME_ROOT, "Levels", name)
        exists = os.path.isfile(path)
        return {"ok": True, "state": self.STATUS_VERIFIED if exists else self.STATUS_FAILED,
                "file": name, "game_file_available": exists,
                "message": "游戏资源已确认" if exists else "本机游戏缺少该结构文件"}

    def scan_map_structures(self):
        """Return live native room records for the current save only.

        A merged tile has no source-file field.  The authoritative
        ``World::UnderRoom`` vector is therefore read first; modifier
        placement history remains excluded so changing saves cannot leave
        ghost annotations.
        """
        map_key = self._structure_map_key()
        saved = self._read_native_room_records()
        persisted = self._saved_map_structures(map_key)
        # Only records emitted by a native runtime scanner/container are
        # eligible for the map overlay.  Modifier placement history is
        # intentionally excluded: it is not evidence of a natural structure.
        saved = [item for item in saved if str(item.get("source") or "").startswith("native-")]
        # A native UnderRoom record carries bounds but no source filename.
        # Local placement metadata may *name* a matching live record; it must
        # never create an overlay by itself.  The old fallback kept a
        # ``portal.map`` record after the room was gone or after a save switch,
        # which produced a large phantom “其它结构 · portal” annotation.
        merged = {}
        for item in saved:
            try:
                anchor = (int(item.get("row")), int(item.get("col")))
                key = (str(item.get("file")).lower(), anchor[0], anchor[1])
                merged[key] = item
            except (TypeError, ValueError):
                continue
        # Persisted modifier placements retain the exact readback mask.  When
        # the live native room has the same anchor and dimensions, enrich that
        # placement with its actual World::UnderRoom slot instead of throwing
        # either record away.  The browser list order is never a native slot.
        for item in persisted:
            try:
                anchor = (int(item.get("row")), int(item.get("col")))
                key = (str(item.get("file")).lower(), anchor[0], anchor[1])
                native_match = next((existing for existing in saved
                                     if (int(existing.get("row", -1)), int(existing.get("col", -1))) == anchor
                                     and int(existing.get("width", -1)) == int(item.get("width", -2))
                                     and int(existing.get("height", -1)) == int(item.get("height", -2))), None)
                if native_match:
                    combined = dict(item)
                    combined["native_record_index"] = int(native_match.get("record_index", -1))
                    for existing_key, existing in list(merged.items()):
                        if (int(existing.get("row", -1)), int(existing.get("col", -1))) == anchor:
                            del merged[existing_key]
                    merged[key] = combined
            except (TypeError, ValueError):
                continue
        placed = list(merged.values())
        for item in placed:
            descriptor = self._structure_descriptor(item.get("file"))
            item.setdefault("name", descriptor["name"])
            item.setdefault("width", descriptor["width"])
            item.setdefault("height", descriptor["height"])
            item.setdefault("category", descriptor["category"])
            item.setdefault("source", "native-room-container")
            item.setdefault("confidence", self.STATUS_VERIFIED)
            item["live_native_room"] = int(item.get("native_record_index", -1)) >= 0
        return {"ok": True, "state": self.STATUS_VERIFIED if placed else self.STATUS_UNVERIFIED,
                "map_key": map_key, "structures": self._clean_structure_records(placed),
                "note": ("已显示来自游戏原生 Room 容器的结构。"
                         if placed else "当前尚未定位到游戏原生 Room/UnderRoom 容器；已隐藏修改器生成记录和旧缓存，避免误标自然结构。")}

    def _query_world_object_occupancy(self, obj, anchor_col, anchor_row,
                                      object_width, object_height, cell_width,
                                      cell_height, map_width, map_height):
        """Return only the cells hit by the native ItemEntity lookup.

        ``width`` and ``height`` in an ItemEntity are render metrics; they are
        useful only for selecting a conservative search neighbourhood.  The
        returned mask itself comes exclusively from
        ``World::FindEntityByCellWithBounds`` on the game thread.  A ``None``
        return means the native dispatcher did not confirm a complete query,
        never that the object has a rectangular footprint.
        """
        try:
            obj = int(obj)
            anchor_col, anchor_row = int(anchor_col), int(anchor_row)
            span_cols = max(1, int(math.ceil(float(object_width) / float(cell_width))))
            span_rows = max(1, int(math.ceil(float(object_height) / float(cell_height))))
        except (TypeError, ValueError, OverflowError, ZeroDivisionError):
            return None
        # ItemEntity anchors can be centred or down-aligned. Search symmetrically
        # with a small margin; this is only a search window, not an asserted
        # footprint.  The native result decides every highlighted cell.
        c0 = max(0, anchor_col - span_cols - 2)
        c1 = min(int(map_width) - 1, anchor_col + span_cols + 2)
        r0 = max(0, anchor_row - span_rows - 2)
        r1 = min(int(map_height) - 1, anchor_row + span_rows + 2)
        if c0 > c1 or r0 > r1:
            return None
        with self._wave_portal_lock, self._memory_write_lock:
            controller, error = self._ensure_wave_portal_controller()
            if not controller:
                _diagnostic("world object occupancy controller:", error)
                return None
            data = int(controller["data"])
            request = data + self.WORLD_OBJECT_OCCUPANCY_REQUEST_OFF
            status_addr = data + self.WORLD_OBJECT_OCCUPANCY_STATUS_OFF
            count_addr = data + self.WORLD_OBJECT_OCCUPANCY_COUNT_OFF
            mask_addr = data + self.WORLD_OBJECT_OCCUPANCY_MASK_OFF
            if int(pm.read_int(request) or 0):
                return None
            cells = []
            # The game-thread handler has a fixed 256-byte result buffer.  A
            # large visual search is partitioned, so no response can overrun
            # the temporary page and every chunk remains independently valid.
            max_cells = int(self.WORLD_OBJECT_OCCUPANCY_MAX_CELLS)
            for chunk_c0 in range(c0, c1 + 1, 16):
                chunk_c1 = min(c1, chunk_c0 + 15)
                cols = chunk_c1 - chunk_c0 + 1
                rows_per_chunk = max(1, max_cells // cols)
                for chunk_r0 in range(r0, r1 + 1, rows_per_chunk):
                    chunk_r1 = min(r1, chunk_r0 + rows_per_chunk - 1)
                    rows = chunk_r1 - chunk_r0 + 1
                    total = cols * rows
                    if total < 1 or total > max_cells:
                        return None
                    pm.write_bytes(mask_addr, b"\x00" * max_cells, max_cells)
                    pm.write_int(data + self.WORLD_OBJECT_OCCUPANCY_TARGET_OFF, obj)
                    pm.write_int(data + self.WORLD_OBJECT_OCCUPANCY_C0_OFF, chunk_c0)
                    pm.write_int(data + self.WORLD_OBJECT_OCCUPANCY_C1_OFF, chunk_c1)
                    pm.write_int(data + self.WORLD_OBJECT_OCCUPANCY_R0_OFF, chunk_r0)
                    pm.write_int(data + self.WORLD_OBJECT_OCCUPANCY_R1_OFF, chunk_r1)
                    pm.write_int(count_addr, 0)
                    pm.write_int(status_addr, 0)
                    # Request is deliberately written last: the game thread
                    # sees a complete target, bounds and empty result mask.
                    pm.write_int(request, 1)
                    # This queue is serviced by the running game thread on
                    # its next normal tick.  Do not make a paused game turn
                    # a many-second wait for every map object; fall back to
                    # the verified anchor and let the user retry after resume.
                    deadline = time.monotonic() + 0.6
                    while time.monotonic() < deadline:
                        if int(pm.read_int(status_addr) or 0) == 1:
                            break
                        time.sleep(0.01)
                    if int(pm.read_int(status_addr) or 0) != 1:
                        return None
                    raw = pm.read_bytes(mask_addr, total)
                    if not raw or len(raw) != total:
                        return None
                    # The handler walks columns outside and rows inside.
                    for local_col in range(cols):
                        for local_row in range(rows):
                            if raw[local_col * rows + local_row] != 1:
                                continue
                            cells.append({"col": chunk_c0 + local_col,
                                          "row": chunk_r0 + local_row})
            return cells
        
    def _read_world_object_id(self, obj):
        """Read the identifier carried by an independent World object.

        The current build stores short identifiers (for example
        ``dragon_egg``) inline at ``GameObject+0x10``.  Some longer names use
        the normal MSVC string buffer, so fall back to its pointer only after
        the inline bytes have failed strict validation.  This helper is
        intentionally read-only and returns an empty name rather than guessing
        a type from a vtable address.
        """
        try:
            raw = pm.read_bytes(int(obj) + self.WORLD_OBJECT_NAME_OFF, 32)
            if not raw:
                return ""
            direct = raw.split(b"\x00", 1)[0].decode("ascii", errors="ignore").strip()
            if re.fullmatch(r"[A-Za-z][A-Za-z0-9_.-]{1,63}", direct or ""):
                return direct.lower()
            if len(raw) < 24:
                return ""
            # MSVC's non-SSO layout is ``pointer, ..., length, capacity``.
            # ``length`` is at the string object's +0x10, rather than directly
            # after the pointer.  Reading +0x04 here treated allocator data as
            # a length and silently hid every long object identifier.
            text_ptr = struct.unpack_from("<I", raw, 0)[0]
            text_len = struct.unpack_from("<I", raw, 0x10)[0]
            if not (_is_plausible_32bit_pointer(text_ptr) and 1 <= text_len <= 64):
                return ""
            pointed = _read_ascii_string(pm, text_ptr, int(text_len)).strip()
            if re.fullmatch(r"[A-Za-z][A-Za-z0-9_.-]{1,63}", pointed or ""):
                return pointed.lower()
        except Exception:
            return ""
        return ""

    def _is_displayable_world_object(self, object_id):
        """Exclude runtime fragments that are not independent map objects.

        Native rooms own several helper ItemEntity instances (for example
        ``r1``/``xr1`` and ``stone_eater_cave*``).  They are real heap objects
        but are only sprite/collision pieces of a room, so presenting them as
        selectable structures confuses the map and makes deletion unsafe.
        Keep the filter deliberately narrow: unknown named objects remain
        visible for investigation instead of being silently hidden.
        """
        name = str(object_id or "").strip().lower()
        if not name:
            return False
        if name in {"r1", "xr1"}:
            return False
        return not name.startswith("stone_eater_cave")

    def scan_map_world_objects(self, precise=False):
        """Return independent live World objects for the map's object layer.

        Map tile layers contain only block IDs.  Visible entities such as a
        dragon egg or an entity-backed door live in the separate World object
        vector, so they must be read and rendered independently.  Records are
        process/save-scoped and deliberately never persisted in configuration.
        """
        if not connected or pm is None:
            return self._read_envelope(False, self.STATUS_DISCONNECTED,
                                       error="尚未连接游戏")
        try:
            resolved = self._map_resolve()
            if not resolved:
                state, detail = self._runtime_read_unavailable_state()
                return self._read_envelope(False, state, error=detail)
            map_data, map_width, map_height, world_width, world_height = resolved
            world = int(pm.read_int(base_addr + ITEM_BASE_OFFSET) or 0)
            begin = int(pm.read_int(world + self.WORLD_OBJECTS_BEGIN_OFF) or 0) if world else 0
            end = int(pm.read_int(world + self.WORLD_OBJECTS_END_OFF) or 0) if world else 0
            span = end - begin
            if (begin <= 0 or end < begin or span % 4 != 0
                    or span > 4 * self.WORLD_OBJECT_MAX_COUNT):
                return self._read_envelope(False, self.STATUS_STALE,
                                           error="当前版本未确认独立对象容器")
            if span == 0:
                return self._read_envelope(True, self.STATUS_VERIFIED, [],
                                           entities=[], count=0,
                                           note="当前地图没有可读取的独立对象")
            vector_raw = pm.read_bytes(begin, span)
            if not vector_raw or len(vector_raw) < span:
                return self._read_envelope(False, self.STATUS_STALE,
                                           error="独立对象容器读取不完整")
            cell_width = float(world_width) / float(map_width)
            cell_height = float(world_height) / float(map_height)
            if cell_width <= 0 or cell_height <= 0:
                return self._read_envelope(False, self.STATUS_STALE,
                                           error="地图格尺寸无效")
            # Only an explicit “读取对象” click starts a native per-cell
            # lookup. Automatic map refreshes reuse the current save's mask,
            # or show the verified anchor alone until the user asks for a
            # precise read. This avoids turning a 2.5-second UI refresh into a
            # heavy stream of game-thread calls.
            precise = bool(precise)
            scope = (int(pm.process_id), int(world), int(map_data),
                     int(map_width), int(map_height))
            cache = self._world_object_occupancy_cache
            if cache.get("scope") != scope:
                cache = {"scope": scope, "items": {}}
                self._world_object_occupancy_cache = cache
            cached_items = cache["items"]
            entities = []
            transient_failures = 0
            for index in range(span // 4):
                obj = int(struct.unpack_from("<I", vector_raw, index * 4)[0] or 0)
                if not _is_plausible_32bit_pointer(obj):
                    continue
                try:
                    raw = pm.read_bytes(obj, self.WORLD_OBJECT_DESTROYED_OFF + 1)
                    if not raw or len(raw) < self.WORLD_OBJECT_DESTROYED_OFF + 1:
                        continue
                    # GameObject::Destroy completes component cleanup and
                    # sets +0xA6.  Some persistent objects retain their slot
                    # in World's vector until a later world cleanup, so a
                    # live-object map must never draw or target them again.
                    if raw[self.WORLD_OBJECT_DESTROYED_OFF]:
                        continue
                    vtable = int(struct.unpack_from("<I", raw, 0)[0] or 0)
                    x, y, width, height = struct.unpack_from(
                        "<4f", raw, self.WORLD_OBJECT_X_OFF)
                    if (not all(math.isfinite(value) for value in (x, y, width, height))
                            or width <= 0 or height <= 0
                            or width > world_width * 2 or height > world_height * 2):
                        continue
                    # Object coordinates are logical placement anchors, not
                    # pixel top-left corners.  They locate an object and set
                    # a bounded search window only; they never define the
                    # displayed occupancy rectangle.
                    left = max(0, min(map_width - 1, int(math.floor(x / cell_width))))
                    top = max(0, min(map_height - 1, int(math.floor(y / cell_height))))
                    object_id = self._read_world_object_id(obj)
                    if not self._is_displayable_world_object(object_id):
                        continue
                    label = self.WORLD_OBJECT_DISPLAY_NAMES.get(object_id)
                    if not label:
                        label = object_id.replace("_", " ") if object_id else "未命名对象"
                    cache_key = (int(obj), int(vtable), int(left), int(top),
                                 round(float(width), 3), round(float(height), 3))
                    cached = cached_items.get(cache_key)
                    cells = list(cached.get("cells") or []) if isinstance(cached, dict) else []
                    occupancy_state = str(cached.get("state") or "") if isinstance(cached, dict) else ""
                    if precise and not cells:
                        native_cells = self._query_world_object_occupancy(
                            obj, left, top, width, height, cell_width, cell_height,
                            map_width, map_height,
                        )
                        if native_cells is not None:
                            cells = native_cells
                            occupancy_state = "native-cell-hit"
                            cached_items[cache_key] = {"cells": list(cells),
                                                       "state": occupancy_state}
                    # A single anchor cell is a verified location. It is much
                    # more honest than the old guessed rectangle when no
                    # native occupancy mask has been read yet.
                    if not cells:
                        cells = [{"col": left, "row": top}]
                        occupancy_state = "anchor-only"
                    valid_cells = []
                    seen_cells = set()
                    for cell in cells:
                        try:
                            cell_col, cell_row = int(cell["col"]), int(cell["row"])
                        except (KeyError, TypeError, ValueError, OverflowError):
                            continue
                        if not (0 <= cell_col < map_width and 0 <= cell_row < map_height):
                            continue
                        key = (cell_col, cell_row)
                        if key not in seen_cells:
                            seen_cells.add(key)
                            valid_cells.append({"col": cell_col, "row": cell_row})
                    if not valid_cells:
                        valid_cells = [{"col": left, "row": top}]
                        occupancy_state = "anchor-only"
                    bounds_left = min(cell["col"] for cell in valid_cells)
                    bounds_top = min(cell["row"] for cell in valid_cells)
                    bounds_right = max(cell["col"] for cell in valid_cells) + 1
                    bounds_bottom = max(cell["row"] for cell in valid_cells) + 1
                    entities.append({
                        "index": index,
                        "id": object_id,
                        "name": label,
                        "address": "0x%08X" % obj,
                        "vtable": "0x%08X" % vtable,
                        "col": left,
                        "row": top,
                        "right": bounds_right,
                        "bottom": bounds_bottom,
                        "width": bounds_right - bounds_left,
                        "height": bounds_bottom - bounds_top,
                        "cells": valid_cells,
                        "occupied_cells": len(valid_cells),
                        "occupancy_state": occupancy_state,
                        "world_x": round(float(x), 2),
                        "world_y": round(float(y), 2),
                        "world_width": round(float(width), 2),
                        "world_height": round(float(height), 2),
                        "confidence": self.STATUS_VERIFIED,
                    })
                # World can retain a pointer for a short period while an
                # object is being destroyed.  A failed candidate must not
                # abort the complete map scan or leak a traceback to the UI.
                except Exception:
                    # World can change this vector while an object is being
                    # destroyed.  Keep scanning the remaining objects, while
                    # preserving enough evidence for the UI to distinguish a
                    # transient read race from an empty object layer.
                    transient_failures += 1
                    continue
            entities.sort(key=lambda item: (int(item["row"]), int(item["col"]), int(item["index"])))
            note = "已从游戏 World 独立对象容器读取；对象与地图外层方块分开显示。"
            if transient_failures:
                note += " 已跳过 %d 个正在变化或无法读取的对象；刷新后会重新尝试。" % transient_failures
            return self._read_envelope(True, self.STATUS_VERIFIED, entities,
                                       entities=entities, count=len(entities),
                                       transient_failures=transient_failures,
                                       note=note)
        except Exception as exc:
            _diagnostic("scan_map_world_objects:", exc)
            return self._read_envelope(False, self.STATUS_STALE,
                                       error="独立对象读取失败：%s" % (str(exc) or "对象容器正在变化；请刷新后重试"))

    def get_special_entity_catalog(self):
        """Return the special-entity catalogue without reading external files.

        Only curated, resource-defined ItemEntity candidates are listed.
        Event containers such as Pandora are deliberately excluded because
        they need a separate event-container initialization chain.
        """
        rows = []
        for entity_id, definition in self.SPECIAL_ENTITY_DEFINITIONS.items():
            row = {"id": entity_id, **dict(definition)}
            row["available"] = None
            row["live_count"] = 0
            rows.append(row)
        if connected and pm:
            try:
                result = self.scan_map_world_objects(False)
                entities = result.get("entities") or [] if isinstance(result, dict) else []
                counts = {}
                for item in entities:
                    key = str(item.get("id") or "").strip().lower()
                    counts[key] = counts.get(key, 0) + 1
                for row in rows:
                    row["live_count"] = int(counts.get(row["id"], 0))
                    # Availability means the native Item definition is loaded,
                    # not that an instance already exists on the map.  This is
                    # deliberately resolved from ResourceManager's Item* table
                    # so a fresh map can still generate a dragon egg.
                    if row.get("supported"):
                        resolved_item, _ = self._resolve_special_entity_item(row["id"])
                        row["available"] = bool(resolved_item)
                    else:
                        row["available"] = False
            except Exception:
                pass
        return {"ok": True, "state": self.STATUS_VERIFIED,
                "entities": rows,
                "note": "特殊实体与地图方块分开管理；生成只开放已验证的原生 ItemEntity 路径。"}

    def _resolve_special_entity_item(self, entity_id):
        """Resolve the shared Item definition used by native item lookup.

        ``World::AddItemInstance`` expects an ``Item*`` from the
        ResourceManager item-definition vector, not a resource-table slot and
        not an ItemEntity copied from the map.  The game's FindItemByName
        routine walks ``manager + 0x474 .. +0x478`` and compares each Item's
        name/hash.  Reading that same authoritative vector means generation
        works even when the requested entity has never existed in the map.
        """
        entity_id = str(entity_id or "").strip().lower()
        if entity_id not in self.SPECIAL_ENTITY_ALLOWED:
            return None, "该特殊实体尚未通过原生生成验收"
        try:
            manager = int(pm.read_int(int(get_base()) + ITEM_BASE_OFFSET) or 0)
            begin = int(pm.read_int(manager + self.ITEM_DEFINITION_VECTOR_BEGIN_OFF) or 0)
            end = int(pm.read_int(manager + self.ITEM_DEFINITION_VECTOR_END_OFF) or 0)
            span = end - begin
            # FindItemByName uses a vector of Item* (4-byte entries).  Keep
            # bounds conservative so a stale manager cannot turn into an
            # arbitrary process-memory walk.
            if not (_is_plausible_32bit_pointer(manager) and
                    _is_plausible_32bit_pointer(begin) and end >= begin and
                    span % 4 == 0 and span <= 4 * 10000):
                return None, "当前游戏的 Item 定义表不可读"
            scope = (int(pm.process_id), manager, begin, end)
            cache = self._special_entity_item_cache
            if cache.get("scope") != scope:
                # The catalogue is refreshed automatically after connection.
                # Index the authoritative vector once per process instead of
                # walking ~2,000 remote Item entries once for every option.
                indexed = {}
                for index in range(span // 4):
                    item = int(pm.read_int(begin + index * 4) or 0)
                    if not _is_plausible_32bit_pointer(item):
                        continue
                    try:
                        name = _read_item_name(pm, item, 0x64, 32, 64).strip().lower()
                    except Exception:
                        continue
                    if name and name not in indexed:
                        indexed[name] = item
                cache = {"scope": scope, "items": indexed}
                self._special_entity_item_cache = cache
            item = int((cache.get("items") or {}).get(entity_id) or 0)
            if _is_plausible_32bit_pointer(item):
                return item, ""
            return None, "游戏资源中未找到 %s 的原生 Item 定义" % (
                self.SPECIAL_ENTITY_DEFINITIONS.get(entity_id, {}).get("name", entity_id))
        except (AttributeError, OSError, TypeError, ValueError, OverflowError, struct.error) as exc:
            return None, "特殊实体 Item 定义定位失败：%s" % exc

    def spawn_special_entity(self, entity_id="dragon_egg", col=0, row=0):
        """Queue one validated special ItemEntity on the real game thread."""
        if not connected or not pm:
            return {"ok": False, "state": self.STATUS_DISCONNECTED,
                    "error": "请先连接游戏并进入已加载的存档"}
        entity_id = str(entity_id or "").strip().lower()
        definition = self.SPECIAL_ENTITY_DEFINITIONS.get(entity_id)
        if not definition or not definition.get("supported"):
            return {"ok": False, "state": self.STATUS_UNSUPPORTED,
                    "error": (definition or {}).get("note", "该特殊实体暂未开放生成")}
        try:
            col, row = int(col), int(row)
        except (TypeError, ValueError, OverflowError):
            return {"ok": False, "error": "列和行必须是整数"}
        if col < 0 or row < 0:
            return {"ok": False, "error": "列和行不能为负数"}
        resolved = self._map_resolve()
        if not resolved:
            return {"ok": False, "error": "地图未载入，请进入存档后重试"}
        _map_data, map_width, map_height, _world_width, _world_height = resolved
        if col >= int(map_width) or row >= int(map_height):
            return {"ok": False, "error": "坐标超出当前地图范围"}
        item, item_error = self._resolve_special_entity_item(entity_id)
        if not item:
            return {"ok": False, "state": self.STATUS_STALE, "error": item_error}
        try:
            module_base = int(get_base())
            add_address = module_base + self.V1_WORLD_ADD_ITEM_INSTANCE_RVA
            if pm.read_bytes(add_address, len(self.V1_WORLD_ADD_ITEM_INSTANCE_PREFIX)) != self.V1_WORLD_ADD_ITEM_INSTANCE_PREFIX:
                return {"ok": False, "state": self.STATUS_UNSUPPORTED,
                        "error": "当前游戏版本的原生实体生成入口未通过校验"}
        except Exception as exc:
            return {"ok": False, "error": "无法验证原生实体生成入口：%s" % exc}
        with self._wave_portal_lock, self._memory_write_lock:
            controller, error = self._ensure_wave_portal_controller()
            if not controller:
                return {"ok": False, "error": error}
            data = int(controller["data"])
            request = data + self.SPECIAL_ENTITY_QUEUE_REQUEST_OFF
            result_addr = data + self.SPECIAL_ENTITY_QUEUE_RESULT_OFF
            status_addr = data + self.SPECIAL_ENTITY_QUEUE_STATUS_OFF
            try:
                if int(pm.read_int(request) or 0):
                    return {"ok": False, "error": "上一条特殊实体生成请求仍在等待处理"}
                before = self.scan_map_world_objects(False)
                before_entities = before.get("entities") or [] if isinstance(before, dict) else []
                before_addresses = {str(item.get("address")) for item in before_entities
                                    if str(item.get("id") or "").lower() == entity_id}
                pm.write_int(result_addr, 0)
                pm.write_int(status_addr, 0)
                pm.write_int(data + self.SPECIAL_ENTITY_QUEUE_ITEM_OFF, int(item))
                pm.write_int(data + self.SPECIAL_ENTITY_QUEUE_X_OFF, col)
                pm.write_int(data + self.SPECIAL_ENTITY_QUEUE_Y_OFF, row)
                pm.write_int(request, 1)
            except Exception as exc:
                return {"ok": False, "error": "提交特殊实体生成请求失败：%s" % exc}
            deadline = time.monotonic() + 2.5
            while time.monotonic() < deadline:
                try:
                    if int(pm.read_int(status_addr) or 0) == 1:
                        break
                except Exception:
                    pass
                time.sleep(0.03)
            if int(pm.read_int(status_addr) or 0) != 1:
                return {"ok": False, "state": self.STATUS_FAILED,
                        "error": "游戏未确认特殊实体生成请求"}
            native_entity = int(pm.read_int(result_addr) or 0)
            deadline = time.monotonic() + 3.0
            created = None
            while time.monotonic() < deadline:
                current = self.scan_map_world_objects(False)
                current_entities = current.get("entities") or [] if isinstance(current, dict) else []
                candidates = [entry for entry in current_entities
                              if str(entry.get("id") or "").lower() == entity_id
                              and str(entry.get("address")) not in before_addresses]
                if native_entity:
                    exact = "0x%08X" % native_entity
                    exact_rows = [entry for entry in candidates if str(entry.get("address")) == exact]
                    if exact_rows:
                        created = exact_rows[0]
                        break
                if len(candidates) == 1:
                    created = candidates[0]
                    break
                time.sleep(0.06)
            if not created:
                return {"ok": False, "created": False,
                        "error": "原生调用已返回，但未在独立对象数组中确认新增对象"}
            note = str(definition.get("note") or
                       "已由游戏原生 AddItemInstance 创建；组件、孵化计时和存档登记由游戏管理。")
            return {"ok": True, "created": True, "state": self.STATUS_VERIFIED,
                    "entity": created, "note": note}

    def spawn_special_entity_batch(self, entity_id="dragon_egg", col=0, row=0,
                                   count=1, spacing=3):
        """Place a small, non-overlapping grid of curated special entities."""
        entity_id = str(entity_id or "").strip().lower()
        definition = self.SPECIAL_ENTITY_DEFINITIONS.get(entity_id) or {}
        if definition and not definition.get("batch_allowed", True):
            return {"ok": False, "state": self.STATUS_UNSUPPORTED,
                    "error": "%s 不允许批量生成：%s" % (
                        definition.get("name", entity_id),
                        definition.get("note", "该实体需要逐个谨慎放置"))}
        try:
            col, row, count, spacing = int(col), int(row), int(count), int(spacing)
        except (TypeError, ValueError, OverflowError):
            return {"ok": False, "error": "坐标、数量和间距必须是整数"}
        if not (1 <= count <= 16):
            return {"ok": False, "error": "批量生成数量限 1–16 个"}
        if not (1 <= spacing <= 12):
            return {"ok": False, "error": "实体间距限 1–12 格"}
        resolved = self._map_resolve()
        if not resolved:
            return {"ok": False, "state": self.STATUS_STALE, "error": "当前地图不可读"}
        _map_data, map_width, map_height, _world_width, _world_height = resolved
        columns = max(1, int(math.ceil(math.sqrt(count))))
        positions = [(col + (index % columns) * spacing,
                      row + (index // columns) * spacing) for index in range(count)]
        if any(c < 0 or r < 0 or c >= int(map_width) or r >= int(map_height)
               for c, r in positions):
            return {"ok": False, "error": "按当前数量和间距排布后会超出地图边界"}
        created, failures = [], []
        for c, r in positions:
            result = self.spawn_special_entity(entity_id, c, r)
            if result.get("ok"):
                created.append(result.get("entity") or {"col": c, "row": r})
            else:
                failures.append({"col": c, "row": r,
                                 "error": result.get("error") or "游戏未确认"})
        return {"ok": bool(created) and not failures,
                "state": self.STATUS_VERIFIED if created and not failures else self.STATUS_FAILED,
                "created": created, "created_count": len(created),
                "failed": failures, "requested_count": count,
                "layout": {"columns": columns, "spacing": spacing},
                "error": ("批量生成中有 %d 个未完成" % len(failures)) if failures else ""}

    def spawn_special_entities(self, entities):
        """Replay a small clipboard list of curated ItemEntities natively.

        The browser sends only an id and target map cell per entity.  Each
        placement still goes through ``spawn_special_entity`` so the Item*
        lookup, game-thread queue and post-create object verification are
        repeated for every copied entity.
        """
        if not isinstance(entities, (list, tuple)):
            return {"ok": False, "error": "特殊实体复制数据无效"}
        if not entities:
            return {"ok": True, "state": self.STATUS_EMPTY,
                    "created_count": 0, "created": []}
        if len(entities) > 32:
            return {"ok": False, "error": "一次复制最多包含 32 个特殊实体"}
        resolved = self._map_resolve()
        if not resolved:
            return {"ok": False, "state": self.STATUS_STALE, "error": "当前地图不可读"}
        _map_data, map_width, map_height, _world_width, _world_height = resolved
        placements = []
        for raw in entities:
            if not isinstance(raw, dict):
                return {"ok": False, "error": "特殊实体复制条目无效"}
            entity_id = str(raw.get("id") or "").strip().lower()
            if entity_id not in self.SPECIAL_ENTITY_ALLOWED:
                return {"ok": False, "error": "复制内容包含未开放的实体：%s" % entity_id}
            try:
                col, row = int(raw.get("col")), int(raw.get("row"))
            except (TypeError, ValueError, OverflowError):
                return {"ok": False, "error": "特殊实体复制坐标无效"}
            if not (0 <= col < int(map_width) and 0 <= row < int(map_height)):
                return {"ok": False, "error": "特殊实体复制目标超出地图边界"}
            item, item_error = self._resolve_special_entity_item(entity_id)
            if not item:
                return {"ok": False, "state": self.STATUS_STALE, "error": item_error}
            placements.append({"id": entity_id, "col": col, "row": row})
        created, failures = [], []
        for placement in placements:
            result = self.spawn_special_entity(placement["id"], placement["col"], placement["row"])
            if result.get("ok"):
                created.append(result.get("entity") or placement)
            else:
                failures.append({**placement, "error": result.get("error") or "游戏未确认"})
        return {"ok": bool(created) and not failures,
                "state": self.STATUS_VERIFIED if created and not failures else self.STATUS_FAILED,
                "created_count": len(created), "created": created, "failed": failures,
                "error": "特殊实体复制中有 %d 个未完成" % len(failures) if failures else ""}

    def delete_special_entities_in_cells(self, cells):
        """Queue destruction for curated ItemEntities anchored in a selection.

        This never edits World vectors from Python.  Every target is freshly
        resolved from the live vector and revalidated on the game thread with
        both its Item pointer and primary vtable before GameObject::Destroy.
        """
        if not connected or pm is None:
            return {"ok": False, "state": self.STATUS_DISCONNECTED,
                    "error": "请先连接并进入已加载的存档"}
        if not isinstance(cells, (list, tuple)):
            return {"ok": False, "error": "选区数据无效"}
        try:
            resolved = self._map_resolve()
            if not resolved:
                return {"ok": False, "state": self.STATUS_STALE, "error": "当前地图不可读"}
            _map_data, map_width, map_height, world_width, world_height = resolved
            selected = set()
            for cell in cells[:1024]:
                c, r = int(cell.get("col")), int(cell.get("row"))
                if 0 <= c < int(map_width) and 0 <= r < int(map_height):
                    selected.add((c, r))
            if not selected:
                return {"ok": False, "state": self.STATUS_EMPTY, "error": "选区中没有有效地图格"}
            module_base = int(get_base())
            if pm.read_bytes(module_base + self.V1_GAME_OBJECT_DESTROY_RVA,
                             len(self.V1_GAME_OBJECT_DESTROY_PREFIX)) != self.V1_GAME_OBJECT_DESTROY_PREFIX:
                return {"ok": False, "state": self.STATUS_UNSUPPORTED,
                        "error": "当前游戏版本的实体销毁入口未通过校验"}
            if pm.read_bytes(module_base + self.V1_GAME_OBJECT_MANAGER_UNREGISTER_RVA,
                             len(self.V1_GAME_OBJECT_MANAGER_UNREGISTER_PREFIX)) != self.V1_GAME_OBJECT_MANAGER_UNREGISTER_PREFIX:
                return {"ok": False, "state": self.STATUS_UNSUPPORTED,
                        "error": "当前游戏版本的完整实体移除入口未通过校验"}
            if pm.read_bytes(module_base + self.V1_WORLD_OBJECT_REMOVE_RVA, 6) != self.V1_GAME_OBJECT_MANAGER_UNREGISTER_PREFIX:
                return {"ok": False, "state": self.STATUS_UNSUPPORTED,
                        "error": "当前游戏版本的世界对象移除入口未通过校验"}
            world = int(pm.read_int(module_base + ITEM_BASE_OFFSET) or 0)
            begin = int(pm.read_int(world + self.WORLD_OBJECTS_BEGIN_OFF) or 0)
            end = int(pm.read_int(world + self.WORLD_OBJECTS_END_OFF) or 0)
            span = end - begin
            if not (_is_plausible_32bit_pointer(world) and _is_plausible_32bit_pointer(begin)
                    and end >= begin and span % 4 == 0
                    and span <= 4 * self.WORLD_OBJECT_MAX_COUNT):
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "当前存档的独立对象容器不可读"}
            manager = int(pm.read_int(module_base + self.V1_GAME_OBJECT_MANAGER_SINGLETON_PTR_RVA) or 0)
            manager_begin = int(pm.read_int(manager + self.V1_GAME_OBJECT_MANAGER_OBJECTS_BEGIN_OFF) or 0)
            manager_end = int(pm.read_int(manager + self.V1_GAME_OBJECT_MANAGER_OBJECTS_END_OFF) or 0)
            manager_span = manager_end - manager_begin
            if not (_is_plausible_32bit_pointer(manager) and _is_plausible_32bit_pointer(manager_begin)
                    and manager_end >= manager_begin and manager_span % 4 == 0
                    and manager_span <= 4 * 20000):
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "游戏对象管理器不可读，未执行删除"}
            manager_objects = set(struct.unpack("<%dI" % (manager_span // 4),
                                                pm.read_bytes(manager_begin, manager_span)))
            cell_width, cell_height = float(world_width) / float(map_width), float(world_height) / float(map_height)
            targets = []
            for index in range(span // 4):
                obj = int(pm.read_int(begin + index * 4) or 0)
                if not _is_plausible_32bit_pointer(obj):
                    continue
                try:
                    if pm.read_bytes(obj + self.WORLD_OBJECT_DESTROYED_OFF, 1)[0]:
                        continue
                    # UnRegister is only safe for an object still owned by
                    # GameObjectManager.  Objects already sent through an old
                    # partial-destroy path are intentionally left untouched.
                    if obj not in manager_objects:
                        continue
                    item = int(pm.read_int(obj + 0x164) or 0)
                    vtable = int(pm.read_int(obj) or 0)
                    # The object itself carries the authoritative identifier.
                    # Reading only Item+0x64 misses long-string objects such
                    # as alien capsules and service buildings, making them
                    # appear in the map while silently skipping deletion.
                    entity_id = self._read_world_object_id(obj)
                    if entity_id not in self.SPECIAL_ENTITY_REMOVABLE_IDS:
                        continue
                    x, y = float(pm.read_float(obj + self.WORLD_OBJECT_X_OFF)), float(pm.read_float(obj + self.WORLD_OBJECT_Y_OFF))
                    anchor = (int(math.floor(x / cell_width)), int(math.floor(y / cell_height)))
                    # A multi-cell entity may be selected by any one of its
                    # occupied cells rather than only by its anchor.  Ask the
                    # same native occupancy probe used by the map renderer;
                    # if it is unavailable, retain the conservative anchor
                    # rule instead of guessing a rectangle.
                    selected_hit = anchor in selected
                    if not selected_hit:
                        try:
                            occupied = self._query_world_object_occupancy(
                                obj, max(0, min(map_width - 1, anchor[0])),
                                max(0, min(map_height - 1, anchor[1])),
                                float(pm.read_float(obj + self.WORLD_OBJECT_WIDTH_OFF)),
                                float(pm.read_float(obj + self.WORLD_OBJECT_HEIGHT_OFF)),
                                cell_width, cell_height, map_width, map_height)
                            if occupied:
                                selected_hit = any(
                                    (int(cell.get("col")), int(cell.get("row"))) in selected
                                    for cell in occupied if isinstance(cell, dict))
                        except Exception:
                            selected_hit = anchor in selected
                    if not selected_hit or not (_is_plausible_32bit_pointer(item)
                                                and _is_plausible_32bit_pointer(vtable)):
                        continue
                    targets.append({"address": obj, "item": item, "vtable": vtable,
                                    "id": entity_id, "col": anchor[0], "row": anchor[1]})
                except (AttributeError, OSError, TypeError, ValueError, OverflowError, struct.error):
                    continue
            if not targets:
                return {"ok": True, "state": self.STATUS_EMPTY, "deleted_count": 0,
                        "entities": [], "message": "选区内没有可删除的特殊实体"}
            deleted, failures = [], []
            with self._wave_portal_lock, self._memory_write_lock:
                controller, error = self._ensure_wave_portal_controller()
                if not controller:
                    return {"ok": False, "state": self.STATUS_FAILED, "error": error}
                data = int(controller["data"])
                request = data + self.SPECIAL_ENTITY_DELETE_QUEUE_REQUEST_OFF
                target_addr = data + self.SPECIAL_ENTITY_DELETE_QUEUE_TARGET_OFF
                item_addr = data + self.SPECIAL_ENTITY_DELETE_QUEUE_ITEM_OFF
                vtable_addr = data + self.SPECIAL_ENTITY_DELETE_QUEUE_VTABLE_OFF
                result_addr = data + self.SPECIAL_ENTITY_DELETE_QUEUE_RESULT_OFF
                status_addr = data + self.SPECIAL_ENTITY_DELETE_QUEUE_STATUS_OFF
                for target in targets:
                    if int(pm.read_int(request) or 0):
                        failures.append({**target, "error": "上一条实体删除请求仍在等待处理"})
                        continue
                    pm.write_int(result_addr, 0); pm.write_int(status_addr, -1)
                    pm.write_int(target_addr, int(target["address"]))
                    pm.write_int(item_addr, int(target["item"]))
                    pm.write_int(vtable_addr, int(target["vtable"]))
                    pm.write_int(request, 1)
                    deadline = time.monotonic() + 2.5
                    while time.monotonic() < deadline and int(pm.read_int(status_addr) or -1) == -1:
                        time.sleep(0.03)
                    status = int(pm.read_int(status_addr) or -1)
                    if status == 1 and int(pm.read_int(result_addr) or 0) == int(target["address"]):
                        # A successful native return alone is insufficient:
                        # V33 returned success after UnRegister but still left
                        # the pointer in World. Re-read both owner lists.
                        world_now = set(struct.unpack(
                            "<%dI" % ((int(pm.read_int(world + self.WORLD_OBJECTS_END_OFF) or 0) -
                                        int(pm.read_int(world + self.WORLD_OBJECTS_BEGIN_OFF) or 0)) // 4),
                            pm.read_bytes(int(pm.read_int(world + self.WORLD_OBJECTS_BEGIN_OFF) or 0),
                                          int(pm.read_int(world + self.WORLD_OBJECTS_END_OFF) or 0) -
                                          int(pm.read_int(world + self.WORLD_OBJECTS_BEGIN_OFF) or 0))))
                        manager_now = set(struct.unpack(
                            "<%dI" % ((int(pm.read_int(manager + self.V1_GAME_OBJECT_MANAGER_OBJECTS_END_OFF) or 0) -
                                        int(pm.read_int(manager + self.V1_GAME_OBJECT_MANAGER_OBJECTS_BEGIN_OFF) or 0)) // 4),
                            pm.read_bytes(int(pm.read_int(manager + self.V1_GAME_OBJECT_MANAGER_OBJECTS_BEGIN_OFF) or 0),
                                          int(pm.read_int(manager + self.V1_GAME_OBJECT_MANAGER_OBJECTS_END_OFF) or 0) -
                                          int(pm.read_int(manager + self.V1_GAME_OBJECT_MANAGER_OBJECTS_BEGIN_OFF) or 0))))
                        if int(target["address"]) not in world_now and int(target["address"]) not in manager_now:
                            deleted.append(target)
                        else:
                            failures.append({**target, "error": "对象仍残留在游戏容器中，未标记为完成"})
                    else:
                        detail = {2: "目标对象已失效", 3: "对象类型校验未通过"}.get(status, "游戏未确认实体销毁")
                        failures.append({**target, "error": detail})
            return {"ok": bool(deleted) and not failures,
                    "state": self.STATUS_VERIFIED if deleted and not failures else self.STATUS_FAILED,
                    "deleted_count": len(deleted), "entities": deleted,
                    "failed": failures,
                    "message": "已提交 %d 个特殊实体的游戏原生销毁" % len(deleted) if deleted else ""}
        except (AttributeError, OSError, TypeError, ValueError, OverflowError, struct.error) as exc:
            return {"ok": False, "state": self.STATUS_FAILED,
                    "error": "读取或提交特殊实体删除请求失败：%s" % exc}

    def restore_current_structure_test_annotations(self):
        """Recover the exact structures generated in the 2026-08-27 test map.

        This is deliberately an explicit, one-map user action rather than an
        automatic guess.  It restores labels for the completed test placements
        that predate persistent annotation storage.
        """
        return {"ok": False, "state": self.STATUS_UNSUPPORTED,
                "error": "已停用测试结构标注恢复：当前结构面板只接受游戏原生 Room 容器数据"}

    def place_structure(self, filename="t.map", col=0, row=0,
                        mirror_x=1.0, mirror_y=1.0, force=False):
        """Queue one whitelisted .map through the game's native putRoom path."""
        if not connected or not pm:
            return {"ok": False, "state": self.STATUS_DISCONNECTED,
                    "error": "请先连接并进入已加载的存档"}
        filename = str(filename or "").strip()
        descriptor = self._structure_descriptor(filename)
        if (not filename or not filename.isascii()
                or len(filename.encode("ascii")) > 0x200):
            return {"ok": False, "state": self.STATUS_UNSUPPORTED,
                    "error": "结构文件名必须是 ASCII，且长度不超过 512 字节"}
        try:
            col, row = int(col), int(row)
            mirror_x, mirror_y = float(mirror_x), float(mirror_y)
            force = bool(force)
        except (TypeError, ValueError, OverflowError):
            return {"ok": False, "state": self.STATUS_FAILED, "error": "结构参数无效"}
        if (not math.isfinite(mirror_x) or not math.isfinite(mirror_y) or
                mirror_x not in (-1.0, 1.0) or mirror_y not in (-1.0, 1.0)):
            return {"ok": False, "state": self.STATUS_FAILED,
                    "error": "镜像参数只能为 1 或 -1"}
        meta = self.map_metadata()
        if not meta.get("ok"):
            return {"ok": False, "state": meta.get("state", self.STATUS_FAILED),
                    "error": meta.get("error") or "无法读取当前地图范围"}
        width, height = int(meta.get("width", 0)), int(meta.get("height", 0))
        if not (0 <= col < width and 0 <= row < height):
            return {"ok": False, "state": self.STATUS_FAILED,
                    "error": "结构坐标超出当前地图范围（列 %d，行 %d）" % (col, row)}
        filename = os.path.basename(filename)
        path = os.path.join(GAME_ROOT, "Levels", filename)
        if not os.path.isfile(path):
            return {"ok": False, "state": self.STATUS_FAILED,
                    "error": "结构文件不存在：%s" % filename}
        # Capture the exact source extent before dispatching.  The native
        # result flag alone only says that putRoom returned.  The before/after
        # tile diff is also saved as the overlay silhouette, so later terrain
        # changes cannot inflate a structure marker into a rectangle.
        descriptor = self._structure_descriptor(filename)
        display_width = int(descriptor.get("width") or 1)
        display_height = int(descriptor.get("height") or 1)
        probe = {"r0": row, "c0": col,
                 "r1": min(height - 1, row + display_height - 1),
                 "c1": min(width - 1, col + display_width - 1)}
        before_probe = None
        try:
            before_data = self.map_read_regions([probe])
            if before_data.get("ok") and before_data.get("regions"):
                before_probe = dict(before_data["regions"][0])
        except Exception:
            before_probe = None
        with self._wave_portal_lock, self._memory_write_lock:
            generation, pm_obj = self._runtime_lock_worker_context()
            if not self._runtime_session_current(generation, pm_obj):
                return {"ok": False, "state": self.STATUS_DISCONNECTED,
                        "error": "游戏连接已失效，请重新连接后再试"}
            controller, error = self._ensure_wave_portal_controller()
            if not controller:
                return {"ok": False, "state": self.STATUS_FAILED, "error": error}
            data = int(controller["data"])
            request = data + self.STRUCTURE_QUEUE_REQUEST_OFF
            result_addr = data + self.STRUCTURE_QUEUE_RESULT_OFF
            status_addr = data + self.STRUCTURE_QUEUE_STATUS_OFF
            if int(pm.read_int(request) or 0):
                return {"ok": False, "state": self.STATUS_FAILED,
                        "error": "上一条结构请求仍在等待游戏处理"}
            payload = filename.encode("ascii")
            name_addr = data + self.STRUCTURE_QUEUE_NAME_OFF
            if len(payload) <= 15:
                # MSVC small-string optimisation: inline bytes + size/cap.
                pm.write_bytes(name_addr, payload + b"\x00" * (16 - len(payload)), 16)
                pm.write_int(name_addr + 0x10, len(payload))
                pm.write_int(name_addr + 0x14, 15)
            else:
                # Long names are staged as plain bytes. The injected game
                # thread allocates the final std::string buffer with the
                # game's allocator immediately before putRoom, so no Python
                # or VirtualAlloc pointer is ever handed to C++ for cleanup.
                source_addr = data + self.STRUCTURE_QUEUE_STRING_BUFFER_OFF
                pm.write_bytes(source_addr, payload + b"\x00", len(payload) + 1)
                pm.write_bytes(name_addr, b"\x00" * 24, 24)
            pm.write_int(data + self.STRUCTURE_QUEUE_LENGTH_OFF, len(payload))
            pm.write_float(data + self.STRUCTURE_QUEUE_X_OFF, float(col))
            pm.write_float(data + self.STRUCTURE_QUEUE_Y_OFF, float(row))
            pm.write_float(data + self.STRUCTURE_QUEUE_MIRROR_X_OFF, mirror_x)
            pm.write_float(data + self.STRUCTURE_QUEUE_MIRROR_Y_OFF, mirror_y)
            pm.write_int(data + self.STRUCTURE_QUEUE_FORCE_OFF, 1 if force else 0)
            pm.write_int(result_addr, -1)
            pm.write_int(status_addr, -1)
            pm.write_int(request, 1)
            deadline = time.monotonic() + 3.0
            while time.monotonic() < deadline:
                if not self._runtime_session_current(generation, pm_obj):
                    return {"ok": False, "state": self.STATUS_DISCONNECTED,
                            "error": "等待结构生成时游戏连接已失效"}
                state = int(pm.read_int(status_addr) or -1)
                if state != -1:
                    native = int(pm.read_int(result_addr) or 0)
                    accepted = state == 1 and bool(native)
                    readback_ok = None
                    readback_mask = []
                    if accepted and before_probe is not None:
                        try:
                            self.map_metadata()
                            after_data = self.map_read_regions([probe])
                            if after_data.get("ok") and after_data.get("regions"):
                                after_probe = dict(after_data["regions"][0])
                                readback_mask = self._structure_readback_mask(
                                    before_probe, after_probe,
                                    int(before_probe.get("cols") or display_width),
                                    int(before_probe.get("rows") or display_height))
                                readback_ok = bool(readback_mask)
                        except Exception:
                            readback_ok = False
                    confirmed = accepted and (readback_ok is not False)
                    if confirmed:
                        record = {
                            "file": filename, "col": col, "row": row,
                            "mirror_x": mirror_x, "mirror_y": mirror_y,
                            "force": force, "result": native,
                            "readback_ok": readback_ok,
                            "width": descriptor["width"],
                            "height": descriptor["height"],
                            "category": descriptor["category"],
                            # This is retained only while the current game
                            # connection lives.  It is evidence from the
                            # successful native putRoom call, not a saved-map
                            # annotation, and therefore cannot leak to a
                            # different save after reconnect.
                            "source": "native-runtime-placement",
                            "confidence": self.STATUS_VERIFIED,
                            "timestamp": int(time.time()),
                        }
                        if readback_mask:
                            # The probe can be clipped at the world edge. Pad
                            # the sampled rows back to the source extent so
                            # the persistent record remains rectangular while
                            # retaining only cells proven to have changed.
                            padded = []
                            for mask_row in readback_mask[:display_height]:
                                padded.append(str(mask_row)[:display_width].ljust(display_width, "0"))
                            while len(padded) < display_height:
                                padded.append("0" * display_width)
                            record["mask"] = padded
                            record["mask_source"] = "placement-readback"
                        with self._structure_history_lock:
                            self._structure_runtime_history = [item for item in self._structure_runtime_history
                                                               if not (int(item.get("row", -1)) == row
                                                                       and int(item.get("col", -1)) == col)]
                            self._structure_runtime_history.append(record)
                        map_key = self._structure_map_key()
                        self._save_map_structures(
                            map_key,
                            self._saved_map_structures(map_key) + [record],
                        )
                    return {"ok": confirmed,
                            "state": self.STATUS_VERIFIED if confirmed else self.STATUS_FAILED,
                            "file": filename, "col": col, "row": row, "result": native,
                            "readback_ok": readback_ok,
                            "error": ("游戏未接受结构放置请求" if not accepted else
                                      "游戏已接受请求，但目标区域未读到方块变化" if readback_ok is False else "")}
                time.sleep(0.03)
            return {"ok": False, "state": self.STATUS_STALE,
                    "error": "结构请求尚未由游戏主线程确认；未继续重试"}

    def activate_structure_portal(self, object_addr=None, mode="all"):
        """Register a structure-generated LevelPortal through native calls.

        ``putRoom("portal.map")`` only materialises the room and its five
        block records.  This method queues the missing LevelPortal::NewPart
        calls on the game's update thread, followed by AllowAllParts, so the
        result can enter the same component/update chain as a native portal.
        ``mode="probe"`` intentionally registers only block1 for a safe
        single-step test; ``mode="all"`` completes all five parts.
        """
        if not connected or pm is None:
            return {"ok": False, "state": self.STATUS_DISCONNECTED,
                    "error": "请先连接并进入已加载的存档"}
        mode = str(mode or "all").strip().lower()
        if mode not in ("probe", "all"):
            return {"ok": False, "error": "激活模式只能是 probe 或 all"}
        try:
            module_base = int(get_base())
            expected_vtable = module_base + self.V1_LEVEL_PORTAL_VTABLE_RVA
            if pm.read_int(module_base + self.V1_LEVEL_PORTAL_NEW_PART_RVA) == 0:
                return {"ok": False, "state": self.STATUS_UNSUPPORTED,
                        "error": "当前版本的传送门原生入口不可读"}
            if object_addr is None:
                scan = self.scan_map_world_objects(False)
                rows = scan.get("entities") or [] if isinstance(scan, dict) else []
                rows = [row for row in rows if str(row.get("id") or "").lower() == "portal"]
                object_addr = int(str(rows[0].get("address") or "0"), 0) if rows else 0
            else:
                object_addr = int(object_addr, 0) if isinstance(object_addr, str) else int(object_addr)
            if not _is_plausible_32bit_pointer(object_addr):
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "未找到可验证的主传送门对象"}
            if int(pm.read_int(object_addr) or 0) != expected_vtable:
                return {"ok": False, "state": self.STATUS_UNSUPPORTED,
                        "error": "目标对象不是当前版本的 LevelPortal"}
            begin = int(pm.read_int(object_addr + self.V1_LEVEL_PORTAL_PARTS_BEGIN_OFF) or 0)
            end = int(pm.read_int(object_addr + self.V1_LEVEL_PORTAL_PARTS_END_OFF) or 0)
            count = (end - begin) // 0x20 if begin and end >= begin and (end - begin) % 0x20 == 0 else 0
            if count != 5 or not _is_plausible_32bit_pointer(begin):
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "目标传送门的部件记录表不可读"}
            part_ids = []
            flags = []
            for index in range(count):
                rec = begin + index * 0x20
                part_id = int(pm.read_int(rec + 0x18) or 0)
                part_ids.append(part_id)
                flags.append(int(pm.read_bytes(rec + 0x1C, 1)[0]))
            if part_ids != [0x45, 0x46, 0x47, 0x48, 0x49]:
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "目标部件 ID 与已验证传送门布局不一致"}
            point_x = float(pm.read_float(object_addr + self.V1_LEVEL_PORTAL_WORLD_X_OFF))
            point_y = float(pm.read_float(object_addr + self.V1_LEVEL_PORTAL_WORLD_Y_OFF))
            if not (math.isfinite(point_x) and math.isfinite(point_y)):
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "传送门世界坐标不可读"}
        except (AttributeError, OSError, TypeError, ValueError, OverflowError, struct.error) as exc:
            return {"ok": False, "state": self.STATUS_STALE,
                    "error": "读取传送门对象失败：%s" % exc}

        with self._wave_portal_lock, self._memory_write_lock:
            controller, error = self._ensure_wave_portal_controller()
            if not controller:
                return {"ok": False, "state": self.STATUS_FAILED, "error": error}
            data = int(controller["data"])
            request = data + self.PORTAL_ACTIVATE_QUEUE_REQUEST_OFF
            target_addr = data + self.PORTAL_ACTIVATE_QUEUE_TARGET_OFF
            part_addr = data + self.PORTAL_ACTIVATE_QUEUE_PART_OFF
            op_addr = data + self.PORTAL_ACTIVATE_QUEUE_OPERATION_OFF
            px_addr = data + self.PORTAL_ACTIVATE_QUEUE_POINT_X_OFF
            py_addr = data + self.PORTAL_ACTIVATE_QUEUE_POINT_Y_OFF
            result_addr = data + self.PORTAL_ACTIVATE_QUEUE_RESULT_OFF
            status_addr = data + self.PORTAL_ACTIVATE_QUEUE_STATUS_OFF
            vtable_addr = data + self.PORTAL_ACTIVATE_QUEUE_VTABLE_OFF

            def submit(operation, part_id=0):
                if int(pm.read_int(request) or 0):
                    return False, "上一条传送门激活请求仍在等待处理"
                pm.write_int(target_addr, object_addr)
                pm.write_int(vtable_addr, expected_vtable)
                pm.write_int(part_addr, int(part_id))
                pm.write_int(op_addr, int(operation))
                pm.write_float(px_addr, point_x)
                pm.write_float(py_addr, point_y)
                pm.write_int(result_addr, 0)
                pm.write_int(status_addr, -1)
                pm.write_int(request, 1)
                deadline = time.monotonic() + 2.5
                while time.monotonic() < deadline:
                    state = int(pm.read_int(status_addr) or -1)
                    if state != -1:
                        if state == 1 and int(pm.read_int(result_addr) or 0) == 1:
                            return True, ""
                        detail = {2: "目标传送门对象已失效", 3: "目标类型或操作校验未通过"}.get(
                            state, "游戏未确认传送门激活")
                        return False, detail
                    time.sleep(0.03)
                return False, "游戏线程未在限定时间内确认传送门激活"

            requested_parts = [part_ids[0]] if mode == "probe" else [
                part_id for part_id, flag in zip(part_ids, flags) if flag == 0]
            completed = []
            for part_id in requested_parts:
                ok, detail = submit(self.PORTAL_ACTIVATE_OPERATION_NEW_PART, part_id)
                if not ok:
                    return {"ok": False, "state": self.STATUS_FAILED,
                            "object": "0x%08X" % object_addr,
                            "completed_parts": completed, "error": detail}
                completed.append(part_id)
            if mode == "all":
                ok, detail = submit(self.PORTAL_ACTIVATE_OPERATION_ALLOW_ALL)
                if not ok:
                    return {"ok": False, "state": self.STATUS_FAILED,
                            "object": "0x%08X" % object_addr,
                            "completed_parts": completed, "error": detail}
            try:
                final_flags = [int(pm.read_bytes(begin + i * 0x20 + 0x1C, 1)[0]) for i in range(5)]
                active_flag = int(pm.read_bytes(object_addr + self.V1_LEVEL_PORTAL_ACTIVE_FLAG_OFF, 1)[0])
                child_owner = int(pm.read_int(object_addr + 0x1DC) or 0)
            except Exception:
                final_flags, active_flag, child_owner = [], 0, 0
            verified = bool(mode == "probe" and final_flags and final_flags[0] == 1 or
                            mode == "all" and final_flags == [1, 1, 1, 1, 1] and active_flag == 1)
            return {"ok": verified, "state": self.STATUS_VERIFIED if verified else self.STATUS_FAILED,
                    "object": "0x%08X" % object_addr, "mode": mode,
                    "completed_parts": completed, "part_flags": final_flags,
                    "active_flag": active_flag, "child_owner": "0x%08X" % child_owner,
                    "error": "游戏调用已返回，但部件状态未完成读回" if not verified else ""}

    def inspect_current_portal_lookup(self):
        """Read which LevelPortal the game itself currently resolves.

        This is a diagnostic only.  It calls the zero-argument native portal
        lookup on the game thread and never changes a portal, its parts, or
        any World container.  It separates a missing registration from the
        game's lookup selecting another portal first.
        """
        if not connected or pm is None:
            return {"ok": False, "state": self.STATUS_DISCONNECTED,
                    "error": "请先连接并进入已加载的存档"}
        try:
            module_base = int(get_base())
            expected_vtable = module_base + self.V1_LEVEL_PORTAL_VTABLE_RVA
            entry = module_base + self.V1_LEVEL_PORTAL_GET_CURRENT_RVA
            prefix = pm.read_bytes(entry, 6)
            if not prefix or prefix == b"\x00" * len(prefix):
                return {"ok": False, "state": self.STATUS_UNSUPPORTED,
                        "error": "当前版本的传送门查找入口不可读"}
        except (AttributeError, OSError, TypeError, ValueError, OverflowError) as exc:
            return {"ok": False, "state": self.STATUS_STALE,
                    "error": "无法验证传送门查找入口：%s" % exc}

        with self._wave_portal_lock, self._memory_write_lock:
            controller, error = self._ensure_wave_portal_controller()
            if not controller:
                return {"ok": False, "state": self.STATUS_FAILED, "error": error}
            data = int(controller["data"])
            request = data + self.PORTAL_LOOKUP_QUEUE_REQUEST_OFF
            result_addr = data + self.PORTAL_LOOKUP_QUEUE_RESULT_OFF
            status_addr = data + self.PORTAL_LOOKUP_QUEUE_STATUS_OFF
            vtable_addr = data + self.PORTAL_LOOKUP_QUEUE_VTABLE_OFF
            try:
                if int(pm.read_int(request) or 0):
                    return {"ok": False, "state": self.STATUS_STALE,
                            "error": "上一条传送门查找请求仍在等待处理"}
                pm.write_int(vtable_addr, expected_vtable)
                pm.write_int(result_addr, 0)
                pm.write_int(status_addr, -1)
                pm.write_int(request, 1)
                deadline = time.monotonic() + 2.5
                while time.monotonic() < deadline:
                    status = int(pm.read_int(status_addr) or -1)
                    if status != -1:
                        raw = int(pm.read_int(result_addr) or 0)
                        if status != 1:
                            details = {2: "游戏当前没有可解析的主传送门",
                                       3: "查找结果不是已验证的 LevelPortal"}
                            return {"ok": False, "state": self.STATUS_STALE,
                                    "lookup_result": "0x%08X" % raw if raw else "",
                                    "error": details.get(status, "游戏未确认传送门查找结果")}
                        if not _is_plausible_32bit_pointer(raw):
                            return {"ok": False, "state": self.STATUS_STALE,
                                    "error": "游戏返回了不可用的传送门地址"}
                        x = float(pm.read_float(raw + self.V1_LEVEL_PORTAL_WORLD_X_OFF))
                        y = float(pm.read_float(raw + self.V1_LEVEL_PORTAL_WORLD_Y_OFF))
                        active = int(pm.read_bytes(raw + self.V1_LEVEL_PORTAL_ACTIVE_FLAG_OFF, 1)[0])
                        return {"ok": True, "state": self.STATUS_VERIFIED,
                                "portal": "0x%08X" % raw,
                                "world_x": x, "world_y": y,
                                "active_flag": active}
                    time.sleep(0.03)
            except (AttributeError, OSError, TypeError, ValueError, OverflowError, struct.error) as exc:
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "读取传送门查找结果失败：%s" % exc}
            return {"ok": False, "state": self.STATUS_STALE,
                    "error": "游戏主线程未在限定时间内确认传送门查找"}

    def _clear_structure_tiles(self, record):
        """Clear only proven cells through the game's native CrashBlock path.

        The old implementation wrote the 0x20-byte map cell directly.  That
        bypassed drops, texture/entity cleanup and the game's own tile
        bookkeeping.  Every occupied cell now receives at most two native
        requests (front, then inner layer); an unknown or stale cell is
        skipped and reported instead of falling back to a rectangle.
        """
        resolved = self._map_resolve()
        if not resolved:
            return {"ok": False, "error": "当前地图不可读"}
        data, width, height, _world_w, _world_h = resolved
        col, row = int(record.get("col", -1)), int(record.get("row", -1))
        sw, sh = int(record.get("width", 0)), int(record.get("height", 0))
        if col < 0 or row < 0 or sw < 1 or sh < 1:
            return {"ok": False, "error": "结构范围无效"}
        cells = self._structure_mask_cells(record, width, height)
        if not cells:
            return {"ok": True, "cells": 0, "exact_mask": False,
                    "message": "未保存结构实际占用掩码；已跳过地图方块清理，避免按长方形误删地形"}
        cleared, skipped = 0, []
        for r, c in cells:
            # A cell may contain both a front and inner value.  CrashBlock
            # resolves the current layer when block=-1, so call it twice and
            # stop as soon as the complete tile is empty.
            cell_ok = True
            for _ in range(2):
                try:
                    raw = pm.read_bytes(int(data) + r * self._map_row_stride(width) + c * self.MAP_COL_W, 4)
                    if not raw or len(raw) < 4:
                        cell_ok = False
                        break
                    front, ground = struct.unpack_from("<HH", raw, 0)
                    if front == 0xFFFF and ground == 0xFFFF:
                        break
                    result = self.delete_structure_cell_native(c, r)
                    if not result.get("ok"):
                        # An already-empty layer is harmless; all other
                        # failures make the composite operation incomplete.
                        after = result.get("after") or {}
                        if int(after.get("front", front)) == 0xFFFF and int(after.get("ground", ground)) == 0xFFFF:
                            break
                        cell_ok = False
                        break
                except (AttributeError, OSError, TypeError, ValueError, OverflowError):
                    cell_ok = False
                    break
            if cell_ok:
                cleared += 1
            else:
                skipped.append({"col": c, "row": r})
        return {"ok": not skipped, "cells": len(cells), "cleared": cleared,
                "skipped": skipped, "exact_mask": True,
                "message": ("已通过游戏原生流程清理 %d/%d 格" % (cleared, len(cells))
                             if not skipped else
                             "已通过游戏原生流程清理 %d/%d 格，剩余格子未强制清空" % (cleared, len(cells)))}

    def _structure_service_entity_cell(self, record):
        """Find a sand-temple service entity on a proven structure cell.

        The room anchor is only the upper-left source coordinate.  It can be
        empty for irregular rooms, so using it for World entity lookup makes
        the native texture deletion silently miss the actual service object.
        """
        try:
            resolved = self._map_resolve()
            if not resolved:
                return None
            _data, map_width, map_height, _world_w, _world_h = resolved
            cells = self._structure_mask_cells(record, map_width, map_height)
            allowed = set(cells) if cells else None
            col, row = int(record.get("col")), int(record.get("row"))
            width, height = int(record.get("width")), int(record.get("height"))
            module_base = int(get_base())
            world = int(pm.read_int(module_base + ITEM_BASE_OFFSET) or 0)
            begin = int(pm.read_int(world + 0x194) or 0) if world else 0
            end = int(pm.read_int(world + 0x198) or 0) if world else 0
            if not (begin and end >= begin and (end - begin) % 4 == 0 and end - begin <= 4 * 20000):
                return None
            for cursor in range(begin, end, 4):
                obj = int(pm.read_int(cursor) or 0)
                if not _is_plausible_32bit_pointer(obj):
                    continue
                if int(pm.read_int(obj) or 0) != module_base + self.V1_SERVICE_SAND_TEMPLE_ITEM_VTABLE_RVA:
                    continue
                x, y = float(pm.read_float(obj + 0x38)), float(pm.read_float(obj + 0x3C))
                sw, sh = float(pm.read_float(obj + 0x40)), float(pm.read_float(obj + 0x44))
                left, top = int(math.floor(x / 60.0)), int(math.floor(y / 60.0))
                right, bottom = int(math.ceil((x + sw) / 60.0)), int(math.ceil((y + sh) / 60.0))
                left, top = max(left, col), max(top, row)
                right, bottom = min(right, col + width), min(bottom, row + height)
                for candidate_row in range(top, bottom):
                    for candidate_col in range(left, right):
                        if allowed is None or (candidate_row, candidate_col) in allowed:
                            return {"col": candidate_col, "row": candidate_row}
        except (AttributeError, OSError, TypeError, ValueError, OverflowError):
            return None
        return None

    def delete_structure_complete(self, record_index=None, col=None, row=None):
        """Delete native structure object/room first, then its map cells."""
        listing = self.scan_map_structures()
        records = listing.get("structures") if listing.get("ok") else None
        if not isinstance(records, list):
            return listing
        target = None
        try:
            if record_index is not None and 0 <= int(record_index) < len(records):
                target = records[int(record_index)]
            elif col is not None and row is not None:
                c, r = int(col), int(row)
                # Prefer a proven occupied cell when a readback mask exists.
                # Only fall back to the rectangular header for the explicit
                # list-row delete button, where the caller supplies the room
                # anchor rather than a selection hit.
                target = None
                for candidate in records:
                    try:
                        mask = candidate.get("mask")
                        mask_row = int(candidate.get("mask_origin_row", candidate.get("row", 0)))
                        mask_col = int(candidate.get("mask_origin_col", candidate.get("col", 0)))
                        rr, cc = r - mask_row, c - mask_col
                        mask_height = int(candidate.get("mask_height", candidate.get("height", 0)))
                        mask_width = int(candidate.get("mask_width", candidate.get("width", 0)))
                        if (isinstance(mask, list) and len(mask) == mask_height
                                and 0 <= rr < mask_height and 0 <= cc < mask_width
                                and len(str(mask[rr])) == mask_width
                                and str(mask[rr])[cc] == "1"):
                            target = candidate
                            break
                    except (AttributeError, TypeError, ValueError, IndexError):
                        continue
                # A native container rectangle is only a locator hint.  It
                # must never select a structure for destructive work when the
                # clicked cell is outside the proven occupied mask.
        except (TypeError, ValueError, KeyError):
            target = None
        if not target:
            return {"ok": False, "state": self.STATUS_EMPTY, "error": "未找到可删除的结构"}
        resolved = self._map_resolve()
        exact_cells = self._structure_mask_cells(target, resolved[1], resolved[2]) if resolved else []
        if not exact_cells:
            return {"ok": False, "state": self.STATUS_UNVERIFIED,
                    "structure": target,
                    "error": "该结构只有原生容器范围，尚未取得精确占用掩码；已拒绝删除，避免误删矩形外地形"}
        # A service entity is often offset from the room anchor.  Find a cell
        # actually covered by it, then call the original verified primitive.
        # The public primitive's standalone safety policy is intentionally
        # bypassed only inside this already policy-checked composite workflow.
        entity_cell = self._structure_service_entity_cell(target)
        native = {"ok": False, "state": self.STATUS_EMPTY,
                  "error": "结构内未找到沙漠神庙服务贴图"}
        if entity_cell:
            entity_fn = self.delete_sand_temple_entity_native
            while hasattr(entity_fn, "__wrapped__"):
                entity_fn = entity_fn.__wrapped__
            native = entity_fn(self, col=entity_cell["col"], row=entity_cell["row"])
        # This composite endpoint is itself policy-checked.  Call the room
        # primitive's implementation directly so an experimental wrapper
        # cannot turn the already-confirmed complete workflow into a no-op.
        room_fn = self.delete_structure_native
        while hasattr(room_fn, "__wrapped__"):
            room_fn = room_fn.__wrapped__
        try:
            native_slot = int(target.get("native_record_index", -1))
        except (AttributeError, TypeError, ValueError, OverflowError):
            native_slot = -1
        # Only a live UnderRoom record may enter RemoveHiddenRoom.  A saved
        # placement can remain visible after the game's room container has
        # naturally discarded it; calling by its old coordinates is a false
        # failure, not an actionable native delete.
        room = ({"ok": False, "state": self.STATUS_EMPTY,
                 "error": "该记录不在当前游戏原生 Room 容器中"}
                if native_slot < 0 else room_fn(self, record_index=native_slot))
        # Never fall back to direct tile clearing when the game did not first
        # acknowledge removal of the owning Room record.  ``exact_cells`` is
        # guaranteed above, so using it as part of this guard made the old
        # condition unreachable: a failed native delete could still erase the
        # room's visible tiles and leave its entity/collision owner behind.
        if not bool(room.get("ok")):
            detail = room.get("error") or "游戏未确认原生结构删除"
            return {"ok": False, "state": self.STATUS_FAILED, "structure": target,
                    "native": native, "room": room,
                    "error": "原生结构记录未删除，已停止清理方块和材质：%s" % detail}
        # A sand-temple service entity is part of the same structure.  Once a
        # matching entity was found, it too must be removed before touching
        # the map cells; otherwise the operation would again be only partial.
        if entity_cell and not bool(native.get("ok")):
            detail = native.get("error") or "游戏未确认服务贴图实体删除"
            return {"ok": False, "state": self.STATUS_FAILED, "structure": target,
                    "native": native, "room": room,
                    "error": "关联贴图实体未删除，已停止清理方块和材质：%s" % detail}
        tiles = self._clear_structure_tiles(target)
        if not bool(tiles.get("ok")):
            # Keep the record visible when any proven cell could not be
            # confirmed by the native path.  The caller can retry after the
            # game finishes its current tick; we never pretend a partial
            # deletion is complete.
            return {"ok": False, "state": self.STATUS_FAILED,
                    "structure": target, "native": native, "room": room,
                    "tiles": tiles,
                    "error": tiles.get("message") or "部分结构格未完成原生删除"}
        map_key = self._structure_map_key()
        remain = [x for x in self._saved_map_structures(map_key)
                  if not (int(x.get("col", -1)) == int(target["col"]) and int(x.get("row", -1)) == int(target["row"]))]
        self._save_map_structures(map_key, remain)
        with self._structure_history_lock:
            self._structure_runtime_history = [x for x in self._structure_runtime_history
                                               if not (int(x.get("col", -1)) == int(target["col"]) and int(x.get("row", -1)) == int(target["row"]))]
        if tiles.get("exact_mask"):
            message = ("已提交原生结构删除，并按实际占用清除 %d 格" % int(tiles.get("cells") or 0)
                       if bool(room.get("ok")) or bool(native.get("ok")) else
                       "该记录已不在原生 Room 容器中；已按保存的实际占用清除 %d 格" % int(tiles.get("cells") or 0))
        else:
            message = "已提交原生结构删除；未保存实际占用掩码，地图方块未清除以避免误删"
        return {"ok": bool(tiles.get("ok")), "state": self.STATUS_VERIFIED if tiles.get("ok") else self.STATUS_FAILED,
                "structure": target, "native": native, "room": room, "tiles": tiles,
                "message": message if tiles.get("ok") else tiles.get("error")}

    def delete_structure_cell_native(self, col, row, block_id=None):
        """Experimental one-cell native destruction probe.

        This endpoint is intentionally not wired to the UI yet.  It exists so
        the next live test can exercise the game's own CrashBlock path from
        the injected update-thread dispatcher and compare the complete tile
        readback before exposing structure-wide deletion.
        """
        if not connected or not pm:
            return {"ok": False, "state": self.STATUS_DISCONNECTED,
                    "error": "请先连接并进入已加载的存档"}
        try:
            col, row = int(col), int(row)
        except (TypeError, ValueError, OverflowError):
            return {"ok": False, "state": self.STATUS_FAILED, "error": "列和行必须是整数"}
        resolved = self._map_resolve()
        if not resolved:
            return {"ok": False, "state": self.STATUS_STALE, "error": "当前地图不可读"}
        map_data, width, height, _world_w, _world_h = resolved
        if not (0 <= col < int(width) and 0 <= row < int(height)):
            return {"ok": False, "state": self.STATUS_FAILED,
                    "error": "坐标超出地图范围（列 %d，行 %d）" % (col, row)}
        cell = int(map_data) + row * int(width) * self.MAP_COL_W + col * self.MAP_COL_W
        try:
            # Pymem.read_int is DWORD-only in the bundled runtime.  Map tile
            # layers are uint16 values, so decode the two bytes explicitly.
            cell_bytes = pm.read_bytes(cell, 4)
            if not cell_bytes or len(cell_bytes) < 4:
                raise RuntimeError("地图单元读取返回空数据")
            front, ground = struct.unpack_from("<HH", cell_bytes, 0)
        except Exception as exc:
            return {"ok": False, "state": self.STATUS_STALE, "error": "目标格读取失败：%s" % exc}
        if front == 0xFFFF and ground == 0xFFFF:
            return {"ok": False, "state": self.STATUS_EMPTY,
                    "error": "目标格为空，拒绝调用原生破坏流程"}
        # 1388 is the game's service_block marker.  It belongs to a native
        # room/structure record and is intentionally ignored by CrashBlock;
        # calling the mining primitive here only returns a false-positive
        # status while leaving the marker and its runtime owner intact.
        if front == 1388 or ground == 1388:
            return {"ok": False, "state": self.STATUS_UNVERIFIED,
                    "col": col, "row": row,
                    "error": "目标格是 service_block 结构标记，需通过原生结构容器销毁，不能按方块挖除"}
        try:
            # The native mining callers pass -1 here, which means "resolve
            # the current tile".  Passing the tile ID itself makes
            # CrashBlock accept the request yet skip the normal destruction
            # branch for structure/background cells.
            requested_block = int(block_id) if block_id is not None else -1
        except (TypeError, ValueError, OverflowError):
            requested_block = front if front != 0xFFFF else ground
        with self._wave_portal_lock, self._memory_write_lock:
            generation, pm_obj = self._runtime_lock_worker_context()
            if not self._runtime_session_current(generation, pm_obj):
                return {"ok": False, "state": self.STATUS_DISCONNECTED, "error": "游戏连接已失效"}
            controller, error = self._ensure_wave_portal_controller()
            if not controller:
                return {"ok": False, "state": self.STATUS_FAILED, "error": error}
            data = int(controller["data"])
            request = data + self.STRUCTURE_DELETE_QUEUE_REQUEST_OFF
            result_addr = data + self.STRUCTURE_DELETE_QUEUE_RESULT_OFF
            status_addr = data + self.STRUCTURE_DELETE_QUEUE_STATUS_OFF
            if int(pm.read_int(request) or 0):
                return {"ok": False, "state": self.STATUS_FAILED, "error": "上一条结构删除请求仍在等待处理"}
            pm.write_int(data + self.STRUCTURE_DELETE_QUEUE_X_OFF, col)
            pm.write_int(data + self.STRUCTURE_DELETE_QUEUE_Y_OFF, row)
            pm.write_int(data + self.STRUCTURE_DELETE_QUEUE_BLOCK_OFF, requested_block)
            for off in (self.STRUCTURE_DELETE_QUEUE_ARG14_OFF,
                        self.STRUCTURE_DELETE_QUEUE_ARG18_OFF,
                        self.STRUCTURE_DELETE_QUEUE_ARG1C_OFF,
                        self.STRUCTURE_DELETE_QUEUE_ARG20_OFF,
                        self.STRUCTURE_DELETE_QUEUE_ARG24_OFF):
                pm.write_int(data + off, 0)
            # CrashBlock's ninth argument is a byte flag.  Native mining and
            # Pandora cleanup calls set it to 1; keep the exact ABI value.
            pm.write_int(data + self.STRUCTURE_DELETE_QUEUE_ARG28_OFF, 1)
            pm.write_int(result_addr, -1)
            pm.write_int(status_addr, -1)
            pm.write_int(request, 1)
            deadline = time.monotonic() + 3.0
            while time.monotonic() < deadline:
                if not self._runtime_session_current(generation, pm_obj):
                    return {"ok": False, "state": self.STATUS_DISCONNECTED, "error": "等待原生删除时游戏连接已失效"}
                state = int(pm.read_int(status_addr) or -1)
                if state != -1:
                    native = int(pm.read_int(result_addr) or 0)
                    try:
                        cell_bytes = pm.read_bytes(cell, 4)
                        if not cell_bytes or len(cell_bytes) < 4:
                            raise RuntimeError("地图单元读回为空")
                        after_front, after_ground = struct.unpack_from("<HH", cell_bytes, 0)
                    except Exception:
                        after_front, after_ground = front, ground
                    changed = (after_front, after_ground) != (front, ground)
                    return {"ok": bool(state == 1 and native and changed),
                            "state": self.STATUS_VERIFIED if state == 1 and changed else self.STATUS_FAILED,
                            "col": col, "row": row, "before": {"front": front, "ground": ground},
                            "after": {"front": after_front, "ground": after_ground},
                            "native": native, "changed": changed,
                            "error": "原生流程已返回，但目标格未变化" if state == 1 and not changed else "游戏拒绝原生破坏请求" if state != 1 else ""}
                time.sleep(0.03)
            return {"ok": False, "state": self.STATUS_STALE, "error": "原生删除请求未在游戏主线程确认"}

    def delete_structure_native(self, record_index=None, col=None, row=None):
        """Run the game's native UnderRoom hide path for one room record.

        This is a diagnostic endpoint, intentionally separate from the old
        single-cell CrashBlock probe.  It never edits map tiles or vector
        pointers.  Success requires the selected record's native +0x30 byte
        to change from visible to hidden after the game-thread call.
        """
        if not connected or pm is None:
            return {"ok": False, "state": self.STATUS_DISCONNECTED,
                    "error": "请先连接并进入已加载的存档"}
        try:
            resolved = self._map_resolve()
            if not resolved:
                return {"ok": False, "state": self.STATUS_STALE, "error": "当前地图不可读"}
            _map_data, map_width, map_height, _world_width, _world_height = resolved
            world = int(pm.read_int(base_addr + ITEM_BASE_OFFSET) or 0)
            if not world:
                return {"ok": False, "state": self.STATUS_STALE, "error": "World 对象不可读"}
            begin = int(pm.read_int(world + 0x310) or 0)
            end = int(pm.read_int(world + 0x314) or 0)
            span = end - begin
            if begin <= 0 or end <= begin or span > 0x34 * 2048 or span % 0x34:
                return {"ok": False, "state": self.STATUS_STALE, "error": "原生房间容器不可读"}
            count = span // 0x34
            if record_index is not None:
                index = int(record_index)
                if not 0 <= index < count:
                    return {"ok": False, "state": self.STATUS_FAILED, "error": "结构记录序号超出范围"}
            else:
                if col is None or row is None:
                    return {"ok": False, "state": self.STATUS_FAILED, "error": "需要 record_index 或列/行坐标"}
                target_col, target_row = int(col), int(row)
                index = None
                for candidate in self._read_native_room_records():
                    left, top = int(candidate["col"]), int(candidate["row"])
                    right = left + int(candidate["width"])
                    bottom = top + int(candidate["height"])
                    if left <= target_col < right and top <= target_row < bottom:
                        index = int(candidate.get("record_index", -1))
                        break
                if index is None or index < 0:
                    return {"ok": False, "state": self.STATUS_EMPTY, "error": "目标坐标未匹配原生房间记录"}
            record_addr = begin + index * 0x34
            before_raw = pm.read_bytes(record_addr + 0x30, 1)
            before_flag = int(before_raw[0]) if before_raw else -1
            raw = pm.read_bytes(record_addr + 0x04, 16)
            if not raw or len(raw) < 16:
                return {"ok": False, "state": self.STATUS_STALE, "error": "目标房间记录读回失败"}
            anchor_col = int(round(struct.unpack_from("<f", raw, 0)[0]))
            anchor_row = int(round(struct.unpack_from("<f", raw, 4)[0]))
            if not (0 <= anchor_col < int(map_width) and 0 <= anchor_row < int(map_height)):
                return {"ok": False, "state": self.STATUS_FAILED, "error": "目标房间锚点超出地图范围"}
            with self._wave_portal_lock, self._memory_write_lock:
                generation, pm_obj = self._runtime_lock_worker_context()
                if not self._runtime_session_current(generation, pm_obj):
                    return {"ok": False, "state": self.STATUS_DISCONNECTED, "error": "游戏连接已失效"}
                controller, error = self._ensure_wave_portal_controller()
                if not controller:
                    return {"ok": False, "state": self.STATUS_FAILED, "error": error}
                data = int(controller["data"])
                request = data + self.STRUCTURE_ROOM_DELETE_QUEUE_REQUEST_OFF
                result_addr = data + self.STRUCTURE_ROOM_DELETE_QUEUE_RESULT_OFF
                status_addr = data + self.STRUCTURE_ROOM_DELETE_QUEUE_STATUS_OFF
                if int(pm.read_int(request) or 0):
                    return {"ok": False, "state": self.STATUS_FAILED, "error": "上一条原生结构请求仍在等待处理"}
                pm.write_int(data + self.STRUCTURE_ROOM_DELETE_QUEUE_POINT_OFF, anchor_col)
                pm.write_int(data + self.STRUCTURE_ROOM_DELETE_QUEUE_POINT_OFF + 4, anchor_row)
                pm.write_int(result_addr, -1)
                pm.write_int(status_addr, -1)
                pm.write_int(request, 1)
                deadline = time.monotonic() + 3.0
                while time.monotonic() < deadline:
                    if not self._runtime_session_current(generation, pm_obj):
                        return {"ok": False, "state": self.STATUS_DISCONNECTED, "error": "等待原生结构请求时游戏连接已失效"}
                    state = int(pm.read_int(status_addr) or -1)
                    if state != -1:
                        after_raw = pm.read_bytes(record_addr + 0x30, 1)
                        after_flag = int(after_raw[0]) if after_raw else -1
                        changed = before_flag == 0 and after_flag == 1
                        return {"ok": bool(state == 1 and changed),
                                "state": self.STATUS_VERIFIED if state == 1 and changed else self.STATUS_FAILED,
                                "record_index": index, "anchor": {"col": anchor_col, "row": anchor_row},
                                "before_flag": before_flag, "after_flag": after_flag,
                                "native": int(pm.read_int(result_addr) or 0), "changed": changed,
                                "complete": False,
                                "effect": "仅隐藏原生 Room 记录；未清理地图方块、碰撞、实体或存档对象",
                                "error": "原生调用已返回，但房间记录隐藏标志未变化" if not changed else ""}
                    time.sleep(0.03)
            return {"ok": False, "state": self.STATUS_STALE, "error": "原生结构请求未在游戏主线程确认"}
        except (AttributeError, OSError, struct.error, TypeError, ValueError, OverflowError) as exc:
            return {"ok": False, "state": self.STATUS_STALE, "error": "原生结构请求失败：%s" % exc}

    def delete_sand_temple_entity_native(self, col=None, row=None):
        """Queue a verified service ItemEntity destruction from one visible cell.

        This deliberately supports only the sand-temple Spine entity identified
        from ``service_sand_temple``.  It is not a generic entity delete API:
        every other entity type is rejected inside the game thread before any
        destruction call can occur.
        """
        if not connected or pm is None:
            return {"ok": False, "state": self.STATUS_DISCONNECTED,
                    "error": "请先连接并进入已加载的存档"}
        try:
            if col is None or row is None:
                return {"ok": False, "state": self.STATUS_FAILED,
                        "error": "需要结构内部任意一格的列、行坐标"}
            col, row = int(col), int(row)
            resolved = self._map_resolve()
            if not resolved:
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "当前地图不可读"}
            _map_data, width, height, _world_w, _world_h = resolved
            if not (0 <= col < int(width) and 0 <= row < int(height)):
                return {"ok": False, "state": self.STATUS_FAILED,
                        "error": "坐标超出地图范围（列 %d，行 %d）" % (col, row)}
            module_base = int(get_base())
            signatures = (
                (self.V1_WORLD_FIND_ENTITY_BY_CELL_RVA, self.V1_WORLD_FIND_ENTITY_BY_CELL_PREFIX),
                (self.V1_WORLD_FIND_ENTITY_BY_CELL_BOUNDS_RVA, self.V1_WORLD_FIND_ENTITY_BY_CELL_BOUNDS_PREFIX),
                (self.V1_GAME_OBJECT_DESTROY_RVA, self.V1_GAME_OBJECT_DESTROY_PREFIX),
            )
            for rva, prefix in signatures:
                if pm.read_bytes(module_base + int(rva), len(prefix)) != prefix:
                    return {"ok": False, "state": self.STATUS_STALE,
                            "error": "当前游戏版本的神庙服务对象删除入口未通过校验"}
            with self._wave_portal_lock, self._memory_write_lock:
                generation, pm_obj = self._runtime_lock_worker_context()
                if not self._runtime_session_current(generation, pm_obj):
                    return {"ok": False, "state": self.STATUS_DISCONNECTED,
                            "error": "游戏连接已失效"}
                controller, error = self._ensure_wave_portal_controller()
                if not controller:
                    return {"ok": False, "state": self.STATUS_FAILED, "error": error}
                data = int(controller["data"])
                request = data + self.STRUCTURE_TEMPLE_DELETE_QUEUE_REQUEST_OFF
                result_addr = data + self.STRUCTURE_TEMPLE_DELETE_QUEUE_RESULT_OFF
                status_addr = data + self.STRUCTURE_TEMPLE_DELETE_QUEUE_STATUS_OFF
                target_addr = data + self.STRUCTURE_TEMPLE_DELETE_QUEUE_TARGET_OFF
                if int(pm.read_int(request) or 0):
                    return {"ok": False, "state": self.STATUS_FAILED,
                            "error": "上一条神庙删除请求仍在等待处理"}
                # Resolve the target from World's authoritative entity vector,
                # then use the clicked map cell only for footprint matching.
                world = int(pm.read_int(module_base + ITEM_BASE_OFFSET) or 0)
                begin = int(pm.read_int(world + 0x194) or 0) if world else 0
                end = int(pm.read_int(world + 0x198) or 0) if world else 0
                target = 0
                if begin and end >= begin and (end - begin) % 4 == 0 and end - begin <= 4 * 20000:
                    for cursor in range(begin, end, 4):
                        obj = int(pm.read_int(cursor) or 0)
                        if not _is_plausible_32bit_pointer(obj):
                            continue
                        try:
                            if int(pm.read_int(obj)) != module_base + self.V1_SERVICE_SAND_TEMPLE_ITEM_VTABLE_RVA:
                                continue
                            x = float(pm.read_float(obj + 0x38)); y = float(pm.read_float(obj + 0x3C))
                            sw = float(pm.read_float(obj + 0x40)); sh = float(pm.read_float(obj + 0x44))
                            left = int(math.floor(x / 60.0)); top = int(math.floor(y / 60.0))
                            right = int(math.ceil((x + sw) / 60.0)); bottom = int(math.ceil((y + sh) / 60.0))
                            if left <= col < right and top <= row < bottom:
                                target = obj
                                break
                        except Exception:
                            continue
                if not target:
                    return {"ok": False, "state": self.STATUS_EMPTY,
                            "col": col, "row": row,
                            "error": "当前实体数组中未找到覆盖该坐标的沙漠神庙服务对象"}
                pm.write_int(target_addr, target)
                pm.write_int(data + self.STRUCTURE_TEMPLE_DELETE_QUEUE_POINT_OFF, col)
                pm.write_int(data + self.STRUCTURE_TEMPLE_DELETE_QUEUE_POINT_OFF + 4, row)
                pm.write_int(result_addr, 0)
                pm.write_int(status_addr, -1)
                pm.write_int(request, 1)
                deadline = time.monotonic() + 3.0
                while time.monotonic() < deadline:
                    if not self._runtime_session_current(generation, pm_obj):
                        return {"ok": False, "state": self.STATUS_DISCONNECTED,
                                "error": "等待原生神庙服务对象删除时游戏连接已失效"}
                    state = int(pm.read_int(status_addr) or -1)
                    if state == -1:
                        time.sleep(0.03)
                        continue
                    if state == 1:
                        target = int(pm.read_int(result_addr) or 0)
                        # The call only schedules GameObject destruction.  A
                        # later game tick runs OnDestroy and releases the
                        # entity, so this readback confirms submission rather
                        # than claiming the full map cleanup has finished.
                        queued = False
                        try:
                            queued = bool(pm.read_bytes(target + 0xA6, 1)[0]) if target else False
                        except Exception:
                            # It may already have been collected, which is
                            # also consistent with a completed native queue.
                            queued = bool(target)
                        return {"ok": bool(target), "state": self.STATUS_UNVERIFIED,
                                "col": col, "row": row, "entity": target,
                                "queued": queued, "complete": False,
                                "message": "已提交游戏原生沙漠神庙服务对象销毁队列；需观察后续帧的贴图、碰撞和存档清理"}
                    errors = {
                        2: "该位置未找到可删除的神庙实体",
                        3: "该位置覆盖的是其它实体，已拒绝删除",
                    }
                    return {"ok": False, "state": self.STATUS_EMPTY if state == 2 else self.STATUS_UNVERIFIED,
                            "col": col, "row": row, "error": errors.get(state, "原生神庙删除请求被拒绝")}
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "原生神庙删除请求未在游戏主线程确认"}
        except (AttributeError, OSError, struct.error, TypeError, ValueError, OverflowError) as exc:
            return {"ok": False, "state": self.STATUS_STALE,
                    "error": "神庙服务对象删除请求失败：%s" % exc}

    # ==================== 魔法传送门 ====================
    PORTAL_CONTAINER_OFF = 0x194
    PORTAL_SLOT_START = 0x3C
    PORTAL_SLOT_END = 0x100
    PORTAL_TIMER_OFF = 0x1C0
    PORTAL_SIG_OFF = 0x184
    PORTAL_KIND_OFF = 0x18C
    PORTAL_ACTIVE_OFF = 0x1C4
    V2_PORTAL_SIGNATURE = b"\x00\x00\xC8\x42\x00\x00\x48\x43"  # +0x184=100.0, +0x188=200.0
    V2_PORTAL_SCAN_TTL = 5.0

    # The visible magic-portal slot table was never validated against the
    # current 1.11.011 object manager.  The values at ITEM_BASE+0x194 contain
    # non-object integers/strings in this build, so treating them as entity
    # pointers can corrupt unrelated memory and later crash the game.  Keep
    # the UI entry, but make every read/write report the exact state until a
    # real vtable/container sample is verified.  Monster-wave lifecycle uses
    # a separate native manager and is not affected by this guard.
    MAGIC_PORTAL_OBJECT_LAYOUT_PROFILES = {
        "steam-v1-local-20260202": False,
    }

    def _magic_portal_object_layout_status(self):
        if not connected or pm is None:
            return False, self.STATUS_DISCONNECTED, "未连接游戏"
        key = str(self._v1_native_layout.get("key") or "")
        if not self._v1_native_layout.get("recognized"):
            return False, self.STATUS_UNSUPPORTED, "当前游戏版本未匹配已验证的传送门对象布局"
        if not self.MAGIC_PORTAL_OBJECT_LAYOUT_PROFILES.get(key, False):
            return False, self.STATUS_UNVERIFIED, (
                "当前版本的魔法传送门对象容器尚未通过验证；为避免再次崩溃，"
                "暂不读取或写入单门倒计时。红门整场事件仍使用独立的原生波次链。"
            )
        return True, self.STATUS_VERIFIED, ""

    def _scan_v2_portal_objects(self):
        """Scan writable private heaps for active magic portal objects (V2).

        The V2 game does not expose the same sparse slot table as V1, so the
        portal signature (100.0/200.0 at +0x184/+0x188) is used instead.  The
        result is cached for a few seconds; refreshes then only re-read the
        known objects.
        """
        global pm, connected
        if not connected or pm is None:
            return []
        try:
            process_id = int(pm.process_id)
            now = time.time()
            with self._v2_portal_scan_lock:
                if (self._v2_portal_scan_pid == process_id
                        and self._v2_portal_objects
                        and now - self._v2_portal_scan_at < self.V2_PORTAL_SCAN_TTL):
                    return list(self._v2_portal_objects)
                signature = self.V2_PORTAL_SIGNATURE
                objects = []
                seen = set()
                writable_protect = {0x04, 0x08, 0x40, 0x80}

                class _MBI(ctypes.Structure):
                    _fields_ = [
                        ("BaseAddress", ctypes.c_void_p), ("AllocationBase", ctypes.c_void_p),
                        ("AllocationProtect", ctypes.c_uint32), ("RegionSize", ctypes.c_size_t),
                        ("State", ctypes.c_uint32), ("Protect", ctypes.c_uint32), ("Type", ctypes.c_uint32),
                    ]

                kernel32 = ctypes.windll.kernel32
                mbi = _MBI()
                address = 0x10000
                limit = 0x80000000
                while address < limit:
                    try:
                        queried = kernel32.VirtualQueryEx(pm.process_handle, address, ctypes.byref(mbi), ctypes.sizeof(mbi))
                    except Exception:
                        queried = 0
                    if not queried:
                        address += 0x10000
                        continue
                    region_base = int(mbi.BaseAddress or 0)
                    region_size = int(mbi.RegionSize or 0)
                    next_address = region_base + region_size
                    if next_address <= address:
                        address += 0x1000
                        continue
                    protect = int(mbi.Protect)
                    if (mbi.State != 0x1000 or mbi.Type != 0x20000 or protect & 0x100
                            or (protect & 0xFF) not in writable_protect or region_size < 4):
                        address = next_address
                        continue
                    offset = 0
                    while offset < region_size:
                        read_size = min(0x200000, region_size - offset)
                        read_base = region_base + offset
                        try:
                            block = pm.read_bytes(read_base, read_size)
                        except Exception:
                            block = None
                        if block:
                            pos = block.find(signature)
                            while pos != -1:
                                obj = read_base + pos - self.PORTAL_SIG_OFF
                                if obj not in seen:
                                    seen.add(obj)
                                    try:
                                        f1 = pm.read_float(obj + self.PORTAL_SIG_OFF)
                                        f2 = pm.read_float(obj + self.PORTAL_SIG_OFF + 4)
                                        kind = pm.read_int(obj + self.PORTAL_KIND_OFF)
                                        timer = pm.read_float(obj + self.PORTAL_TIMER_OFF)
                                        active_flag = pm.read_int(obj + self.PORTAL_ACTIVE_OFF)
                                    except Exception:
                                        continue
                                    if (f1 is None or f2 is None or kind is None or timer is None
                                            or active_flag is None):
                                        continue
                                    if (abs(f1 - 100.0) > 0.001 or abs(f2 - 200.0) > 0.001
                                            or (kind & 0xFF) != 1):
                                        continue
                                    if not math.isfinite(timer) or timer < -0.01:
                                        continue
                                    if timer <= 0.01:
                                        continue
                                    objects.append(obj)
                                pos = block.find(signature, pos + 1)
                        if offset + read_size >= region_size:
                            break
                        offset += max(1, read_size - 8)
                    address = next_address
                self._v2_portal_objects = objects
                self._v2_portal_scan_at = now
                self._v2_portal_scan_pid = process_id
                return list(objects)
        except Exception:
            return []

    def _portal_entries(self):
        """Enumerate active magic portal objects (V1 slot table / V2 heap scan)."""
        global pm, connected
        layout_ok, _, layout_error = self._magic_portal_object_layout_status()
        if not layout_ok:
            return None, layout_error
        try:
            entries = {}
            current_samples = {}

            def accept(obj, slot):
                try:
                    f1 = pm.read_float(obj + self.PORTAL_SIG_OFF)
                    f2 = pm.read_float(obj + self.PORTAL_SIG_OFF + 4)
                    kind = pm.read_int(obj + self.PORTAL_KIND_OFF)
                    timer = pm.read_float(obj + self.PORTAL_TIMER_OFF)
                    active_flag = pm.read_int(obj + self.PORTAL_ACTIVE_OFF)
                except Exception:
                    return
                if f1 is None or f2 is None or kind is None or timer is None or active_flag is None:
                    return
                if abs(f1 - 100.0) > 0.001 or abs(f2 - 200.0) > 0.001 or (kind & 0xFF) != 1:
                    return
                if not math.isfinite(timer) or timer < -0.01:
                    return
                if timer <= 0.01:
                    return
                previous_timer = self._portal_samples.get(obj)
                if previous_timer is not None and abs(previous_timer - float(timer)) < 0.05:
                    self._portal_stability[obj] = self._portal_stability.get(obj, 0) + 1
                else:
                    self._portal_stability[obj] = 0
                current_samples[obj] = float(timer)
                # A stale canceled object can retain a positive cached timer.
                # Keep a new object visible immediately, then hide it only
                # after several stable samples with an inactive state flag.
                if active_flag != 0 and self._portal_stability.get(obj, 0) >= 3:
                    return
                entry = entries.setdefault(obj, {"object": obj, "slots": [], "timer": float(timer)})
                entry["slots"].append(slot)
                entry["timer"] = float(timer)

            if self._detect_v2():
                for obj in self._scan_v2_portal_objects():
                    accept(obj, obj)
            else:
                root = pm.read_int(get_base() + ITEM_BASE_OFFSET)
                container = root and pm.read_int(root + self.PORTAL_CONTAINER_OFF)
                if not container or container < 0x10000:
                    return None, "未找到传送门容器"
                for slot in range(self.PORTAL_SLOT_START, self.PORTAL_SLOT_END + 1, 4):
                    obj = pm.read_int(container + slot)
                    if not _is_plausible_32bit_pointer(obj):
                        continue
                    accept(obj, slot)

            self._portal_samples = current_samples
            self._portal_stability = {obj: self._portal_stability.get(obj, 0) for obj in current_samples}
            return list(entries.values()), None
        except Exception as e:
            return None, str(e)

    def get_portals(self):
        entries, error = self._portal_entries()
        if entries is None:
            if not connected or pm is None:
                state = self.STATUS_DISCONNECTED
            elif str(error or "").startswith("当前版本的魔法传送门"):
                state = self.STATUS_UNVERIFIED
            elif str(error or "").startswith("当前游戏版本未匹配"):
                state = self.STATUS_UNSUPPORTED
            else:
                state = self.STATUS_STALE
            return {"ok": False, "state": state,
                    "error": error or "传送门对象定位失败", "portals": None}
        portals = []
        for entry in entries:
            timer = entry["timer"]
            portals.append({
                "object": entry["object"],
                "timer_address": entry["object"] + self.PORTAL_TIMER_OFF,
                "timer": timer,
                "active": True,
                "slots": entry["slots"],
                "locked": entry["object"] in self._portal_locks,
            })
        portals.sort(key=lambda p: (not p["active"], p["slots"][0]))
        return {"ok": True, "state": self.STATUS_VERIFIED, "portals": portals}

    def _portal_by_object(self, object_addr):
        entries, _ = self._portal_entries()
        if not entries:
            return None
        for entry in entries:
            if entry["object"] == int(object_addr):
                return entry
        return None

    def _read_verified_magic_portal(self, object_addr):
        """Revalidate a portal object while the process is paused.

        A slot-table address is only a candidate identity.  The object can be
        destroyed/reused between a list refresh and a write, so every future
        verified layout must recheck its signature, kind, activity and timer
        immediately before and after the mutation.
        """
        try:
            object_addr = int(object_addr)
            f1 = pm.read_float(object_addr + self.PORTAL_SIG_OFF)
            f2 = pm.read_float(object_addr + self.PORTAL_SIG_OFF + 4)
            kind = pm.read_int(object_addr + self.PORTAL_KIND_OFF)
            timer = pm.read_float(object_addr + self.PORTAL_TIMER_OFF)
            active_flag = pm.read_int(object_addr + self.PORTAL_ACTIVE_OFF)
            if (f1 is None or f2 is None or kind is None or timer is None
                    or active_flag is None or abs(float(f1) - 100.0) > 0.001
                    or abs(float(f2) - 200.0) > 0.001 or (int(kind) & 0xFF) != 1
                    or not math.isfinite(float(timer)) or float(timer) < -0.01
                    or float(timer) <= 0.01):
                return None
            return {"object": object_addr, "timer": float(timer),
                    "active_flag": int(active_flag)}
        except Exception:
            return None

    def set_portal_timer(self, object_addr, seconds):
        layout_ok, state, layout_error = self._magic_portal_object_layout_status()
        if not layout_ok:
            return {"ok": False, "state": state, "error": layout_error}
        blocked = self._require_high_risk_world_write("传送门倒计时写入")
        if blocked:
            return {"ok": False, "error": blocked}
        try:
            seconds = float(seconds)
            if not math.isfinite(seconds) or seconds < 1:
                return {"ok": False, "error": "时间必须是不小于 1 秒的有效数字"}
            entry = self._portal_by_object(object_addr)
            if not entry:
                return {"ok": False, "error": "传送门已消失，请刷新"}
            hnd = self._suspend(pm.process_id)
            try:
                latest = self._read_verified_magic_portal(entry["object"])
                if not latest:
                    return {"ok": False, "state": self.STATUS_STALE,
                            "error": "传送门对象在写入前已变化，未执行修改"}
                old_timer = float(latest["timer"])
                pm.write_float(entry["object"] + self.PORTAL_TIMER_OFF, seconds)
                readback = self._read_verified_magic_portal(entry["object"])
                if not readback or abs(float(readback["timer"]) - seconds) > 0.05:
                    try:
                        pm.write_float(entry["object"] + self.PORTAL_TIMER_OFF, old_timer)
                    except Exception:
                            pass
                    return {"ok": False, "state": self.STATUS_FAILED,
                            "error": "传送门倒计时写入读回失败，已尝试恢复原值"}
                # If the UI temporarily/explicitly froze this portal, move
                # the lock target together with the new value.  Otherwise the
                # background lock worker would immediately restore the old
                # countdown after this successful write.
                with self._portal_lock_guard:
                    if int(entry["object"]) in self._portal_locks:
                        self._portal_locks[int(entry["object"])] = float(seconds)
            finally:
                self._resume(hnd)
            return {"ok": True, "state": self.STATUS_VERIFIED, "timer": seconds}
        except Exception as e:
            return {"ok": False, "error": str(e)}

    def add_portal_time(self, object_addr, seconds=60):
        layout_ok, state, layout_error = self._magic_portal_object_layout_status()
        if not layout_ok:
            return {"ok": False, "state": state, "error": layout_error}
        blocked = self._require_high_risk_world_write("传送门倒计时写入")
        if blocked:
            return {"ok": False, "error": blocked}
        entry = self._portal_by_object(object_addr)
        if not entry:
            return {"ok": False, "error": "传送门已消失，请刷新"}
        return self.set_portal_timer(object_addr, float(entry["timer"]) + float(seconds))

    def close_portal(self, object_addr):
        """Ask the game to close one magic portal on its next normal update.

        The portal's own update destroys it when its duration reaches zero.
        We intentionally change only that duration: clearing container slots or
        the object's active flag directly can leave dangling game references.
        """
        layout_ok, state, layout_error = self._magic_portal_object_layout_status()
        if not layout_ok:
            return {"ok": False, "state": state, "error": layout_error}
        blocked = self._require_high_risk_world_write("关闭传送门")
        if blocked:
            return {"ok": False, "error": blocked}
        try:
            entry = self._portal_by_object(object_addr)
            if not entry:
                return {"ok": False, "error": "传送门已消失，请刷新"}
            object_addr = int(entry["object"])
            # A frozen portal would otherwise be restored by its background
            # loop.  Remove the lock first, then make the final write zero.
            hnd = self._suspend(pm.process_id)
            if hnd is None:
                return {"ok": False, "error": "无法暂停游戏以安全关闭传送门"}
            try:
                with self._portal_lock_guard:
                    self._portal_locks.pop(object_addr, None)
                    latest = self._read_verified_magic_portal(object_addr)
                    if not latest:
                        return {"ok": False, "state": self.STATUS_STALE,
                                "error": "传送门对象在关闭前已变化，未执行修改"}
                    pm.write_float(object_addr + self.PORTAL_TIMER_OFF, 0.0)
                    readback = pm.read_float(object_addr + self.PORTAL_TIMER_OFF)
                    if readback is None or abs(float(readback)) > 0.05:
                        try:
                            pm.write_float(object_addr + self.PORTAL_TIMER_OFF, latest["timer"])
                        except Exception:
                            pass
                        return {"ok": False, "state": self.STATUS_FAILED,
                                "error": "传送门关闭写入读回失败，已尝试恢复原值"}
            finally:
                self._resume(hnd)
            return {"ok": True, "state": self.STATUS_VERIFIED,
                    "message": "已请求关闭传送门（游戏下一帧会自行清理）"}
        except Exception as e:
            return {"ok": False, "error": "关闭传送门失败：%s" % e}

    def toggle_portal_lock(self, object_addr):
        layout_ok, state, layout_error = self._magic_portal_object_layout_status()
        if not layout_ok:
            return {"ok": False, "state": state, "error": layout_error}
        blocked = self._require_high_risk_world_write("锁定传送门")
        if blocked:
            return {"ok": False, "error": blocked}
        try:
            object_addr = int(object_addr)
            with self._portal_lock_guard:
                if object_addr in self._portal_locks:
                    del self._portal_locks[object_addr]
                    return {"ok": True, "locked": False}
                entry = self._portal_by_object(object_addr)
                if not entry or entry["timer"] <= 0.01:
                    return {"ok": False, "error": "没有可冻结的有效传送门"}
                session_generation, pm_obj = self._runtime_lock_worker_context()
                if not self._runtime_session_current(session_generation, pm_obj):
                    return {"ok": False, "error": "游戏会话已改变"}
                self._portal_locks[object_addr] = entry["timer"]
            self._spawn_runtime_worker(self._portal_lock_loop,
                                       args=(object_addr, session_generation, pm_obj),
                                       name="ctw-portal-lock")
            return {"ok": True, "locked": True, "timer": entry["timer"]}
        except Exception as e:
            return {"ok": False, "error": str(e)}

    def _portal_lock_loop(self, object_addr, session_generation, pm_obj):
        while (object_addr in self._portal_locks and
               self._runtime_session_current(session_generation, pm_obj)):
            try:
                layout_ok, _, _ = self._magic_portal_object_layout_status()
                if not layout_ok:
                    with self._portal_lock_guard:
                        self._portal_locks.pop(object_addr, None)
                    return
                hnd = self._suspend(pm_obj.process_id)
                if hnd is None:
                    return
                try:
                    if not self._runtime_session_current(session_generation, pm_obj):
                        return
                    with self._portal_lock_guard:
                        if object_addr not in self._portal_locks:
                            break
                        entry = self._portal_by_object(object_addr)
                        if not entry:
                            self._portal_locks.pop(object_addr, None)
                            break
                        pm_obj.write_float(object_addr + self.PORTAL_TIMER_OFF,
                                           self._portal_locks[object_addr])
                finally:
                    self._resume(hnd)
                time.sleep(0.35)
            except Exception:
                if self._runtime_session_current(session_generation, pm_obj):
                    self._portal_locks.pop(object_addr, None)
                break

    _v2_cache = None
    def _detect_v2(self):
        """_detect_v2"""
        if self._v2_cache is not None:
            return self._v2_cache
        try:
            import psutil as _psutil
            exe = _psutil.Process(pm.process_id).exe().lower()
            if "dragon" in exe or "\u5de8\u9f99" in exe:
                self._v2_cache = True
                return True
            if "crafttheworld" in exe or "steam" in exe:
                self._v2_cache = False
                return False
        except Exception:
            pass
        try:
            mgr = pm.read_int(get_base() + V2_RESOURCE_MGR)
            if mgr:
                ab = pm.read_int(mgr + V2_RES_ARR_BASE)
                ae = pm.read_int(mgr + V2_RES_ARR_END)
                if ab and ae and ab < ae:
                    self._v2_cache = True
                    return True
        except Exception:
            pass
        self._v2_cache = False
        return False

    def _v2_gold_ptr(self):
        """_v2_gold_ptr"""
        try:
            mgr = pm.read_int(get_base() + V2_RESOURCE_MGR)
            if mgr:
                ab = pm.read_int(mgr + V2_RES_ARR_BASE)
                if ab:
                    return ab + V2_GOLD_INDEX * V2_RES_ELEM_SIZE
        except Exception:
            pass
        return None

    def _v2_mana_ptr(self):
        """_v2_mana_ptr"""
        try:
            return get_base() + V2_MANAGER_ARRAY + V2_MANA_OBJ_INDEX * 4
        except Exception:
            return None

    def gp(self):
        """gp"""
        try:
            mgr=pm.read_int(get_base()+0xDE3BB0)
            return pm.read_int(mgr+0x1C) if mgr else None
        except: return None

    def read_gold(self):
        """读取当前金币数量；失败必须显式返回 ``None``。

        This legacy helper is still used by a few lock/diagnostic paths.  Do
        not use ``0`` as a sentinel here: zero is a real, valid gold value.
        The UI-facing ``get_basic_state`` turns this into an explicit status.
        """
        try:
            if self._detect_v2():
                pp=self._v2_gold_ptr()
                if pp:
                    key=pm.read_int(pp+V2_GOLD_KEY);enc=pm.read_int(pp+V2_GOLD_ENC)
                    if key is not None and enc is not None:
                        return str((key^enc)&0xFFFFFFFF)
            p=self.gp()
            if not p:
                return None
            enc=pm.read_int(p+0x4C34);key=pm.read_int(p+0x4ADC)
            if enc is None or key is None:
                return None
            return str((enc^key)&0xFFFFFFFF)
        except Exception:
            return None

    def write_gold(self,amt):
        """写入金币数量"""
        try:
            amt = int(amt)
            if self._detect_v2():
                pp=self._v2_gold_ptr()
                if pp:
                    k1=pm.read_int(pp+0x94);k2=pm.read_int(pp+0x208)
                    pm.write_int(pp+0x204,amt^k1);pm.write_int(pp+0x20C,amt^k2)
                    pm.write_int(pp+V2_GOLD_VAL_OFF,amt)
                    return True
            p=self.gp()
            if not p: return False
            k1=pm.read_int(p+0x4ADC);k2=pm.read_int(p+0x4C3C)
            pm.write_int(p+0x4C34,amt^k1);pm.write_int(p+0x4C38,amt^k2)
            return True
        except: return False

    # ==================== 金币经济控制（V1.0） ====================

    @classmethod
    def _clean_gold_amount(cls, value, allow_empty=True):
        if value is None or value == "":
            return None if allow_empty else None
        if isinstance(value, bool):
            return None
        try:
            number = int(float(value))
        except (TypeError, ValueError, OverflowError):
            return None
        if number < 0 or number > cls.GOLD_ECONOMY_MAX:
            return None
        return number

    @classmethod
    def _clean_gold_economy_rule(cls, value):
        value = value if isinstance(value, dict) else {}
        mode = str(value.get("mode") or "floor").strip().lower()
        if mode not in ("floor", "fixed"):
            mode = "floor"
        floor = cls._clean_gold_amount(value.get("floor"))
        ceiling = cls._clean_gold_amount(value.get("ceiling"))
        fixed = cls._clean_gold_amount(value.get("fixed"))
        if ceiling is not None and floor is not None and floor > ceiling:
            return None, "金币保底不能高于金币上限"
        if mode == "floor" and floor is None:
            return None, "请设置非负的金币保底"
        if mode == "fixed" and fixed is None:
            return None, "请设置非负的固定金币目标"
        if ceiling is not None and mode == "floor" and floor > ceiling:
            return None, "金币保底不能高于金币上限"
        if ceiling is not None and mode == "fixed" and fixed > ceiling:
            return None, "固定金币目标不能高于金币上限"
        return {"mode": mode, "floor": floor, "ceiling": ceiling, "fixed": fixed}, ""

    def _gold_economy_add_event(self, source, before, after, message=""):
        event = {"at": time.strftime("%H:%M:%S"), "source": str(source or "金币操作"),
                 "before": int(before), "after": int(after), "message": str(message or "")}
        with self._gold_economy_guard:
            self._gold_economy_events.append(event)
            self._gold_economy_events = self._gold_economy_events[-40:]
        return event

    def _gold_economy_runtime_snapshot(self):
        with self._gold_economy_guard:
            state = dict(self._gold_economy_state)
            state.pop("generation", None)
            state["last_before"] = self._gold_economy_last_before
            state["last_after"] = self._gold_economy_last_after
            state["interval"] = self.GOLD_ECONOMY_INTERVAL
            state["events"] = list(self._gold_economy_events)
        return state

    def _stop_gold_economy_runtime(self):
        with self._gold_economy_guard:
            self._gold_economy_state["enabled"] = False
            self._gold_economy_state["generation"] = int(self._gold_economy_state.get("generation", 0)) + 1

    def _gold_transaction(self, operation, value=None, source="手动金币操作", remember_before=True):
        """Pause once, resolve from the live amount, write, and immediately read back."""
        if not connected or not pm:
            return {"ok": False, "error": "请先连接游戏"}
        try:
            requested = None if value is None else float(value)
        except (TypeError, ValueError, OverflowError):
            return {"ok": False, "error": "金币参数无效"}
        if requested is not None and (not math.isfinite(requested) or abs(requested) > self.GOLD_ECONOMY_MAX):
            return {"ok": False, "error": "金币参数超出允许范围"}
        with self._memory_write_lock:
            generation, pm_obj = self._runtime_lock_worker_context()
            if not self._runtime_session_current(generation, pm_obj):
                return {"ok": False, "error": "游戏连接已失效，请重新连接"}
            hnd = self._suspend(pm_obj.process_id)
            if not hnd:
                return {"ok": False, "error": "无法暂停游戏以安全写入金币"}
            try:
                raw_before = self.read_gold()
                if raw_before is None:
                    return {"ok": False, "error": "金币对象未读取到，未写入"}
                before = int(raw_before)
                op = str(operation or "").lower()
                if op == "set":
                    target = int(requested)
                elif op == "add":
                    target = before + int(requested)
                elif op == "multiply":
                    target = int(round(before * float(requested)))
                elif op == "percent":
                    target = int(round(before * float(requested) / 100.0))
                elif op == "restore":
                    with self._gold_economy_guard:
                        target = self._gold_economy_last_before
                    if target is None:
                        return {"ok": False, "error": "本次启动后还没有可恢复的金币操作"}
                    target = int(target)
                else:
                    return {"ok": False, "error": "未知金币操作"}
                if target < 0 or target > self.GOLD_ECONOMY_MAX:
                    return {"ok": False, "error": "计算后的金币数量超出 0 到 %d 的范围" % self.GOLD_ECONOMY_MAX}
                if target == before:
                    return {"ok": True, "changed": False, "before": before, "after": before,
                            "message": "金币无需变化"}
                if not self.write_gold(target):
                    return {"ok": False, "error": "金币写入失败"}
                raw_after = self.read_gold()
                after = int(raw_after) if raw_after is not None else None
                if after != target:
                    self.write_gold(before)
                    return {"ok": False, "error": "金币写后读回不一致，已恢复写前数值"}
            finally:
                self._resume(hnd)
        if remember_before:
            with self._gold_economy_guard:
                self._gold_economy_last_before = before
                self._gold_economy_last_after = after
        event = self._gold_economy_add_event(source, before, after, op)
        return {"ok": True, "changed": True, "before": before, "after": after,
                "event": event, "readback_ok": True}

    def gold_apply_operation(self, operation, value=None):
        """Immediate set/add/ratio/restore actions used by the economy panel."""
        labels = {"set": "设置金币", "add": "增减金币", "multiply": "金币倍率",
                  "percent": "金币百分比", "restore": "恢复本次操作前金币"}
        return self._gold_transaction(operation, value, labels.get(str(operation or "").lower(), "金币操作"), True)

    def _gold_economy_enforce_once(self, source="低频保底检查"):
        with self._gold_economy_guard:
            state = dict(self._gold_economy_state)
        if not state.get("enabled"):
            return {"ok": True, "changed": False, "message": "规则未启用"}
        current_raw = self.read_gold()
        if current_raw is None:
            return {"ok": False, "error": "金币读取失败"}
        current = int(current_raw)
        if state.get("mode") == "fixed":
            target = int(state.get("fixed"))
        elif current < int(state.get("floor")):
            target = int(state.get("floor"))
        else:
            return {"ok": True, "changed": False, "before": current, "after": current,
                    "message": "金币仍在保底范围内"}
        ceiling = state.get("ceiling")
        if ceiling is not None and target > int(ceiling):
            return {"ok": False, "error": "规则目标高于当前设置的金币上限"}
        if target == current:
            return {"ok": True, "changed": False, "before": current, "after": current}
        return self._gold_transaction("set", target, source, False)

    def _gold_economy_loop(self, generation, session_generation, pm_obj):
        while self._runtime_session_current(session_generation, pm_obj):
            with self._gold_economy_guard:
                active = bool(self._gold_economy_state.get("enabled"))
                same_generation = int(self._gold_economy_state.get("generation", 0)) == int(generation)
            if not active or not same_generation:
                return
            result = self._gold_economy_enforce_once()
            if not result.get("ok"):
                self._stop_gold_economy_runtime()
                return
            time.sleep(self.GOLD_ECONOMY_INTERVAL)

    def set_gold_economy_rule(self, enabled, mode="floor", floor=None, ceiling=None, fixed=None):
        enabled = bool(enabled)
        if not enabled:
            self._stop_gold_economy_runtime()
            return {"ok": True, "enabled": False}
        rule, error = self._clean_gold_economy_rule({"mode": mode, "floor": floor,
                                                     "ceiling": ceiling, "fixed": fixed})
        if not rule:
            return {"ok": False, "error": error}
        if not connected or not pm:
            return {"ok": False, "error": "请先连接游戏"}
        with self._gold_economy_guard:
            generation = int(self._gold_economy_state.get("generation", 0)) + 1
            self._gold_economy_state = {"enabled": True, **rule, "generation": generation}
        session_generation, pm_obj = self._runtime_lock_worker_context()
        if not self._runtime_session_current(session_generation, pm_obj):
            self._stop_gold_economy_runtime()
            return {"ok": False, "error": "游戏会话已改变，未启动金币规则"}
        first = self._gold_economy_enforce_once("启用金币规则")
        if not first.get("ok"):
            self._stop_gold_economy_runtime()
            return first
        self._spawn_runtime_worker(self._gold_economy_loop,
                                   args=(generation, session_generation, pm_obj),
                                   name="ctw-gold-economy")
        return {"ok": True, "enabled": True, **rule, "first": first,
                "message": "本局金币规则已启用；关闭修改器或断开连接后会自动停止"}

    def _gold_economy_presets(self):
        raw = self._read_config().get("gold_economy_presets", {})
        result = {}
        if not isinstance(raw, dict):
            return result
        for name, value in raw.items():
            clean, _ = self._clean_gold_economy_rule(value)
            if clean:
                result[str(name)] = clean
        return result

    def get_gold_economy_state(self):
        current = self.read_gold() if connected and pm else None
        state = self._gold_economy_runtime_snapshot()
        if connected and pm and current is None:
            return {"ok": False, "state": self.STATUS_STALE,
                    "error": "金币读取失败，未以 0 代替", "data": None}
        return {"ok": True, "state": self.STATUS_VERIFIED if connected and pm else self.STATUS_DISCONNECTED,
                "current": int(current) if current is not None else None,
                "rule": state, "presets": self._gold_economy_presets(),
                "builtins": {
                    "生存档": {"mode": "floor", "floor": 5000, "ceiling": None, "fixed": None},
                    "建造档": {"mode": "floor", "floor": 100000, "ceiling": None, "fixed": None},
                    "测试档": {"mode": "fixed", "floor": None, "ceiling": None, "fixed": 999999},
                }}

    def save_gold_economy_preset(self, name, mode, floor=None, ceiling=None, fixed=None):
        title = str(name or "").strip()
        if not title or len(title) > 40:
            return {"ok": False, "error": "预设名称需为 1 到 40 个字符"}
        rule, error = self._clean_gold_economy_rule({"mode": mode, "floor": floor,
                                                     "ceiling": ceiling, "fixed": fixed})
        if not rule:
            return {"ok": False, "error": error}
        def update(cfg):
            presets = cfg.get("gold_economy_presets")
            if not isinstance(presets, dict):
                presets = {}
            presets[title] = rule
            cfg["gold_economy_presets"] = presets
        if not self._update_config(update):
            return {"ok": False, "error": "无法保存金币预设"}
        return {"ok": True, "name": title, "rule": rule}

    def rename_gold_economy_preset(self, old_name, new_name):
        old_name, new_name = str(old_name or "").strip(), str(new_name or "").strip()
        if not old_name or not new_name or len(new_name) > 40:
            return {"ok": False, "error": "请输入有效的新预设名称"}
        result = {"ok": False, "error": "未找到金币预设"}
        def update(cfg):
            nonlocal result
            presets = cfg.get("gold_economy_presets")
            if not isinstance(presets, dict) or old_name not in presets:
                return
            if new_name != old_name and new_name in presets:
                result = {"ok": False, "error": "已有同名金币预设"}
                return
            presets[new_name] = presets.pop(old_name)
            cfg["gold_economy_presets"] = presets
            result = {"ok": True, "name": new_name}
        self._update_config(update)
        return result

    def copy_gold_economy_preset(self, source_name, new_name):
        presets = self._gold_economy_presets()
        rule = presets.get(str(source_name or "").strip())
        if not rule:
            return {"ok": False, "error": "未找到要复制的金币预设"}
        return self.save_gold_economy_preset(new_name, **rule)

    def read_mana(self):
        """读取当前法力值；失败必须显式返回 ``None``。"""
        try:
            if self._detect_v2():
                try:
                    mana_obj = pm.read_int(get_base() + V2_MANAGER_ARRAY + V2_MANA_OBJ_INDEX)
                    if mana_obj and mana_obj > 0x10000:
                        ca = mana_obj + V2_MANA_CUR_OFF
                        ma = mana_obj + V2_MANA_MAX_OFF
                        ce = pm.read_int(ca+0); ck = pm.read_int(ca+8)
                        me = pm.read_int(ma+0); mk = pm.read_int(ma+8)
                        if ce is not None and ck is not None:
                            cv = struct.unpack("f", struct.pack("I", (ce ^ ck) & 0xFFFFFFFF))[0]
                            mv = 100.0
                            if me is not None and mk is not None:
                                mv = struct.unpack("f", struct.pack("I", (me ^ mk) & 0xFFFFFFFF))[0]
                            if math.isfinite(cv) and math.isfinite(mv):
                                return "%.1f|%.1f" % (cv, mv)
                except Exception:
                    pass
            ui=pm.read_int(get_base()+0xDC3628)
            if not ui:
                return None
            a=ui+0x64;e1=pm.read_int(a);k1=pm.read_int(a+8)
            mm=ui+V1_MANA_MAX_OFF;me=pm.read_int(mm+V1_MANA_ENC1);mk=pm.read_int(mm+V1_MANA_KEY1)
            if None in (e1, k1, me, mk):
                return None
            c=struct.unpack("f",struct.pack("I",(e1^k1)&0xFFFFFFFF))[0]
            m=struct.unpack("f",struct.pack("I",(me^mk)&0xFFFFFFFF))[0]
            if not math.isfinite(c) or not math.isfinite(m):
                return None
            return "%.1f|%.1f"%(c,m)
        except Exception:
            return None

    def write_mana(self,val):
        """写入法力值"""
        try:
            if self._detect_v2():
                try:
                    mana_obj = pm.read_int(get_base() + V2_MANAGER_ARRAY + V2_MANA_OBJ_INDEX)
                    if mana_obj and mana_obj > 0x10000:
                        ca = mana_obj + V2_MANA_CUR_OFF
                        k1 = pm.read_int(ca+8); k2 = pm.read_int(ca+12)
                        fi = struct.unpack("<I", struct.pack("<f", float(val)))[0]
                        pm.write_int(ca+0, fi ^ k1); pm.write_int(ca+4, fi ^ k2)
                        pm.write_float(get_base() + 0xC96560, float(val))
                        return True
                except Exception:
                    pass
            ui=pm.read_int(get_base()+0xDC3628)
            if not ui: return False
            a=ui+0x64;k1=pm.read_int(a+8);k2=pm.read_int(a+12)
            fi=struct.unpack("<I",struct.pack("<f",float(val)))[0]
            pm.write_int(a,fi^k1);pm.write_int(a+4,fi^k2)
            return True
        except: return False

    def write_mana_max(self,val):
        """写入最大法力值"""
        try:
            amount = float(val)
            fi = struct.unpack("<I", struct.pack("<f", amount))[0]
            if self._detect_v2():
                try:
                    mana_obj = pm.read_int(get_base() + V2_MANAGER_ARRAY + V2_MANA_OBJ_INDEX)
                    if mana_obj and mana_obj > 0x10000:
                        ma = mana_obj + V2_MANA_MAX_OFF
                        k1 = pm.read_int(ma + 8)
                        k2 = pm.read_int(ma + 12)
                        pm.write_int(ma + 0, fi ^ k1)
                        if k2 is not None:
                            pm.write_int(ma + 4, fi ^ k2)
                        # 同步显示地址
                        try:
                            pm.write_float(get_base() + V2_MANA_DISPLAY, amount)
                        except Exception:
                            pass
                        return True
                except Exception:
                    pass
            # V1 路径
            ui = pm.read_int(get_base() + V1_MANA_BASE)
            if not ui: return False
            addr = ui + V1_MANA_MAX_OFF
            k1 = pm.read_int(addr + V1_MANA_KEY1)
            k2 = pm.read_int(addr + V1_MANA_KEY2)
            pm.write_int(addr + V1_MANA_ENC1, fi ^ k1)
            if k2 is not None:
                pm.write_int(addr + V1_MANA_ENC2, fi ^ k2)
            return True
        except: return False

    # ==================== 法力资源控制（V1.0） ====================

    def _read_mana_pair(self):
        raw = self.read_mana()
        if not raw or "|" not in str(raw):
            return None
        try:
            current, maximum = (float(part) for part in str(raw).split("|", 1))
        except (TypeError, ValueError):
            return None
        if (not math.isfinite(current) or not math.isfinite(maximum) or current < 0 or
                maximum <= 0 or current > self.MANA_CONTROL_MAX or maximum > self.MANA_CONTROL_MAX):
            return None
        return current, maximum

    @staticmethod
    def _mana_close(left, right):
        return abs(float(left) - float(right)) <= 0.11

    def _mana_control_transaction(self, kind, operation, value=None, sync_current=False, source="法力操作"):
        if not connected or not pm:
            return {"ok": False, "error": "请先连接游戏"}
        try:
            requested = None if value is None else float(value)
        except (TypeError, ValueError, OverflowError):
            return {"ok": False, "error": "法力参数无效"}
        if requested is not None and (not math.isfinite(requested) or abs(requested) > self.MANA_CONTROL_MAX):
            return {"ok": False, "error": "法力参数超出允许范围"}
        with self._memory_write_lock:
            generation, pm_obj = self._runtime_lock_worker_context()
            if not self._runtime_session_current(generation, pm_obj):
                return {"ok": False, "error": "游戏连接已失效，请重新连接"}
            hnd = self._suspend(pm_obj.process_id)
            if not hnd:
                return {"ok": False, "error": "无法暂停游戏以安全写入法力"}
            try:
                before_pair = self._read_mana_pair()
                if not before_pair:
                    return {"ok": False, "error": "法力对象未读取到，未写入"}
                before_current, before_max = before_pair
                op = str(operation or "").lower()
                if kind == "current":
                    if op == "set": target = requested
                    elif op == "add": target = before_current + requested
                    elif op == "percent": target = before_max * requested / 100.0
                    elif op == "fill": target = before_max
                    elif op == "zero": target = 0.0
                    else: return {"ok": False, "error": "未知当前法力操作"}
                    target = max(0.0, min(float(target), before_max))
                    if self._mana_close(target, before_current):
                        return {"ok": True, "changed": False, "current": before_current, "maximum": before_max,
                                "message": "当前法力无需变化"}
                    if not self.write_mana(target):
                        return {"ok": False, "error": "当前法力写入失败"}
                    after_pair = self._read_mana_pair()
                    if not after_pair or not self._mana_close(after_pair[0], target):
                        self.write_mana(before_current)
                        return {"ok": False, "error": "当前法力写后读回不一致，已恢复写前数值"}
                elif kind == "maximum":
                    if op == "set": target_max = requested
                    elif op == "add": target_max = before_max + requested
                    elif op == "multiply": target_max = before_max * requested
                    else: return {"ok": False, "error": "未知法力上限操作"}
                    if target_max is None or target_max <= 0 or target_max > self.MANA_CONTROL_MAX:
                        return {"ok": False, "error": "法力上限需在 0 到 %d 之间" % self.MANA_CONTROL_MAX}
                    if not self.write_mana_max(target_max):
                        return {"ok": False, "error": "法力上限写入失败"}
                    target_current = float(target_max) if sync_current else min(before_current, float(target_max))
                    if not self._mana_close(target_current, before_current) and not self.write_mana(target_current):
                        self.write_mana_max(before_max)
                        return {"ok": False, "error": "同步当前法力失败，已恢复法力上限"}
                    after_pair = self._read_mana_pair()
                    if (not after_pair or not self._mana_close(after_pair[1], target_max) or
                            not self._mana_close(after_pair[0], target_current)):
                        self.write_mana_max(before_max)
                        self.write_mana(before_current)
                        return {"ok": False, "error": "法力上限写后读回不一致，已恢复写前数值"}
                else:
                    return {"ok": False, "error": "未知法力控制类型"}
            finally:
                self._resume(hnd)
        return {"ok": True, "changed": True, "before_current": before_current, "before_max": before_max,
                "current": after_pair[0], "maximum": after_pair[1], "readback_ok": True,
                "source": source}

    def mana_apply_operation(self, operation, value=None):
        labels = {"set": "设置当前法力", "add": "增减当前法力", "percent": "按上限百分比设置法力",
                  "fill": "一键满蓝", "zero": "当前法力归零"}
        return self._mana_control_transaction("current", operation, value, False,
                                              labels.get(str(operation or "").lower(), "当前法力操作"))

    def mana_apply_max_operation(self, operation, value=None, sync_current=False):
        labels = {"set": "设置法力上限", "add": "增减法力上限", "multiply": "法力上限倍率"}
        return self._mana_control_transaction("maximum", operation, value, bool(sync_current),
                                              labels.get(str(operation or "").lower(), "法力上限操作"))

    def _stop_mana_reserve_runtime(self):
        with self._mana_reserve_guard:
            self._mana_reserve_state["enabled"] = False
            self._mana_reserve_state["generation"] = int(self._mana_reserve_state.get("generation", 0)) + 1

    def _mana_reserve_once(self, source="法力保留检查"):
        with self._mana_reserve_guard:
            state = dict(self._mana_reserve_state)
        if not state.get("enabled"):
            return {"ok": True, "changed": False}
        pair = self._read_mana_pair()
        if not pair:
            return {"ok": False, "error": "法力读取失败"}
        current, maximum = pair
        low = maximum * float(state["low_percent"]) / 100.0
        if current >= low:
            return {"ok": True, "changed": False, "current": current, "maximum": maximum}
        target = maximum * float(state["restore_percent"]) / 100.0
        return self._mana_control_transaction("current", "set", target, False, source)

    def _mana_reserve_loop(self, generation, session_generation, pm_obj):
        while self._runtime_session_current(session_generation, pm_obj):
            with self._mana_reserve_guard:
                active = bool(self._mana_reserve_state.get("enabled"))
                same_generation = int(self._mana_reserve_state.get("generation", 0)) == int(generation)
            if not active or not same_generation:
                return
            result = self._mana_reserve_once()
            if not result.get("ok"):
                self._stop_mana_reserve_runtime()
                return
            time.sleep(self.MANA_RESERVE_INTERVAL)

    def set_mana_reserve_rule(self, enabled, low_percent=30, restore_percent=80):
        enabled = bool(enabled)
        if not enabled:
            self._stop_mana_reserve_runtime()
            return {"ok": True, "enabled": False}
        try:
            low, restore = float(low_percent), float(restore_percent)
        except (TypeError, ValueError, OverflowError):
            return {"ok": False, "error": "法力保留百分比无效"}
        if (not math.isfinite(low) or not math.isfinite(restore) or low < 0 or low > 100 or
                restore < 0 or restore > 100 or restore < low):
            return {"ok": False, "error": "保留阈值需在 0% 到 100%，且补回比例不能低于阈值"}
        if not connected or not pm:
            return {"ok": False, "error": "请先连接游戏"}
        with self._mana_reserve_guard:
            generation = int(self._mana_reserve_state.get("generation", 0)) + 1
            self._mana_reserve_state = {"enabled": True, "low_percent": low,
                                        "restore_percent": restore, "generation": generation}
        session_generation, pm_obj = self._runtime_lock_worker_context()
        if not self._runtime_session_current(session_generation, pm_obj):
            self._stop_mana_reserve_runtime()
            return {"ok": False, "error": "游戏会话已改变，未启动法力保留规则"}
        first = self._mana_reserve_once("启用法力保留规则")
        if not first.get("ok"):
            self._stop_mana_reserve_runtime()
            return first
        self._spawn_runtime_worker(self._mana_reserve_loop,
                                   args=(generation, session_generation, pm_obj),
                                   name="ctw-mana-reserve")
        return {"ok": True, "enabled": True, "low_percent": low, "restore_percent": restore,
                "first": first, "message": "本局法力保留已启用；关闭修改器或断开连接后自动停止"}

    def get_mana_control_state(self):
        pair = self._read_mana_pair() if connected and pm else None
        with self._mana_reserve_guard:
            reserve = dict(self._mana_reserve_state)
            reserve.pop("generation", None)
            reserve["interval"] = self.MANA_RESERVE_INTERVAL
        if connected and pm and not pair:
            return {"ok": False, "state": self.STATUS_STALE, "data": None,
                    "error": "法力读取失败，未以 0 或旧值代替"}
        return {"ok": True, "state": self.STATUS_VERIFIED if pair else self.STATUS_DISCONNECTED,
                "current": pair[0] if pair else None, "maximum": pair[1] if pair else None,
                "reserve": reserve,
                "max_presets": {"普通": 100.0, "法师": 1000.0, "高法力测试": 9999.0},
                "spell_lab": {"state": self.STATUS_UNVERIFIED,
                               "message": "尚未重新定位施法扣蓝与回复调用链；不会显示不可用的倍率或免耗蓝开关。"}}

    def _clean_mana_max_lock(self, state):
        if not isinstance(state, dict) or not state.get("enabled"):
            return {"enabled": False, "target": None}
        try:
            target = float(state.get("target"))
        except (TypeError, ValueError):
            return {"enabled": False, "target": None}
        if not math.isfinite(target) or target <= 0 or target > self.MANA_MAX_LOCK_LIMIT:
            return {"enabled": False, "target": None}
        return {"enabled": True, "target": target}

    def _set_mana_max_lock_runtime(self, enabled, target):
        with self._mana_max_lock_guard:
            self._mana_max_lock_generation += 1
            generation = self._mana_max_lock_generation
            self._mana_max_lock_enabled = bool(enabled)
            self._mana_max_lock_target = float(target) if enabled else None
        if enabled:
            session_generation, pm_obj = self._runtime_lock_worker_context()
            self._spawn_runtime_worker(self._mana_max_lock_loop,
                                       args=(generation, session_generation, pm_obj),
                                       name="ctw-mana-max-lock")

    def _mana_max_lock_loop(self, generation, session_generation, pm_obj):
        while self._runtime_session_current(session_generation, pm_obj):
            with self._mana_max_lock_guard:
                if generation != self._mana_max_lock_generation or not self._mana_max_lock_enabled:
                    return
                target = self._mana_max_lock_target
            try:
                with self._memory_write_lock:
                    if not self._runtime_session_current(session_generation, pm_obj):
                        return
                    if not self.write_mana_max(target):
                        return
            except Exception:
                return
            time.sleep(self.MANA_MAX_LOCK_INTERVAL)

    def _restore_mana_max_lock(self):
        state = self._clean_mana_max_lock(self._read_config().get("mana_max_lock"))
        self._set_mana_max_lock_runtime(state["enabled"], state["target"])

    def get_mana_max_lock(self):
        with self._mana_max_lock_guard:
            return {"ok": True, "enabled": self._mana_max_lock_enabled,
                    "target": self._mana_max_lock_target}

    def set_mana_max_lock(self, enabled, target=None):
        enabled = bool(enabled)
        state = self._clean_mana_max_lock({"enabled": enabled, "target": target})
        if enabled and not state["enabled"]:
            return {"ok": False, "error": "法力上限必须是大于 0 的有效数值"}
        if state["enabled"] and not self.write_mana_max(state["target"]):
            return {"ok": False, "error": "无法写入法力上限"}
        if not self._update_config(lambda cfg: cfg.update({"mana_max_lock": state})):
            return {"ok": False, "error": "无法保存法力上限锁定"}
        self._set_mana_max_lock_runtime(state["enabled"], state["target"])
        return {"ok": True, **state}

    def read_xp(self):
        """读取经验值、等级和下一级所需经验；失败返回 ``None``。"""
        try:
            if self._detect_v2():
                p = pm.read_int(get_base() + V2_XP_OFFSET)
                if p:
                    xv = pm.read_int(p + 0x10)
                    lv = pm.read_int(p + 0x0C)
                    ss = pm.read_int(p + 0x14)
                    if xv is None or lv is None or not (0 < int(lv) <= 9999):
                        return None
                    nv = 0
                    if ss:
                        nv = pm.read_int(ss + 0x1C)
                        if nv is None:
                            return None
                    if int(xv) < 0 or int(nv) < 0:
                        return None
                    return "%d|%d|%d" % (int(xv), int(lv), int(nv))
            p=pm.read_int(get_base()+0xDC3618)
            if not p:
                return None
            xv=pm.read_int(p+0x10);lv=pm.read_int(p+0x0C)
            if xv is None or lv is None or not (0 < int(lv) <= 9999):
                return None
            lt=pm.read_int(p+0x14);nv=0
            if lt and lt>0x100000:
                nv=pm.read_int(lt+int(lv)*12+4)
                if nv is None:
                    return None
            if int(xv) < 0 or int(nv) < 0:
                return None
            return "%d|%d|%d"%(int(xv),int(lv),int(nv))
        except Exception:
            return None

    def write_xp(self,val):
        """写入经验值"""
        try:
            if self._detect_v2():
                p = pm.read_int(get_base() + V2_XP_OFFSET)
                if p:
                    pm.write_int(p + 0x10, int(val))
                    return True
            p=pm.read_int(get_base()+0xDC3618)
            if not p: return False
            pm.write_int(p+0x10,int(val));return True
        except: return False

    def xp_to_next(self):
        """通过游戏原生 AddExp 补足到下一等级。"""
        return self.xp_apply_progress("next")

    # ==================== 等级 / 经验进度控制（V1.0） ====================

    def _read_xp_control_state(self):
        raw = self.read_xp()
        if not raw:
            return None, "经验对象未读取到"
        try:
            xp, level, next_xp = (int(part) for part in str(raw).split("|", 2))
        except (TypeError, ValueError):
            return None, "经验结构解析失败"
        if xp < 0 or level < 1 or next_xp <= 0:
            return None, "经验数值校验失败"
        state = {"xp": xp, "level": level, "next_xp": next_xp,
                 "level_start_xp": 0, "progress_percent": None,
                 "remaining": max(0, next_xp - xp), "target_supported": False,
                 "max_level": None, "thresholds": {}}
        if self._detect_v2():
            # The V2 build currently exposes the next threshold but its whole
            # level table is not confirmed. It can safely use next-level and
            # current-XP controls, not arbitrary target-level lookup yet.
            state["progress_percent"] = max(0.0, min(100.0, xp * 100.0 / next_xp))
            return state, ""
        try:
            pointer = pm.read_int(get_base() + 0xDC3618)
            table = pm.read_int(pointer + 0x14) if pointer else 0
            if not table or int(table) < 0x10000:
                return state, "等级表尚未读取到"
            thresholds = {0: 0}
            previous = 0
            # Each 12-byte row stores the cumulative XP threshold at +4.
            # Stop on a zero/decreasing entry instead of inventing a maximum.
            for index in range(1, 1000):
                value = pm.read_int(int(table) + index * 12 + 4)
                if value is None:
                    break
                value = int(value)
                if value <= previous:
                    break
                thresholds[index] = value
                previous = value
            if not thresholds.get(level):
                return state, "当前等级超出已识别经验表"
            start = thresholds.get(level - 1, 0)
            next_threshold = thresholds.get(level, next_xp)
            if next_threshold <= start:
                return state, "当前等级经验区间无效"
            state.update({"next_xp": next_threshold, "level_start_xp": start,
                          "remaining": max(0, next_threshold - xp),
                          "progress_percent": max(0.0, min(100.0, (xp - start) * 100.0 / (next_threshold - start))),
                          "target_supported": True,
                          "max_level": max(thresholds), "thresholds": thresholds})
            return state, ""
        except Exception as exc:
            return state, "等级表读取失败：%s" % exc

    def _xp_progress_transaction(self, target_xp, source):
        try:
            target_xp = int(target_xp)
        except (TypeError, ValueError, OverflowError):
            return {"ok": False, "error": "目标经验无效"}
        if target_xp < 0 or target_xp > 0x7FFFFFFF:
            return {"ok": False, "error": "目标经验超出允许范围"}
        if not connected or not pm:
            return {"ok": False, "error": "请先连接游戏"}
        with self._memory_write_lock:
            generation, pm_obj = self._runtime_lock_worker_context()
            if not self._runtime_session_current(generation, pm_obj):
                return {"ok": False, "error": "游戏连接已失效，请重新连接"}
            hnd = self._suspend(pm_obj.process_id)
            if not hnd:
                return {"ok": False, "error": "无法暂停游戏以安全写入经验"}
            try:
                before, error = self._read_xp_control_state()
                if not before:
                    return {"ok": False, "error": error}
                if int(before["xp"]) == target_xp:
                    return {"ok": True, "changed": False, "before": before, "after": before,
                            "message": "经验无需变化"}
                if not self.write_xp(target_xp):
                    return {"ok": False, "error": "经验写入失败"}
                after, after_error = self._read_xp_control_state()
                if not after or int(after["xp"]) != target_xp:
                    self.write_xp(int(before["xp"]))
                    return {"ok": False, "error": "经验写后读回不一致，已恢复写前数值：%s" % after_error}
            finally:
                self._resume(hnd)
        return {"ok": True, "changed": True, "before": before, "after": after,
                "readback_ok": True, "source": str(source or "经验进度操作")}

    def _native_xp_to_target_transaction(self, target_xp, source):
        """Reach an XP target by queuing the game's own CharLevels::AddExp.

        This deliberately supports only upward moves.  Lowering XP or changing
        an in-level percentage remains a direct, paused transaction because
        the game has no corresponding negative-AddExp path.  A native request
        checks the live object, module code signature and snapshot immediately
        before it reaches the real game update thread.
        """
        try:
            target_xp = int(target_xp)
        except (TypeError, ValueError, OverflowError):
            return {"ok": False, "error": "目标经验无效"}
        if not connected or not pm:
            return {"ok": False, "error": "请先连接游戏"}
        if self._detect_v2():
            return {"ok": False, "error": "当前原生等级结算仅已定位 Steam 原版；巨龙版不会回退为直接写阈值"}
        if target_xp < 1 or target_xp > 0x7FFFFFFF:
            return {"ok": False, "error": "目标经验超出允许范围"}
        with self._wave_portal_lock, self._memory_write_lock:
            generation, pm_obj = self._runtime_lock_worker_context()
            if not self._runtime_session_current(generation, pm_obj):
                return {"ok": False, "error": "游戏连接已失效，请重新连接"}
            before, error = self._read_xp_control_state()
            if not before:
                return {"ok": False, "error": error}
            old_xp = int(before["xp"])
            if target_xp <= old_xp:
                return {"ok": False, "error": "原生经验结算只支持增加经验"}
            raw_amount = target_xp - old_xp
            try:
                base = int(get_base())
                levels = int(pm_obj.read_int(base + 0xDC3618) or 0)
                expected_vtable = base + self.V1_CHAR_LEVELS_VTABLE_RVA
                add_exp_addr = base + self.V1_CHAR_LEVELS_ADD_EXP_RVA
                if levels < 0x10000 or int(pm_obj.read_int(levels) or 0) != expected_vtable:
                    return {"ok": False, "error": "等级对象校验失败，请重新连接游戏"}
                if pm_obj.read_bytes(add_exp_addr, len(self.V1_CHAR_LEVELS_ADD_EXP_PREFIX)) != self.V1_CHAR_LEVELS_ADD_EXP_PREFIX:
                    return {"ok": False, "error": "原生经验结算函数签名不匹配，当前版本不会执行"}
                controller, controller_error = self._ensure_wave_portal_controller()
                if not controller:
                    return {"ok": False, "error": controller_error}
                data = int(controller["data"])
                request = data + self.XP_NATIVE_QUEUE_REQUEST_OFF
                if int(pm_obj.read_int(request) or 0):
                    return {"ok": False, "error": "已有原生经验结算请求正在等待游戏处理"}
                # Fill the complete immutable request first.  request=1 is the
                # final publication step observed by the update-thread hook.
                pm_obj.write_int(data + self.XP_NATIVE_QUEUE_THIS_OFF, levels)
                pm_obj.write_int(data + self.XP_NATIVE_QUEUE_RAW_AMOUNT_OFF, raw_amount)
                pm_obj.write_int(data + self.XP_NATIVE_QUEUE_BEFORE_OFF, old_xp)
                pm_obj.write_int(data + self.XP_NATIVE_QUEUE_AFTER_OFF, 0)
                pm_obj.write_int(data + self.XP_NATIVE_QUEUE_RESULT_OFF, 0)
                pm_obj.write_int(request, 1)
            except Exception as exc:
                return {"ok": False, "error": "提交原生经验结算请求失败：%s" % exc}

        # The hook normally consumes the request in the next update.  A paused
        # game is reported as queued instead of being misreported as a failed
        # write; after the game resumes the next normal refresh reads the truth.
        deadline = time.monotonic() + 1.2
        while time.monotonic() < deadline:
            try:
                result = int(pm_obj.read_int(data + self.XP_NATIVE_QUEUE_RESULT_OFF) or 0)
                if result == 1:
                    after, after_error = self._read_xp_control_state()
                    if not after:
                        return {"ok": False, "error": "原生经验处理已返回，但读回失败：%s" % after_error}
                    if int(after["xp"]) <= old_xp:
                        return {"ok": False, "error": "游戏已执行原生经验处理，但经验没有增加"}
                    return {"ok": True, "changed": True, "native": True,
                            "readback_ok": True, "source": str(source or "原生经验结算"),
                            "before": before, "after": after,
                            "requested_xp": target_xp, "raw_amount": raw_amount,
                            "message": "已通过游戏原生经验结算处理；等级动画、奖励与相关刷新由游戏自身触发。"}
            except Exception as exc:
                return {"ok": False, "error": "等待原生经验结算结果失败：%s" % exc}
            time.sleep(0.025)
        return {"ok": True, "changed": True, "queued": True, "native": True,
                "source": str(source or "原生经验结算"), "before": before,
                "requested_xp": target_xp, "raw_amount": raw_amount,
                "message": "原生经验结算已排入游戏线程；恢复游戏后会按正常流程升级。"}

    def xp_apply_progress(self, action, value=None):
        state, error = self._read_xp_control_state()
        if not state:
            return {"ok": False, "error": error}
        action = str(action or "").lower()
        xp, level, start, next_xp = (int(state["xp"]), int(state["level"]),
                                     int(state["level_start_xp"]), int(state["next_xp"]))
        if action == "next":
            target, label = next_xp, "设置为下一等级阈值"
        elif action == "next_minus_one":
            target, label = max(start, next_xp - 1), "设置为差 1 点经验升级"
        elif action == "level_start":
            target, label = start, "设置为本级 0% 进度"
        elif action == "progress":
            try: percent = float(value)
            except (TypeError, ValueError, OverflowError): return {"ok": False, "error": "经验进度百分比无效"}
            if not math.isfinite(percent) or percent < 0 or percent > 99:
                return {"ok": False, "error": "经验进度需在 0% 到 99% 之间"}
            target, label = int(round(start + (next_xp - start) * percent / 100.0)), "设置当前等级进度"
            target = min(target, next_xp - 1)
        elif action in ("level", "add_levels", "max_level"):
            if not state.get("target_supported"):
                return {"ok": False, "error": "当前版本尚未定位完整等级表，只支持本级进度与下一等级操作"}
            if action == "level":
                try: desired = int(value)
                except (TypeError, ValueError, OverflowError): return {"ok": False, "error": "目标等级无效"}
            elif action == "add_levels":
                try: desired = level + int(value)
                except (TypeError, ValueError, OverflowError): return {"ok": False, "error": "等级增量无效"}
            else:
                desired = int(state["max_level"])
            maximum = int(state["max_level"])
            if desired < 1 or desired > maximum:
                return {"ok": False, "error": "目标等级需在 1 到 %d 之间" % maximum}
            target = 0 if desired <= 1 else int(state["thresholds"].get(desired - 1, -1))
            if target < 0:
                return {"ok": False, "error": "未读取到目标等级的经验阈值"}
            label = "设置目标等级 %d（0%% 进度）" % desired
        else:
            return {"ok": False, "error": "未知经验进度操作"}
        # An upward level operation must go through CharLevels::AddExp rather
        # than direct XP storage.  This is the only path that immediately
        # runs the game's level-up animation and event/reward refresh.
        native_actions = ("next", "level", "add_levels", "max_level")
        if action in native_actions and target > xp:
            result = self._native_xp_to_target_transaction(target, label)
        else:
            result = self._xp_progress_transaction(target, label)
        if result.get("ok"):
            result["preview"] = {"target_xp": target, "requested_action": action,
                                  "expected_level": level if action not in ("level", "add_levels", "max_level") else desired}
            result["native_level_refresh"] = bool(result.get("native"))
            if result.get("native"):
                result["note"] = result.get("message") or "已走游戏原生经验结算流程。"
            else:
                result["note"] = "当前等级内的进度/降级操作按安全事务写入经验存储值；它不会伪装成原生升级。"
        return result

    def get_xp_control_state(self):
        state, error = self._read_xp_control_state() if connected and pm else (None, "未连接游戏")
        if connected and pm and not state:
            return {"ok": False, "state": self.STATUS_STALE, "data": None,
                    "error": "经验读取失败，未以 0 或旧值代替：%s" % error}
        return {"ok": True, "state": self.STATUS_VERIFIED if state else self.STATUS_DISCONNECTED,
                "data": state, "error": error or "",
                "advanced": {"state": self.STATUS_UNVERIFIED,
                             "message": "经验获得函数、来源区分与原生等级刷新尚未抓取；不会提供无效倍率/暂停开关。"}}

    def _read_wave_countdown_seconds(self, attempts=3):
        """Read the wave countdown across brief map/object initialization gaps.

        The wave controller pointer can be unavailable for a few frames while a
        save is entering the map. A transient failure must not be reported as a
        zero countdown or overwrite the UI's last verified value.
        """
        last_error = "怪物波次尚未初始化"
        tries = max(1, int(attempts or 1))
        for attempt in range(tries):
            try:
                is_v2 = bool(self._detect_v2())
                base = int(get_base())
                pointer = pm.read_int(base + (V2_TIMER_OFFSET if is_v2 else 0xDC8858))
                if not pointer or int(pointer) <= 0x10000:
                    raise RuntimeError("怪物波次对象尚未加载")
                seconds = float(pm.read_float(int(pointer) + (V2_TIMER_PTR if is_v2 else 0x24)))
                if not math.isfinite(seconds) or seconds < 0:
                    raise RuntimeError("倒计时数值校验失败")
                return seconds, ""
            except Exception as exc:
                last_error = str(exc) or last_error
                if attempt + 1 < tries:
                    time.sleep(0.03)
        return None, last_error

    def read_timer(self):
        """读取当前倒计时；失败必须显式返回 ``None``。"""
        seconds, _ = self._read_wave_countdown_seconds()
        if seconds is None:
            return None
        whole = int(seconds)
        return "%d:%02d" % (whole // 60, whole % 60)

    def get_basic_state(self):
        """Read the four basic values without using zero as a failure sentinel."""
        values = {'gold': None, 'mana': None, 'xp': None, 'timer': None}
        errors = {}
        if not pm or not connected:
            for field in values:
                errors[field] = '未连接游戏'
            return {'ok': False, 'state': self.STATUS_DISCONNECTED, 'values': values, 'errors': errors}
        try:
            is_v2 = bool(self._detect_v2())
            base = int(get_base())
            if base <= 0x10000:
                raise RuntimeError('游戏模块基址无效')
        except Exception as exc:
            for field in values:
                errors[field] = '无法确认游戏版本：%s' % exc
            return {'ok': False, 'state': self.STATUS_UNSUPPORTED, 'values': values, 'errors': errors}
        try:
            pointer = self._v2_gold_ptr() if is_v2 else self.gp()
            if not pointer or int(pointer) <= 0x10000:
                raise RuntimeError('金币对象未加载')
            gold = int(self.read_gold())
            if gold < 0 or gold > 0xFFFFFFFF:
                raise RuntimeError('金币数值校验失败')
            values['gold'] = str(gold)
        except Exception as exc:
            errors['gold'] = '金币未识别：%s' % exc
        try:
            pointer = (pm.read_int(base + V2_MANAGER_ARRAY + V2_MANA_OBJ_INDEX)
                       if is_v2 else pm.read_int(base + 0xDC3628))
            if not pointer or int(pointer) <= 0x10000:
                raise RuntimeError('法力对象未加载')
            current, maximum = (float(part) for part in self.read_mana().split('|', 1))
            if (not math.isfinite(current) or not math.isfinite(maximum)
                    or current < 0 or maximum <= 0 or current > 100000000 or maximum > 100000000):
                raise RuntimeError('法力数值校验失败')
            values['mana'] = '%.1f|%.1f' % (current, maximum)
        except Exception as exc:
            errors['mana'] = '法力未识别：%s' % exc
        try:
            pointer = pm.read_int(base + (V2_XP_OFFSET if is_v2 else 0xDC3618))
            if not pointer or int(pointer) <= 0x10000:
                raise RuntimeError('经验对象未加载')
            xp, level, next_xp = (int(part) for part in self.read_xp().split('|', 2))
            if xp < 0 or level < 0 or level > 9999 or next_xp < 0:
                raise RuntimeError('经验数值校验失败')
            values['xp'] = '%d|%d|%d' % (xp, level, next_xp)
        except Exception as exc:
            errors['xp'] = '经验未识别：%s' % exc
        try:
            seconds, timer_error = self._read_wave_countdown_seconds()
            if seconds is None:
                raise RuntimeError(timer_error)
            # A save may contain a countdown much larger than one in-game week.
            # It is still safe to display as long as it is finite and non-negative.
            whole = int(seconds)
            values['timer'] = '%d:%02d' % (whole // 60, whole % 60)
        except Exception as exc:
            errors['timer'] = '倒计时未识别：%s' % exc
        return {'ok': not errors,
                'state': self.STATUS_VERIFIED if not errors else self.STATUS_STALE,
                'values': values, 'errors': errors}

    def get_wave_countdown_state(self):
        """Read only the live red-door countdown for the 0.5-second UI tick.

        The basic-state endpoint also reads gold, mana and experience.  Using
        it for a real-time countdown made the whole top panel refresh at the
        same frequency and caused avoidable UI churn.  This lightweight read
        leaves those unrelated values on their normal cadence.
        """
        if not pm or not connected:
            return {'ok': False, 'state': self.STATUS_DISCONNECTED,
                    'seconds': None, 'text': None, 'error': '未连接游戏'}
        seconds, error = self._read_wave_countdown_seconds(attempts=1)
        if seconds is None:
            return {'ok': False, 'state': self.STATUS_STALE,
                    'seconds': None, 'text': None,
                    'error': error or '红门倒计时未识别'}
        whole = int(seconds)
        return {'ok': True, 'state': self.STATUS_VERIFIED,
                'seconds': float(seconds),
                'text': '%d:%02d' % (whole // 60, whole % 60),
                'error': ''}

    def write_timer(self, seconds):
        """Set the live monster-wave countdown and verify it after resume.

        The old version returned ``True`` as soon as ``WriteProcessMemory``
        accepted the bytes.  MonstersWaves can update the same field on the
        next game frame, so that was not evidence that the game retained the
        requested countdown.  A paused transaction plus a post-resume read is
        required before the UI may report success.
        """
        try:
            seconds = float(seconds)
        except (TypeError, ValueError):
            return {"ok": False, "error": "倒计时必须是有效数字"}
        if not math.isfinite(seconds) or seconds < 0:
            return {"ok": False, "error": "倒计时必须是不小于 0 的有效数字"}
        if not pm or not connected:
            return {"ok": False, "error": "未连接游戏"}

        hnd = self._suspend(pm.process_id)
        if hnd is None:
            return {"ok": False, "error": "无法暂停游戏以安全修改红门倒计时"}
        try:
            is_v2 = bool(self._detect_v2())
            pointer = pm.read_int(get_base() + (V2_TIMER_OFFSET if is_v2 else self.WAVE_PORTAL_MANAGER_RVA))
            if not pointer or int(pointer) <= 0x10000:
                return {"ok": False, "error": "红门波次对象尚未加载"}
            timer_offset = V2_TIMER_PTR if is_v2 else 0x24
            address = int(pointer) + timer_offset
            before = pm.read_float(address)
            if before is None or not math.isfinite(float(before)) or float(before) < 0:
                return {"ok": False, "error": "红门倒计时对象校验失败"}
            pm.write_float(address, seconds)
            immediate = pm.read_float(address)
            if immediate is None or abs(float(immediate) - seconds) > 0.05:
                return {"ok": False, "error": "红门倒计时写入读回失败"}
        except Exception as exc:
            return {"ok": False, "error": "修改红门倒计时失败：%s" % exc}
        finally:
            self._resume(hnd)

        # Let one normal game update run, then prove that the live wave still
        # carries the requested value.  A small tolerance covers elapsed frame
        # time without hiding a native overwrite back to the old countdown.
        time.sleep(0.08)
        actual, error = self._read_wave_countdown_seconds(attempts=2)
        if actual is None:
            return {"ok": False, "error": "倒计时写入后无法复读：%s" % error}
        if abs(float(actual) - seconds) > 1.5:
            return {"ok": False, "error": "游戏未保留新的红门倒计时（当前 %.1f 秒）" % float(actual)}
        return {"ok": True, "timer": float(actual), "before": float(before)}

    # ==================== 倒计时 / 时间 / 速度运行时锁定 ====================
    def _clear_timer_locks(self):
        """Stop all non-persistent timer lock loops for this process."""
        with self._timer_lock_guard:
            for state in self._timer_locks.values():
                state["enabled"] = False
                state["target"] = None
                state["generation"] = int(state.get("generation", 0)) + 1

    def _timer_lock_snapshot(self, kind=None):
        with self._timer_lock_guard:
            if kind is not None:
                state = self._timer_locks.get(str(kind))
                if not state:
                    return None
                return {"enabled": bool(state.get("enabled")), "target": state.get("target"),
                        "generation": int(state.get("generation", 0))}
            return {key: {"enabled": bool(value.get("enabled")), "target": value.get("target")}
                    for key, value in self._timer_locks.items()}

    def get_timer_locks(self):
        """Return current session-only locks for the four time controls."""
        return {"ok": True, "locks": self._timer_lock_snapshot()}

    def _write_countdown_lock_target(self, seconds):
        return self.write_timer(seconds)

    def _write_pandora_timer_cached(self, seconds):
        """Write a previously-validated live spawner without a full rescan."""
        status, error = self._pandora_runtime_state(False)
        if not status or not status.get("spawner"):
            return {"ok": False, "error": error or "未定位潘多拉生成器"}
        hnd = self._suspend(pm.process_id)
        if hnd is None:
            return {"ok": False, "error": "无法暂停游戏以锁定潘多拉倒计时"}
        try:
            runtime, current_error = self._pandora_runtime_state(False)
            if not runtime or int(runtime.get("spawner") or 0) != int(status["spawner"]):
                return {"ok": False, "error": current_error or "潘多拉生成器已变化"}
            address = int(status["timer_address"])
            pm.write_float(address, float(seconds))
            actual = float(pm.read_float(address))
        finally:
            self._resume(hnd)
        if abs(actual - float(seconds)) > 0.05:
            return {"ok": False, "error": "潘多拉倒计时写入未确认"}
        return {"ok": True, "timer": actual}

    def _apply_timer_lock_target(self, kind, target):
        if kind == "countdown":
            return self._write_countdown_lock_target(target)
        if kind == "game_time":
            return self.set_game_time(target)
        if kind == "game_speed":
            return self.set_game_speed(target)
        if kind == "pandora":
            return self._write_pandora_timer_cached(target)
        return {"ok": False, "error": "未知的计时锁定类型"}

    def _timer_lock_loop(self, kind, generation, session_generation, pm_obj):
        failures = 0
        while self._runtime_session_current(session_generation, pm_obj):
            snapshot = self._timer_lock_snapshot(kind)
            if not snapshot or not snapshot["enabled"] or snapshot["generation"] != generation:
                return
            try:
                # Serialise with reconnect/disconnect, then verify again while
                # holding the gate before any helper reads or writes global pm.
                with self._memory_write_lock:
                    if not self._runtime_session_current(session_generation, pm_obj):
                        return
                    result = self._apply_timer_lock_target(kind, snapshot["target"])
            except Exception as exc:
                result = {"ok": False, "error": str(exc)}
            if result.get("ok"):
                failures = 0
            else:
                failures += 1
                if failures >= 3:
                    with self._timer_lock_guard:
                        state = self._timer_locks.get(kind)
                        if (self._runtime_session_current(session_generation, pm_obj) and state and
                                int(state.get("generation", 0)) == generation):
                            state["enabled"] = False
                            state["target"] = None
                            state["generation"] = generation + 1
                    return
            time.sleep(self.TIMER_LOCK_INTERVAL)

    def set_timer_lock(self, kind, enabled, target=None):
        """Lock one UI time control to the supplied value for this session."""
        kind = str(kind or "")
        if kind not in self._timer_locks:
            return {"ok": False, "error": "未知的计时锁定类型"}
        if kind == "pandora":
            blocked = self._require_high_risk_world_write("潘多拉倒计时锁定")
            if blocked:
                return {"ok": False, "error": blocked}
        enabled = bool(enabled)
        if enabled:
            try:
                target = float(target)
            except (TypeError, ValueError):
                return {"ok": False, "error": "锁定值必须是有效数字"}
            limits = {
                "countdown": (0.0, float("inf")), "game_time": (0.0, 36000.0),
                "game_speed": (GAME_SPEED_MIN, GAME_SPEED_MAX), "pandora": (0.1, 604800.0),
            }
            minimum, maximum = limits[kind]
            if not math.isfinite(target) or target < minimum or target > maximum:
                return {"ok": False, "error": "锁定值超出允许范围"}
            # Pandora's spawner may not have been scanned before the first
            # lock request.  Do one normal, validated write first; recurring
            # updates then use the cached address only while it stays valid.
            result = (self.set_pandora_spawn_timer(target)
                      if kind == "pandora" else self._apply_timer_lock_target(kind, target))
            if not result.get("ok"):
                return result
        with self._timer_lock_guard:
            state = self._timer_locks[kind]
            state["generation"] = int(state.get("generation", 0)) + 1
            generation = state["generation"]
            state["enabled"] = enabled
            state["target"] = float(target) if enabled else None
        if enabled:
            session_generation, pm_obj = self._runtime_lock_worker_context()
            if not self._runtime_session_current(session_generation, pm_obj):
                with self._timer_lock_guard:
                    state = self._timer_locks.get(kind)
                    if state and int(state.get("generation", 0)) == generation:
                        state["enabled"] = False
                        state["target"] = None
                        state["generation"] = generation + 1
                return {"ok": False, "error": "游戏会话已改变，未启动计时锁定"}
            self._spawn_runtime_worker(self._timer_lock_loop,
                                       args=(kind, generation, session_generation, pm_obj),
                                       name="ctw-%s-lock" % kind)
        return {"ok": True, "kind": kind, "enabled": enabled,
                "target": float(target) if enabled else None}


    # ==================== 游戏时间与全局速度（当前 Steam 原版） ====================
    def _clear_time_controls_cache(self):
        """Forget dynamic time-object addresses when the process changes."""
        self._time_controls_cache = None
        self._time_controls_last_failed_scan = 0.0
        self._time_controls_scan_error = ""

    def _invalidate_time_controls_cache(self, error=""):
        """Drop a stale map object without treating its old address as reusable."""
        self._time_controls_cache = None
        self._time_controls_last_failed_scan = time.time()
        if error:
            self._time_controls_scan_error = str(error)

    def _start_time_controls_scan(self):
        """Locate time objects in one cancellable worker for this game session.

        The broad heap pass is read-only but can take roughly a second on a
        loaded world.  Running it independently lets the connection finish and
        makes every later refresh a tiny cached read instead of a blocked UI
        request.  Cache publication is still tied to the exact PID/session.
        """
        if not connected or not pm:
            return False
        pm_obj = pm
        try:
            process_id = int(pm_obj.process_id)
            module_base = int(get_base(pm_obj))
        except Exception:
            return False
        with self._runtime_session_lock:
            if self._runtime_shutdown or self._time_controls_scan_running:
                return False
            generation = self._runtime_session_generation
            self._time_controls_scan_token += 1
            scan_token = self._time_controls_scan_token
            self._time_controls_scan_running = True
            self._time_controls_scan_error = ""

        def worker():
            try:
                cache, error = self._scan_time_controls(pm_obj, process_id, module_base)
                with self._runtime_session_lock:
                    if (scan_token != self._time_controls_scan_token or
                            not self._runtime_session_current(generation, pm_obj)):
                        return
                    if cache:
                        self._time_controls_cache = cache
                        self._time_controls_scan_error = ""
                    else:
                        self._time_controls_last_failed_scan = time.time()
                        self._time_controls_scan_error = error or "定位游戏时间对象失败"
            except Exception as exc:
                with self._runtime_session_lock:
                    if (scan_token == self._time_controls_scan_token and
                            self._runtime_session_current(generation, pm_obj)):
                        self._time_controls_last_failed_scan = time.time()
                        self._time_controls_scan_error = str(exc) or "定位游戏时间对象失败"
            finally:
                with self._runtime_session_lock:
                    if scan_token == self._time_controls_scan_token:
                        self._time_controls_scan_running = False

        self._spawn_runtime_worker(worker, name="ctw-time-scan")
        return True

    def _read_time_region_chunks(self, pm_obj, region_base, region_size):
        """Read one suitable region with small fallbacks and a 3-byte overlap."""
        pos = int(region_base)
        end = pos + int(region_size)
        while pos < end:
            chunk = None
            for wanted in (0x800000, 0x200000, 0x10000, 0x1000):
                try:
                    size = min(wanted, end - pos)
                    if size <= 0:
                        break
                    chunk = pm_obj.read_bytes(pos, size)
                    if chunk:
                        break
                except Exception:
                    chunk = None
            if chunk:
                yield pos, chunk
                # Both signatures are four bytes.  The overlap preserves a
                # match that straddles two readable chunks.
                pos += max(len(chunk) - 3, 1)
            else:
                pos += 0x1000

    def _read_time_control_state(self, pm_obj, cache):
        """Read and validate the two already-located runtime objects."""
        try:
            game = int(cache["game"])
            daytime = int(cache["daytime"])
            if pm_obj.read_int(game) != int(cache["game_vtable"]):
                return None
            if pm_obj.read_int(daytime) != int(cache["daytime_vtable"]):
                return None

            # One bulk read per object makes the frame-to-frame snapshot much
            # less likely to mix values from two game updates.
            game_raw = pm_obj.read_bytes(game + int(cache.get("active_off", GAME_SPEED_ACTIVE_OFF)), 0x14)
            active_speed, _unused1, _unused2, _unused3, speed = struct.unpack("<5f", game_raw)
            # Day count and the seven DayTime floats are contiguous.  One
            # read keeps the snapshot coherent and avoids a second cross-
            # process call on every overview/time refresh.
            day_raw = pm_obj.read_bytes(daytime + DAYTIME_DAY_COUNT_OFF, 0x20)
            day_count, current, day_end, sunset_mid, night_begin, night_end, sunrise_mid, cycle = struct.unpack("<I7f", day_raw)
            values = (active_speed, speed, current, day_end, sunset_mid, night_begin, night_end, sunrise_mid, cycle)
            if not all(math.isfinite(value) for value in values):
                return None
            # A paused game can expose zero active speed.  The source field is
            # the player-controlled multiplier and must remain a sensible
            # positive float; no write is ever made to the active cache.
            if active_speed < 0.0 or active_speed > GAME_SPEED_MAX or speed < 0.01 or speed > GAME_SPEED_MAX:
                return None
            bounds = (day_end, sunset_mid, night_begin, night_end, sunrise_mid, cycle)
            if cycle <= 1.0 or cycle > 36000.0 or current < -0.5 or current > cycle + 0.5:
                return None
            if any(value <= 0.0 for value in bounds) or any(bounds[index] > bounds[index + 1] for index in range(len(bounds) - 1)):
                return None

            if current < day_end:
                phase = "白天"
            elif current < night_begin:
                phase = "黄昏"
            elif current < night_end:
                phase = "夜晚"
            else:
                phase = "黎明"
            if day_count < 0 or day_count > 100000000:
                return None
            return {
                "current": float(current), "cycle": float(cycle), "phase": phase,
                "day_count": day_count,
                "speed": float(speed), "active_speed": float(active_speed),
                "bounds": {
                    "day_end": float(day_end), "sunset_mid": float(sunset_mid),
                    "night_begin": float(night_begin), "night_end": float(night_end),
                    "sunrise_mid": float(sunrise_mid), "cycle": float(cycle),
                },
            }
        except Exception:
            return None

    def _is_time_game_candidate(self, pm_obj, address, vtable, active_off=GAME_SPEED_ACTIVE_OFF):
        try:
            if pm_obj.read_int(address) != vtable:
                return False
            raw = pm_obj.read_bytes(address + active_off, 0x14)
            active_speed, _unused1, _unused2, _unused3, speed = struct.unpack("<5f", raw)
            return math.isfinite(active_speed) and math.isfinite(speed) and 0.0 <= active_speed <= GAME_SPEED_MAX and 0.01 <= speed <= GAME_SPEED_MAX
        except Exception:
            return False

    def _is_time_day_candidate(self, pm_obj, address, vtable, active_off=None):
        try:
            if pm_obj.read_int(address) != vtable:
                return False
            raw = pm_obj.read_bytes(address + DAYTIME_CURRENT_OFF, 0x1C)
            current, day_end, sunset_mid, night_begin, night_end, sunrise_mid, cycle = struct.unpack("<7f", raw)
            values = (current, day_end, sunset_mid, night_begin, night_end, sunrise_mid, cycle)
            if not all(math.isfinite(value) for value in values):
                return False
            bounds = values[1:]
            return (1.0 < cycle <= 36000.0 and -0.5 <= current <= cycle + 0.5
                    and all(value > 0.0 for value in bounds)
                    and all(bounds[index] <= bounds[index + 1] for index in range(len(bounds) - 1)))
        except Exception:
            return False

    def _scan_time_controls(self, pm_obj, process_id, module_base):
        """Locate the Game and DayTime heap objects once, without breakpoints."""
        started = time.time()
        is_v2 = self._detect_v2()
        game_vtable = int(module_base) + (V2_GAME_VTABLE_RVA if is_v2 else V1_GAME_VTABLE_RVA)
        daytime_vtable = int(module_base) + (V2_DAYTIME_VTABLE_RVA if is_v2 else V1_DAYTIME_VTABLE_RVA)
        active_off = V2_GAME_SPEED_ACTIVE_OFF if is_v2 else GAME_SPEED_ACTIVE_OFF
        source_off = V2_GAME_SPEED_SOURCE_OFF if is_v2 else GAME_SPEED_SOURCE_OFF
        game_signature = struct.pack("<I", game_vtable)
        daytime_signature = struct.pack("<I", daytime_vtable)
        game_candidates = set()
        daytime_candidates = set()
        writable_protect = {0x04, 0x08, 0x40, 0x80}

        class _MBI(ctypes.Structure):
            _fields_ = [
                ("BaseAddress", ctypes.c_void_p), ("AllocationBase", ctypes.c_void_p),
                ("AllocationProtect", ctypes.c_uint32), ("RegionSize", ctypes.c_size_t),
                ("State", ctypes.c_uint32), ("Protect", ctypes.c_uint32), ("Type", ctypes.c_uint32),
            ]

        kernel32 = ctypes.windll.kernel32
        mbi = _MBI()
        address = 0x10000
        limit = 0x80000000
        while address < limit:
            try:
                queried = kernel32.VirtualQueryEx(pm_obj.process_handle, address, ctypes.byref(mbi), ctypes.sizeof(mbi))
            except Exception:
                queried = 0
            if not queried:
                address += 0x10000
                continue
            region_base = int(mbi.BaseAddress or 0)
            region_size = int(mbi.RegionSize or 0)
            next_address = region_base + region_size
            if next_address <= address:
                address += 0x1000
                continue
            protect = int(mbi.Protect)
            if (mbi.State != 0x1000 or mbi.Type != 0x20000 or protect & 0x100
                    or (protect & 0xFF) not in writable_protect or region_size < 4):
                address = next_address
                continue
            for chunk_address, chunk in self._read_time_region_chunks(pm_obj, region_base, region_size):
                for signature, candidates, validator, vtable in (
                    (game_signature, game_candidates, self._is_time_game_candidate, game_vtable),
                    (daytime_signature, daytime_candidates, self._is_time_day_candidate, daytime_vtable),
                ):
                    pos = 0
                    while True:
                        found = chunk.find(signature, pos)
                        if found < 0:
                            break
                        pos = found + 4
                        candidate = chunk_address + found
                        if candidate in candidates:
                            continue
                        if validator(pm_obj, candidate, vtable, active_off):
                            candidates.add(candidate)
            address = next_address

        if len(game_candidates) != 1 or len(daytime_candidates) != 1:
            return None, "未能唯一定位游戏时间对象（请先进入已载入的地图）"
        cache = {
            "pid": int(process_id), "base": int(module_base),
            "game": next(iter(game_candidates)), "daytime": next(iter(daytime_candidates)),
            "game_vtable": game_vtable, "daytime_vtable": daytime_vtable,
            "active_off": active_off, "source_off": source_off,
            "scan_ms": int((time.time() - started) * 1000),
        }
        first = self._read_time_control_state(pm_obj, cache)
        if not first:
            return None, "游戏时间对象验证失败"
        # Confirm that this is a live object rather than a stale heap remnant.
        time.sleep(0.04)
        second = self._read_time_control_state(pm_obj, cache)
        if not second or any(abs(first["bounds"][key] - second["bounds"][key]) > 0.01 for key in first["bounds"]):
            return None, "地图正在切换，请稍后重试"
        return cache, ""

    def _ensure_time_controls(self):
        if not connected or not pm:
            return None, "请先连接游戏"
        pm_obj = pm
        try:
            process_id = int(pm_obj.process_id)
            module_base = int(get_base(pm_obj))
        except Exception:
            return None, "读取游戏进程信息失败"
        cache = self._time_controls_cache
        if cache and cache.get("pid") == process_id and cache.get("base") == module_base:
            if self._read_time_control_state(pm_obj, cache):
                return cache, ""
            self._invalidate_time_controls_cache("游戏时间对象已失效")
        with self._time_controls_scan_lock:
            if not connected or pm is not pm_obj or int(pm_obj.process_id) != process_id:
                return None, "游戏连接已变化，请重新读取"
            cache = self._time_controls_cache
            if cache and cache.get("pid") == process_id and cache.get("base") == module_base:
                if self._read_time_control_state(pm_obj, cache):
                    return cache, ""
            if self._time_controls_scan_running:
                return None, "正在读取游戏时间，请稍候"
            now = time.time()
            if now - self._time_controls_last_failed_scan < 3.0:
                return None, self._time_controls_scan_error or "正在等待地图时间对象"
            if self._start_time_controls_scan():
                return None, "正在读取游戏时间，请稍候"
            return None, self._time_controls_scan_error or "正在等待游戏时间对象"

    def get_game_time_state(self):
        """Read current day/night time and the global simulation multiplier."""
        if not connected or not pm:
            return {"ok": False, "state": self.STATUS_DISCONNECTED,
                    "error": "请先连接游戏并进入已载入的地图"}
        cache, error = self._ensure_time_controls()
        if not cache:
            # Time and magic use independent caches.  Never report a magic
            # scan as a time read: it only delays the primary time/velocity UI.
            pending_time_scan = bool(self._time_controls_scan_running)
            return {"ok": False,
                    "state": self.STATUS_UNVERIFIED if pending_time_scan else self.STATUS_STALE,
                    "scanning": pending_time_scan,
                    "error": error or "游戏时间对象定位失效"}
        state = self._read_time_control_state(pm, cache)
        if not state:
            self._invalidate_time_controls_cache("游戏时间对象已失效")
            return {"ok": False, "state": self.STATUS_STALE,
                    "error": "游戏时间对象已失效，请重新读取"}
        state.update({"ok": True, "state": self.STATUS_VERIFIED,
                      "scan_ms": cache.get("scan_ms", 0)})
        return state

    def set_game_time(self, seconds):
        """Safely jump inside the current runtime day/night cycle."""
        try:
            seconds = float(seconds)
        except (TypeError, ValueError):
            return {"ok": False, "error": "请输入有效的时间秒数"}
        if not math.isfinite(seconds):
            return {"ok": False, "error": "请输入有限的时间秒数"}
        cache, error = self._ensure_time_controls()
        if not cache:
            return {"ok": False, "error": error}
        before = self._read_time_control_state(pm, cache)
        if not before:
            self._invalidate_time_controls_cache("游戏时间对象已失效")
            return {"ok": False, "error": "游戏时间对象已失效，请重新读取"}
        cycle = before["cycle"]
        if seconds < 0.0 or seconds > cycle:
            return {"ok": False, "error": "当前地图的时间范围为 0 ～ %.1f 秒" % cycle}
        target = min(seconds, max(0.0, cycle - 0.001))
        try:
            pm.write_float(int(cache["daytime"]) + DAYTIME_CURRENT_OFF, target)
            time.sleep(0.08)
        except Exception as e:
            self._invalidate_time_controls_cache(str(e))
            return {"ok": False, "error": "写入游戏时间失败"}
        after = self._read_time_control_state(pm, cache)
        if not after:
            self._invalidate_time_controls_cache("写入后对象失效")
            return {"ok": False, "error": "写入后游戏时间对象失效"}
        difference = abs(after["current"] - target)
        difference = min(difference, abs(difference - cycle))
        tolerance = max(1.0, after["active_speed"] * 0.5 + 0.5)
        if difference > tolerance:
            return {"ok": False, "error": "游戏没有接受新的时间，请在地图内重试"}
        return {"ok": True, "state": after}

    def set_game_speed(self, speed):
        """Set the source multiplier; the game refreshes its active cache itself."""
        try:
            speed = float(speed)
        except (TypeError, ValueError):
            return {"ok": False, "error": "请输入有效的速度倍率"}
        if not math.isfinite(speed) or speed < GAME_SPEED_MIN or speed > GAME_SPEED_MAX:
            return {"ok": False, "error": "全局速度范围为 %.2f ～ %.0f 倍" % (GAME_SPEED_MIN, GAME_SPEED_MAX)}
        cache, error = self._ensure_time_controls()
        if not cache:
            return {"ok": False, "error": error}
        if not self._read_time_control_state(pm, cache):
            self._invalidate_time_controls_cache("游戏时间对象已失效")
            return {"ok": False, "error": "游戏时间对象已失效，请重新读取"}
        try:
            # The lower offset is a frame cache.  Only the source offset is the
            # native control value, so the game refreshes the cache itself.
            pm.write_float(int(cache["game"]) + int(cache.get("source_off", GAME_SPEED_SOURCE_OFF)), speed)
            time.sleep(0.08)
        except Exception as e:
            self._invalidate_time_controls_cache(str(e))
            return {"ok": False, "error": "写入全局速度失败"}
        after = self._read_time_control_state(pm, cache)
        if not after:
            self._invalidate_time_controls_cache("写入后对象失效")
            return {"ok": False, "error": "写入后游戏时间对象失效"}
        if abs(after["speed"] - speed) > 0.02:
            return {"ok": False, "error": "游戏没有接受新的速度，请在地图内重试"}
        return {"ok": True, "state": after}


    # ==================== 矮人人口上限（原生计算覆盖） ====================
    # The verified hook point is immediately after SimpleVariant::ToInt for
    # the ``additional_dwarfs`` parameter.  Replaying these two displaced
    # instructions preserves the rest of DwarfSpawner::UpdateSpawns exactly.
    DWARF_POPULATION_HOOK_RVA = 0x397F23
    DWARF_POPULATION_HOOK_PREFIX = b"\x8B\x4D\xEC\x8B\xF0"
    DWARF_POPULATION_LEVEL_GLOBAL_RVA = 0xDC3618
    DWARF_POPULATION_MIN = 1
    DWARF_POPULATION_MAX = 99
    DWARF_POPULATION_TAG = b"CTWDPCAP1\x00"
    DWARF_POPULATION_TAG_OFF = 0x20
    DWARF_POPULATION_TARGET_OFF = 0x00
    DWARF_POPULATION_ENABLED_OFF = 0x04
    DWARF_POPULATION_OBSERVED_EXTRA_OFF = 0x08
    DWARF_POPULATION_HITS_OFF = 0x0C

    @staticmethod
    def _signed_i32(value):
        value = int(value or 0)
        return value - 0x100000000 if value >= 0x80000000 else value

    def _dwarf_population_layout_error(self):
        if not connected or not pm:
            return "请先连接游戏并进入已加载的存档"
        if self._detect_v2():
            return "矮人上限目前只支持已验证的 Steam 原版"
        layout = self._apply_v1_native_layout()
        # The hook site is verified only for the Steam build used in the
        # population analysis.  Do not infer it from nearby build offsets.
        if not layout.get("recognized") or layout.get("key") != "steam-v1-build-21776357":
            return "当前 CraftWorld.exe 未匹配已验证的矮人人口计算布局"
        return ""

    def _read_dwarf_population_level(self, module_base=None):
        try:
            base = int(module_base if module_base is not None else get_base())
            levels = pm.read_int(base + self.DWARF_POPULATION_LEVEL_GLOBAL_RVA)
            if not levels or int(levels) <= 0x10000:
                return None
            level = self._signed_i32(pm.read_int(int(levels) + 0x0C))
            return level if 0 <= level <= 9999 else None
        except Exception:
            return None

    def _build_dwarf_population_hook(self, module_base, cave_base):
        """Return a tiny detour that alters only UpdateSpawns' EAX result."""
        cave_base = int(cave_base)
        module_base = int(module_base)
        data = cave_base + 0x1000
        target = data + self.DWARF_POPULATION_TARGET_OFF
        enabled = data + self.DWARF_POPULATION_ENABLED_OFF
        observed = data + self.DWARF_POPULATION_OBSERVED_EXTRA_OFF
        hits = data + self.DWARF_POPULATION_HITS_OFF
        level_global = module_base + self.DWARF_POPULATION_LEVEL_GLOBAL_RVA
        code = bytearray()

        def u32(value):
            code.extend(struct.pack("<I", int(value) & 0xFFFFFFFF))

        # Preserve all registers/flags.  The saved EAX slot is at ESP+1C
        # after pushfd + pushad; changing that slot makes popad restore the
        # requested additional_dwarfs value for the original two instructions.
        code.extend(b"\x9C\x60")
        code.extend(b"\x8B\x44\x24\x1C")                 # eax = original extra
        code.extend(b"\xA3"); u32(observed)
        code.extend(b"\xFF\x05"); u32(hits)
        code.extend(b"\x83\x3D"); u32(enabled); code.extend(b"\x01")
        jne_pos = len(code); code.extend(b"\x75\x00")
        code.extend(b"\xA1"); u32(level_global)             # eax = CharLevels*
        code.extend(b"\x85\xC0")
        jz_pos = len(code); code.extend(b"\x74\x00")
        code.extend(b"\x8B\x40\x0C")                       # eax = current level
        code.extend(b"\x8B\x0D"); u32(target)               # ecx = requested cap
        code.extend(b"\x29\xC1")                             # ecx -= level
        code.extend(b"\x89\x4C\x24\x1C")                   # saved eax = extra
        no_override = len(code)
        code[jne_pos + 1] = (no_override - (jne_pos + 2)) & 0xFF
        code[jz_pos + 1] = (no_override - (jz_pos + 2)) & 0xFF
        code.extend(b"\x61\x9D")
        code.extend(self.DWARF_POPULATION_HOOK_PREFIX)
        return_address = module_base + self.DWARF_POPULATION_HOOK_RVA + len(self.DWARF_POPULATION_HOOK_PREFIX)
        code.extend(b"\xE9")
        code.extend(struct.pack("<i", int(return_address) - (cave_base + len(code) + 4)))
        return bytes(code), data

    def _dwarf_population_controller_from_live_hook(self, module_base):
        try:
            site = int(module_base) + self.DWARF_POPULATION_HOOK_RVA
            patch = pm.read_bytes(site, len(self.DWARF_POPULATION_HOOK_PREFIX))
            if not patch or len(patch) != len(self.DWARF_POPULATION_HOOK_PREFIX) or patch[0] != 0xE9:
                return None
            cave = site + 5 + struct.unpack("<i", patch[1:5])[0]
            if not (0x10000 <= cave < 0x80000000):
                return None
            data = cave + 0x1000
            tag = pm.read_bytes(data + self.DWARF_POPULATION_TAG_OFF, len(self.DWARF_POPULATION_TAG))
            if tag != self.DWARF_POPULATION_TAG:
                return None
            return {"pid": int(pm.process_id), "base": int(module_base),
                    "cave": int(cave), "data": int(data), "patch": patch}
        except Exception:
            return None

    def _dispose_dwarf_population_controller(self):
        """Restore our exact population detour before ending this session."""
        with self._dwarf_population_lock:
            controller = self._dwarf_population_controller
            if not controller or not pm:
                return
            try:
                if int(controller.get("pid", 0)) != int(pm.process_id):
                    self._dwarf_population_controller = None
                    return
                site = int(controller["base"]) + self.DWARF_POPULATION_HOOK_RVA
                if pm.read_bytes(site, len(self.DWARF_POPULATION_HOOK_PREFIX)) != controller.get("patch"):
                    return
                hnd = self._suspend(int(pm.process_id))
                if not hnd:
                    return
                try:
                    if pm.read_bytes(site, len(self.DWARF_POPULATION_HOOK_PREFIX)) != controller.get("patch"):
                        return
                    pm.write_bytes(site, self.DWARF_POPULATION_HOOK_PREFIX,
                                   len(self.DWARF_POPULATION_HOOK_PREFIX))
                    if pm.read_bytes(site, len(self.DWARF_POPULATION_HOOK_PREFIX)) == self.DWARF_POPULATION_HOOK_PREFIX:
                        self._dwarf_population_controller = None
                finally:
                    self._resume(hnd)
            except Exception as exc:
                _diagnostic("dwarf population controller cleanup:", exc)

    def _ensure_dwarf_population_controller(self):
        error = self._dwarf_population_layout_error()
        if error:
            return None, error
        try:
            process_id = int(pm.process_id)
            module_base = int(get_base())
        except Exception:
            return None, "无法读取游戏进程信息"
        with self._dwarf_population_lock:
            current = self._dwarf_population_controller
            site = module_base + self.DWARF_POPULATION_HOOK_RVA
            if current and int(current.get("pid", 0)) == process_id and int(current.get("base", 0)) == module_base:
                if pm.read_bytes(site, len(self.DWARF_POPULATION_HOOK_PREFIX)) == current.get("patch"):
                    return current, ""
                self._dwarf_population_controller = None
            try:
                raw = pm.read_bytes(site, len(self.DWARF_POPULATION_HOOK_PREFIX))
                if raw != self.DWARF_POPULATION_HOOK_PREFIX:
                    stale = self._dwarf_population_controller_from_live_hook(module_base)
                    if not stale:
                        return None, "矮人人口计算代码与已验证版本不一致，请重启游戏后再试"
                    hnd = self._suspend(process_id)
                    if not hnd:
                        return None, "无法暂停游戏以恢复旧的人口控制器"
                    try:
                        if pm.read_bytes(site, len(self.DWARF_POPULATION_HOOK_PREFIX)) != stale["patch"]:
                            return None, "旧的人口控制器状态已变化，请重启游戏后再试"
                        pm.write_bytes(site, self.DWARF_POPULATION_HOOK_PREFIX,
                                       len(self.DWARF_POPULATION_HOOK_PREFIX))
                        if pm.read_bytes(site, len(self.DWARF_POPULATION_HOOK_PREFIX)) != self.DWARF_POPULATION_HOOK_PREFIX:
                            return None, "恢复旧的人口控制器失败"
                    finally:
                        self._resume(hnd)
                cave = pymem.memory.allocate_memory(pm.process_handle, 0x2000)
                code, data = self._build_dwarf_population_hook(module_base, cave)
                pm.write_bytes(cave, code, len(code))
                pm.write_bytes(data, b"\x00" * 0x100, 0x100)
                pm.write_bytes(data + self.DWARF_POPULATION_TAG_OFF,
                               self.DWARF_POPULATION_TAG, len(self.DWARF_POPULATION_TAG))
                patch = self._wave_portal_jump(site, cave, len(self.DWARF_POPULATION_HOOK_PREFIX))
                hnd = self._suspend(process_id)
                if not hnd:
                    return None, "无法暂停游戏以安全安装人口控制器"
                try:
                    if pm.read_bytes(site, len(self.DWARF_POPULATION_HOOK_PREFIX)) != self.DWARF_POPULATION_HOOK_PREFIX:
                        return None, "人口计算代码在安装前已变化"
                    pm.write_bytes(site, patch, len(patch))
                    if pm.read_bytes(site, len(patch)) != patch:
                        pm.write_bytes(site, self.DWARF_POPULATION_HOOK_PREFIX,
                                       len(self.DWARF_POPULATION_HOOK_PREFIX))
                        return None, "安装人口控制器失败，已恢复原代码"
                finally:
                    self._resume(hnd)
                controller = {"pid": process_id, "base": module_base, "cave": cave,
                              "data": data, "patch": patch}
                self._dwarf_population_controller = controller
                return controller, ""
            except Exception as exc:
                _diagnostic("dwarf population controller install:", exc)
                return None, "安装矮人人口控制器失败：%s" % exc

    def _wait_dwarf_population_sample(self, controller, previous_hits, timeout=0.8):
        deadline = time.monotonic() + float(timeout)
        hits_addr = int(controller["data"]) + self.DWARF_POPULATION_HITS_OFF
        while time.monotonic() < deadline:
            try:
                hits = int(pm.read_int(hits_addr) or 0)
                if hits > int(previous_hits):
                    return hits
            except Exception:
                return None
            time.sleep(0.04)
        return None

    def get_dwarf_population_cap_state(self):
        """Read the native level + additional_dwarfs calculation safely."""
        with self._dwarf_population_lock:
            controller, error = self._ensure_dwarf_population_controller()
            if not controller:
                return {"ok": False, "state": self.STATUS_UNSUPPORTED, "error": error}
            level = self._read_dwarf_population_level(controller["base"])
            if level is None:
                return {"ok": False, "state": self.STATUS_STALE, "error": "当前等级对象未准备好"}
            data = int(controller["data"])
            try:
                hits_before = int(pm.read_int(data + self.DWARF_POPULATION_HITS_OFF) or 0)
            except Exception:
                hits_before = 0
            hits = hits_before or self._wait_dwarf_population_sample(controller, 0)
            if not hits:
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "正在等待游戏原生人口计算，请稍后刷新"}
            try:
                enabled = int(pm.read_int(data + self.DWARF_POPULATION_ENABLED_OFF) or 0) == 1
                target = self._signed_i32(pm.read_int(data + self.DWARF_POPULATION_TARGET_OFF))
                additional = self._signed_i32(pm.read_int(data + self.DWARF_POPULATION_OBSERVED_EXTRA_OFF))
                current_limit = target if enabled else level + additional
                if current_limit < 0 or current_limit > self.DWARF_POPULATION_MAX:
                    return {"ok": False, "state": self.STATUS_STALE,
                            "error": "人口上限读回超出可信范围"}
                return {"ok": True, "state": self.STATUS_VERIFIED,
                        "current_limit": int(current_limit), "base_level": int(level),
                        "additional_dwarfs": int(additional), "override_enabled": enabled,
                        "target": int(target) if enabled else None}
            except Exception as exc:
                return {"ok": False, "state": self.STATUS_STALE,
                        "error": "读取矮人上限失败：%s" % exc}

    def set_dwarf_population_cap(self, target):
        """Keep the requested absolute cap across level changes this session."""
        try:
            target = int(target)
        except (TypeError, ValueError):
            return {"ok": False, "error": "矮人上限必须是整数"}
        if target < self.DWARF_POPULATION_MIN or target > self.DWARF_POPULATION_MAX:
            return {"ok": False, "error": "矮人上限范围为 %d～%d" %
                    (self.DWARF_POPULATION_MIN, self.DWARF_POPULATION_MAX)}
        with self._dwarf_population_lock:
            controller, error = self._ensure_dwarf_population_controller()
            if not controller:
                return {"ok": False, "error": error}
            level = self._read_dwarf_population_level(controller["base"])
            if level is None:
                return {"ok": False, "error": "当前等级对象未准备好"}
            data = int(controller["data"])
            try:
                hits_before = int(pm.read_int(data + self.DWARF_POPULATION_HITS_OFF) or 0)
                # Publish target first; enabling it last prevents the game
                # thread from observing a partly-written request.
                pm.write_int(data + self.DWARF_POPULATION_ENABLED_OFF, 0)
                pm.write_int(data + self.DWARF_POPULATION_TARGET_OFF, target)
                pm.write_int(data + self.DWARF_POPULATION_ENABLED_OFF, 1)
                if (int(pm.read_int(data + self.DWARF_POPULATION_TARGET_OFF) or -1) != target or
                        int(pm.read_int(data + self.DWARF_POPULATION_ENABLED_OFF) or 0) != 1):
                    return {"ok": False, "error": "人口上限控制器写入读回失败"}
            except Exception as exc:
                return {"ok": False, "error": "提交矮人上限失败：%s" % exc}
            if not self._wait_dwarf_population_sample(controller, hits_before):
                return {"ok": False, "error": "游戏未执行人口计算，请稍后重试"}
            return {"ok": True, "state": self.STATUS_VERIFIED, "current_limit": target,
                    "base_level": level, "additional_dwarfs": target - level,
                    "override_enabled": True}


    # ==================== 怪物传送门 ====================
    # These RVAs were verified against the current 32-bit Steam build.  They
    # are deliberately kept module-relative: CraftWorld.exe is ASLR-enabled.
    WAVE_PORTAL_MANAGER_RVA = 0xDC8858
    # MonstersWaves::Update(float).  ``_RVA`` is the installed-detour site;
    # ``_ENTRY_RVA`` is its real function entry and is used only from our
    # always-running main-thread dispatcher with a zero delta-time.
    WAVE_PORTAL_UPDATE_ENTRY_RVA = 0x5B9890
    WAVE_PORTAL_UPDATE_RVA = 0x5B98C5
    # A tiny virtual duration getter called continuously by the live game.
    # Unlike MonstersWaves::Update, it remains active while no monster wave
    # is scheduled, so it is used only for personal-skill queue dispatch.
    PERSONAL_SKILL_TICK_RVA = 0x1FFBC0
    WAVE_PORTAL_DAY_CLOSE_RVA = 0x5B990B
    WAVE_PORTAL_CLOSE_POST_RVA = 0x5B6446
    # HellPortalEntity::SlowUpdate after its first relocated global load.  This
    # site is invoked by each live portal while the wave is spawning, unlike
    # MonstersWaves::Update which is not a per-frame dispatcher in this build.
    WAVE_PORTAL_ENTITY_SLOW_RVA = 0x852BD5
    # DoAction's local portal-count comparison.  Replacing this lets the
    # game's own creation loop produce each requested portal in one call.
    WAVE_PORTAL_COUNT_RVA = 0x5B6AAD
    # Cleanup continuation used by the relocated native portal-count check.
    # Keep this module-relative address explicit because the dispatcher
    # builder references it when reconstructing the original branch.
    WAVE_PORTAL_COUNT_CLEANUP_RVA = 0x5B6BA2
    # The native loop writes an index-based opening delay to every portal.
    # Clearing it for our queued wave makes all requested doors open together.
    WAVE_PORTAL_DELAY_RVA = 0x5B6B3E
    # This is the authoritative per-frame readiness test.  The update loop
    # subtracts dt from a queued entry's delay and only then instantiates its
    # portal, so this hook is needed in addition to the initial delay write.
    WAVE_PORTAL_READY_RVA = 0x5B9F83
    WAVE_PORTAL_POSITION_RVA = 0x5B6AE5
    WAVE_PORTAL_DO_ACTION_RVA = 0x5B67F0
    # This routine is part of the normal countdown/reset path. It is still
    # used by the original sunrise hook, but it does not terminate a live red
    # portal event.
    WAVE_PORTAL_CLOSE_RVA = 0x5B6190
    # The lifecycle close request is consumed only by the existing game-thread
    # controller.  It mirrors only the three writes confirmed in the game's
    # natural cleanup tail, and never jumps into that stack-frame-dependent
    # internal code block.
    WAVE_PORTAL_END_REQUEST_OFF = 0xD0
    WAVE_PORTAL_END_RESULT_OFF = 0xD4
    # Set only around the controller's synchronous Update(0.0f) call used to
    # finish a live portal.  The Update entry is itself detoured, so this
    # prevents that nested native call from re-entering any controller queue.
    WAVE_PORTAL_UPDATE_REENTRY_GUARD_OFF = 0xD8
    # The wave-update cave doubles as the safe main-thread dispatcher for one
    # LibraryBehaviour upgrade.  These offsets are deliberately outside the
    # portal request payload (+0x00..+0xCB), but inside its zeroed data page.
    LIBRARY_QUEUE_REQUEST_OFF = 0xE0
    LIBRARY_QUEUE_THIS_OFF = 0xE4
    LIBRARY_QUEUE_NODE_OFF = 0xE8
    LIBRARY_QUEUE_RESULT_OFF = 0xEC
    # 魔法快捷调用也使用同一个游戏更新线程。收集魔法必须经由游戏的
    # ResourceSlot 调度器，不能直接调用 MCollect 的底层实体函数。
    MAGIC_QUEUE_REQUEST_OFF = 0xF0
    MAGIC_QUEUE_ITEM_OFF = 0xF4
    MAGIC_QUEUE_X_OFF = 0xF8
    MAGIC_QUEUE_Y_OFF = 0xFC
    MAGIC_QUEUE_RESULT_OFF = 0x100
    # Optional one-call overrides for the full-map collect shortcut.  They
    # are applied and restored by the update-thread controller itself, never
    # left active while Python waits for the request.
    MAGIC_QUEUE_FLAGS_OFF = 0x104
    MAGIC_QUEUE_MANA_ADDR_OFF = 0x108
    MAGIC_QUEUE_MANA_SAVED_OFF = 0x10C
    MAGIC_QUEUE_RADIUS_ADDR_OFF = 0x110
    MAGIC_QUEUE_RADIUS_VALUE_OFF = 0x114
    MAGIC_QUEUE_RADIUS_SAVED_OFF = 0x118
    MAGIC_COLLECT_FLAG_NO_MANA = 0x01
    MAGIC_COLLECT_FLAG_RADIUS_OVERRIDE = 0x02
    MAGIC_COLLECT_FULL_MAP_MAX_RADIUS = 512

    # Recipe edits are also consumed by the game update thread.  A payload is
    # a compact 3×3 grid: every non-empty cell becomes one Recipe::Ingredient
    # {resource_array_index, position_1_to_9}.  The native vector grow helper
    # owns any reallocation, so its memory will later be freed by the game.
    RECIPE_QUEUE_REQUEST_OFF = 0x120
    RECIPE_QUEUE_ADDRESS_OFF = 0x124
    RECIPE_QUEUE_COUNT_OFF = 0x128
    RECIPE_QUEUE_ENTRIES_OFF = 0x130
    RECIPE_QUEUE_RESULT_OFF = 0x178
    RECIPE_VECTOR_EMPLACE_RVA = 0x342480
    RECIPE_VECTOR_EMPLACE_PREFIX = b"\x55\x8B\xEC\x83\xEC\x0C\x8B\x45\x08\x56\x8B\xF1"
    # Personal dwarf skills live in a 0x2C-record vector at Worker+0x888.
    # Removal is a bounded POD erase, while additions use Worker's own native
    # skill API on the game update thread.  Do not call the neighbouring vector
    # helper: it has a different ABI and was the source of the old crash.
    PERSONAL_SKILL_QUEUE_REQUEST_OFF = 0x180
    PERSONAL_SKILL_QUEUE_WORKER_OFF = 0x184
    PERSONAL_SKILL_QUEUE_NODE_OFF = 0x188
    PERSONAL_SKILL_QUEUE_OPERATION_OFF = 0x18C
    PERSONAL_SKILL_QUEUE_INDEX_OFF = 0x190
    PERSONAL_SKILL_QUEUE_RESULT_OFF = 0x194
    # ``INDEX`` carries an array index for removal.  For native additions it
    # carries the raw IEEE754 bits of the requested skill value, so no Python-
    # fabricated PersonalSkillRecord is ever inserted into a game vector.
    PERSONAL_SKILL_QUEUE_ADD = 1
    PERSONAL_SKILL_QUEUE_REMOVE = 2
    PERSONAL_SKILL_NATIVE_ADD_RVA = 0x68F8B0
    PERSONAL_SKILL_NATIVE_ADD_PREFIX = b"\x55\x8B\xEC\x83\xEC\x10\x8B\x51\x0C"
    PERSONAL_SKILL_MAX_PER_DWARF = 3
    # A raw write to CharLevels+0x10 bypasses the game-owned level-up event.
    # This request invokes CharLevels::AddExp on the real game update thread.
    XP_NATIVE_QUEUE_REQUEST_OFF = 0x1D0
    XP_NATIVE_QUEUE_THIS_OFF = 0x1D4
    XP_NATIVE_QUEUE_RAW_AMOUNT_OFF = 0x1D8
    XP_NATIVE_QUEUE_RESULT_OFF = 0x1DC
    XP_NATIVE_QUEUE_BEFORE_OFF = 0x1E0
    XP_NATIVE_QUEUE_AFTER_OFF = 0x1E4
    V1_CHAR_LEVELS_VTABLE_RVA = 0xBA2DA0
    V1_CHAR_LEVELS_ADD_EXP_RVA = 0x31CEE0
    V1_CHAR_LEVELS_ADD_EXP_PREFIX = b"\x55\x8B\xEC\x6A\xFF\x68"
    # LibraryBehaviour::Upgrade, called by the native skill/tech dispatcher.
    # This was present in the profile table but missing from Api, which made
    # rebuilding the controller fail immediately after a CE restart.
    V1_LIBRARY_UPGRADE_RVA = 0x5034E0
    # Direct pet generation is queued into the same verified game-update
    # dispatcher as recipes, skills and magic. The request carries only a
    # validated ASCII species name (max 15 bytes, matching the game's SSO
    # std::string layout); the dispatcher supplies the global dwarf-gate
    # spawn anchor and invokes the native factory on the game thread.
    PET_DIRECT_QUEUE_REQUEST_OFF = 0x220
    PET_DIRECT_QUEUE_NAME_OFF = 0x224
    PET_DIRECT_QUEUE_LENGTH_OFF = 0x234
    PET_DIRECT_QUEUE_RESULT_OFF = 0x238
    # Pet removal intentionally carries only one already-scanned live pet
    # address.  The injected dispatcher rechecks its two vtables immediately
    # before entering the game's own Pet death callback on the update thread.
    # It never frees memory, edits entity vectors, or changes PetHouse state.
    PET_REMOVE_QUEUE_REQUEST_OFF = 0x240
    PET_REMOVE_QUEUE_TARGET_OFF = 0x244
    PET_REMOVE_QUEUE_RESULT_OFF = 0x248
    PET_LIMIT_QUERY_REQUEST_OFF = 0x250
    PET_LIMIT_QUERY_TARGET_OFF = 0x254
    PET_LIMIT_QUERY_RESULT_OFF = 0x258
    PET_LIMIT_QUERY_STATUS_OFF = 0x25C
    # EnemyManager keeps entities during several death/despawn transitions.
    # Its own Counter() invokes IEnemyBase::Battle::IsAvailable before
    # counting.  Mirror that read-only predicate on the game update thread so
    # a still-linked but unavailable Pet is never rendered as a live pet.
    PET_AVAILABLE_QUERY_REQUEST_OFF = 0x260
    PET_AVAILABLE_QUERY_TARGET_OFF = 0x264
    PET_AVAILABLE_QUERY_RESULT_OFF = 0x268
    PET_AVAILABLE_QUERY_STATUS_OFF = 0x26C
    # A native shop purchase is deliberately limited to one currently-selected
    # product.  The queue runs on the game update thread and invokes the same
    # ShopDialog::OnEvent("buy") route as the visible button; it never changes
    # gold or inventory directly.
    SHOP_NATIVE_QUEUE_REQUEST_OFF = 0x280
    SHOP_NATIVE_QUEUE_DIALOG_OFF = 0x284
    SHOP_NATIVE_QUEUE_SOURCE_OFF = 0x288
    SHOP_NATIVE_QUEUE_RESULT_OFF = 0x28C
    SHOP_NATIVE_QUEUE_DONE_OFF = 0x290
    SHOP_NATIVE_QUEUE_SOURCE_STATE_OFF = 0x294
    SHOP_NATIVE_EVENT_OFF = 0x2A0
    SHOP_NATIVE_EVENT_AUX_OFF = 0x330
    # Special world entities (dragon eggs, Pandora chests, etc.) are ordinary
    # ItemEntity instances owned by World's independent-object vector. The
    # queue carries a validated resource-table Item* and a map-cell position;
    # the game-thread handler calls World::AddItemInstance so constructors,
    # component registration and save bookkeeping remain game-owned.
    SPECIAL_ENTITY_QUEUE_REQUEST_OFF = 0x350
    SPECIAL_ENTITY_QUEUE_ITEM_OFF = 0x354
    SPECIAL_ENTITY_QUEUE_X_OFF = 0x358
    SPECIAL_ENTITY_QUEUE_Y_OFF = 0x35C
    SPECIAL_ENTITY_QUEUE_RESULT_OFF = 0x360
    SPECIAL_ENTITY_QUEUE_STATUS_OFF = 0x364
    # Native special-entity removal.  Python resolves an exact live object
    # from both World and GameObjectManager.  The game thread then rechecks
    # its Item* and vtable before GameObjectManager::UnRegister performs the
    # complete lifecycle (registration, components and presentation).
    SPECIAL_ENTITY_DELETE_QUEUE_REQUEST_OFF = 0x4A0
    SPECIAL_ENTITY_DELETE_QUEUE_TARGET_OFF = 0x4A4
